import assert from "node:assert/strict";
import test from "node:test";

import { createStore } from "./storage.mjs";

class LocalStorageMock {
  #map = new Map();

  clear() {
    this.#map.clear();
  }

  getItem(key) {
    return this.#map.has(key) ? this.#map.get(key) : null;
  }

  setItem(key, value) {
    this.#map.set(key, String(value));
  }

  removeItem(key) {
    this.#map.delete(key);
  }
}

test.beforeEach(() => {
  globalThis.localStorage = new LocalStorageMock();
});

test.afterEach(() => {
  delete globalThis.localStorage;
});

test("createStore persists and recovers values from versioned localStorage keys", () => {
  const storageKey = "viaje-en-familia:v1:areas/trips";
  const value = { area: "trips", items: ["bus", "hotel"], ready: true };

  globalThis.localStorage.setItem(storageKey, JSON.stringify(value));

  const store = createStore("areas/trips");

  assert.deepEqual(store.get(), value);
  assert.equal(globalThis.localStorage.getItem(storageKey), JSON.stringify(value));
});

test("createStore notifies subscribers on set and supports unsubscribe", () => {
  const store = createStore("areas/notes");
  const calls = [];

  const unsubscribe = store.subscribe((value) => {
