+import assert from "node:assert/strict";
+import test from "node:test";
+
+import { createFavoritosStore } from "./favoritos.mjs";
+
+class LocalStorageMock {
+  #map = new Map();
+
+  clear() {
+    this.#map.clear();
+  }
+
+  getItem(key) {
+    return this.#map.has(key) ? this.#map.get(key) : null;
+  }
+
+  setItem(key, value) {
+    this.#map.set(key, String(value));
+  }
+
+  removeItem(key) {
+    this.#map.delete(key);
+  }
+}
+
+test.beforeEach(() => {
+  globalThis.localStorage = new LocalStorageMock();
+});
+
+test.afterEach(() => {
+  delete globalThis.localStorage;
+});
+
+test("favoritos marca lugares y actividades en una sola lista persistida", () => {
+  const store = createFavoritosStore();
+  const lugar = { id: "museo", tipo: "lugar", nombre: "Museo de los Ninos" };
+  const actividad = { id: "picnic", tipo: "actividad", nombre: "Picnic en la plaza" };
+
+  store.marcarFavorito(lugar);
+  store.marcarFavorito(actividad);
+  store.marcarFavorito({ ...lugar });
+
+  assert.deepEqual(store.listarFavoritos(), [lugar, actividad]);
+  assert.equal(store.esFavorito(lugar), true);
+  assert.equal(store.esFavorito(actividad), true);
+  assert.equal(
+    globalThis.localStorage.getItem("viaje-en-familia:v1:recuerdos/favoritos"),
+    JSON.stringify([lugar, actividad])
+  );
+});
+
+test("favoritos desmarca un elemento sin afectar al resto", () => {
+  const store = createFavoritosStore();
+  const lugar = { id: "parque", tipo: "lugar", nombre: "Parque Central" };
+  const actividad = { id: "bicicleta", tipo: "actividad", nombre: "Paseo en bicicleta" };
+
+  store.marcarFavorito(lugar);
+  store.marcarFavorito(actividad);
+
+  assert.equal(store.desmarcarFavorito({ id: "parque", tipo: "lugar" }), true);
+  assert.deepEqual(store.listarFavoritos(), [actividad]);
+  assert.equal(store.esFavorito(lugar), false);
+  assert.equal(store.esFavorito(actividad), true);
+});
+

