+import { createStore } from "../../storage/storage.mjs";
+
+const notasStore = createStore("recuerdos/notas");
+
+function leerNotas() {
+  const notas = notasStore.get();
+  return Array.isArray(notas) ? notas : [];
+}
+
+function escribirNotas(notas) {
+  notasStore.set(notas);
+  return notas;
+}
+
+function validarTexto(texto) {
+  if (typeof texto !== "string" || texto.trim() === "") {
+    throw new TypeError("texto is required");
+  }
+
+  return texto.trim();
+}
+
+function validarAsociacion({ diaId, paradaId }) {
+  const tieneDia = typeof diaId === "string" && diaId.trim() !== "";
+  const tieneParada = typeof paradaId === "string" && paradaId.trim() !== "";
+
+  if (tieneDia === tieneParada) {
+    throw new TypeError("nota must be associated with a diaId or a paradaId");
+  }
+
+  return {
+    diaId: tieneDia ? diaId : undefined,
+    paradaId: tieneParada ? paradaId : undefined
+  };
+}
+
+function normalizarNota(nota) {
+  const texto = validarTexto(nota.texto);
+  const asociacion = validarAsociacion(nota);
+
+  return {
+    id: typeof nota.id === "string" && nota.id.trim() !== "" ? nota.id : crypto.randomUUID(),
+    texto,
+    diaId: asociacion.diaId,
+    paradaId: asociacion.paradaId,
+    creadoEn: typeof nota.creadoEn === "string" && nota.creadoEn.trim() !== "" ? nota.creadoEn : new Date().toISOString()
+  };
+}
+
+export function createNotasStore() {
+  return notasStore;
+}
+
+export const crearNotasStore = createNotasStore;
+
+export function obtenerNotas() {
+  return [...leerNotas()];
+}
+
+export function guardarNota(nota) {
+  const nuevaNota = normalizarNota(nota);
+  const notas = leerNotas();
+  const indice = notas.findIndex(({ id }) => id === nuevaNota.id);
+
+  if (indice === -1) {
+    return escribirNotas([...notas, nuevaNota]);
+  }
+
+  const copia = [...notas];
+  copia[indice] = nuevaNota;
+  return escribirNotas(copia);
+}
+
+export const agregarNota = guardarNota;
+
+export function obtenerNotasDeDia(diaId) {
+  if (typeof diaId !== "string" || diaId.trim() === "") {
+    throw new TypeError("diaId is required");
+  }
+
+  return leerNotas().filter((nota) => nota.diaId === diaId);
+}
+
+export const listarNotasPorDia = obtenerNotasDeDia;
+
+export function obtenerNotasDeParada(paradaId) {
+  if (typeof paradaId !== "string" || paradaId.trim() === "") {
+    throw new TypeError("paradaId is required");
+  }
+
+  return leerNotas().filter((nota) => nota.paradaId === paradaId);
+}
+
+export const listarNotasPorParada = obtenerNotasDeParada;
+
+export function eliminarNota(id) {
+  if (typeof id !== "string" || id.trim() === "") {
+    throw new TypeError("id is required");
+  }
+
+  const notas = leerNotas();
+  const filtradas = notas.filter((nota) => nota.id !== id);
+
+  if (filtradas.length !== notas.length) {
+    escribirNotas(filtradas);
+  }
+
+  return filtradas;
+}
