+import { createStore } from "../../storage/storage.mjs";
+
+const FAVORITOS_KEY = "recuerdos/favoritos";
+
+function cloneFavorito(favorito) {
+  return { ...favorito };
+}
+
+function toText(value) {
+  return value === undefined || value === null ? "" : String(value).trim();
+}
+
+function getFavoritoId(favorito) {
+  return toText(
+    favorito.id ??
+      favorito.slug ??
+      favorito.clave ??
+      favorito.key ??
+      favorito.nombre ??
+      favorito.name ??
+      favorito.titulo ??
+      favorito.title
+  );
+}
+
+function getFavoritoTipo(favorito) {
+  return toText(favorito.tipo ?? favorito.type ?? favorito.kind ?? favorito.categoria);
+}
+
+function getFavoritoClave(favorito) {
+  const id = getFavoritoId(favorito);
+  const tipo = getFavoritoTipo(favorito);
+
+  if (!id) {
+    throw new TypeError("favorito must include an identifier");
+  }
+
+  return tipo ? `${tipo}:${id}` : id;
+}
+
+function normalizeLista(value) {
+  return Array.isArray(value) ? value.map(cloneFavorito) : [];
+}
+
+function sameFavorito(a, b) {
+  return getFavoritoClave(a) === getFavoritoClave(b);
+}
+
+export function createFavoritosStore() {
+  const store = createStore(FAVORITOS_KEY);
+
+  function get() {
+    return normalizeLista(store.get());
+  }
+
+  function set(value) {
+    const next = normalizeLista(value);
+    store.set(next);
+    return next;
+  }
+
+  function subscribe(listener) {
+    return store.subscribe((value) => {
+      listener(normalizeLista(value));
+    });
+  }
+
+  function listarFavoritos() {
+    return get();
+  }
+
+  function esFavorito(favorito) {
+    const clave = getFavoritoClave(favorito);
+    return get().some((item) => getFavoritoClave(item) === clave);
+  }
+
+  function marcarFavorito(favorito) {
+    const favoritos = get();
+    if (favoritos.some((item) => sameFavorito(item, favorito))) {
+      return favoritos.find((item) => sameFavorito(item, favorito));
+    }
+
+    const next = [...favoritos, cloneFavorito(favorito)];
+    store.set(next);
+    return next[next.length - 1];
+  }
+
+  function desmarcarFavorito(favorito) {
+    const favoritos = get();
+    const next = favoritos.filter((item) => !sameFavorito(item, favorito));
+    if (next.length === favoritos.length) {
+      return false;
+    }
+
+    store.set(next);
+    return true;
+  }
+
+  return {
+    get,
+    set,
+    subscribe,
+    listarFavoritos,
+    marcarFavorito,
+    desmarcarFavorito,
+    esFavorito
+  };
+}
+
+export const createFavoritos = createFavoritosStore;
+
