+
+export const FILTROS_EQUIPAJE = Object.freeze({
+  TODOS: "todos",
+  PENDIENTES: "pendientes",
+  COMPLETADOS: "completados"
+});
+
+const STORE_KEY = "organizacion/equipaje";
+const VALID_FILTERS = new Set(Object.values(FILTROS_EQUIPAJE));
+
+function createId() {
+  if (globalThis.crypto && typeof globalThis.crypto.randomUUID === "function") {
+    return globalThis.crypto.randomUUID();
+  }
+
+  return `equipaje-${Date.now()}-${Math.random().toString(16).slice(2)}`;
+}
+
+function normalizeFilter(value) {
+  return VALID_FILTERS.has(value) ? value : FILTROS_EQUIPAJE.TODOS;
+}
+
+function normalizeItem(item) {
+  if (!item || typeof item !== "object") {
+    return null;
+  }
+
+  const id = typeof item.id === "string" ? item.id : "";
+  const nombre = typeof item.nombre === "string" ? item.nombre.trim() : "";
+  if (!id || !nombre) {
+    return null;
+  }
+
+  return {
+    id,
+    nombre,
+    completado: Boolean(item.completado)
+  };
+}
+
+function normalizeState(value) {
+  const source = value && typeof value === "object" ? value : {};
+  const items = Array.isArray(source.items)
+    ? source.items.map(normalizeItem).filter(Boolean)
+    : [];
+
+  return {
+    items,
+    filtro: normalizeFilter(source.filtro)
+  };
+}
+
+export function filtrarEquipaje(items, filtro = FILTROS_EQUIPAJE.TODOS) {
+  const collection = Array.isArray(items) ? items.map(normalizeItem).filter(Boolean) : [];
+  switch (normalizeFilter(filtro)) {
+    case FILTROS_EQUIPAJE.PENDIENTES:
+      return collection.filter((item) => !item.completado);
+    case FILTROS_EQUIPAJE.COMPLETADOS:
+      return collection.filter((item) => item.completado);
+    default:
+      return collection;
+  }
+}
+
+export function calcularProgresoEquipaje(items) {
+  const collection = Array.isArray(items) ? items.map(normalizeItem).filter(Boolean) : [];
+  const total = collection.length;
+  const completados = collection.filter((item) => item.completado).length;
+  const pendientes = total - completados;
+  const porcentaje = total === 0 ? 0 : Math.round((completados / total) * 100);
+
+  return {
+    total,
+    completados,
+    pendientes,
+    porcentaje
+  };
+}
+
+export function crearChecklistEquipaje() {
+  const store = createStore(STORE_KEY);
+
+  function readState() {
+    return normalizeState(store.get());
+  }
+
+  function writeState(nextState) {
+    const normalized = normalizeState(nextState);
+    store.set(normalized);
+    return normalized;
+  }
+
+  return {
+    get() {
+      return readState();
+    },
+    subscribe(listener) {
+      return store.subscribe(listener);
+    },
+    agregarEquipaje(nombre) {
+      const texto = typeof nombre === "string" ? nombre.trim() : "";
+      if (!texto) {
+        return null;
+      }
+
+      const state = readState();
+      const item = {
+        id: createId(),
+        nombre: texto,
+        completado: false
+      };
+
+      writeState({
+        ...state,
+        items: [...state.items, item]
+      });
+
+      return item;
+    },
+    completarEquipaje(id, completado = true) {
+      if (typeof id !== "string" || !id) {
+        return null;
+      }
+
+      const state = readState();
+      let changed = false;
+      const items = state.items.map((item) => {
+        if (item.id !== id) {
+          return item;
+        }
+
+        changed = true;
+        return {
+          ...item,
+          completado: Boolean(completado)
+        };
+      });
+
+      if (!changed) {
+        return null;
+      }
+
+      writeState({
+        ...state,
+        items
+      });
+
+      return items.find((item) => item.id === id) ?? null;
+    },
+    filtrarEquipaje(filtro = FILTROS_EQUIPAJE.TODOS) {
+      const state = readState();
+      const normalizedFilter = normalizeFilter(filtro);
+      writeState({
