+  });
+});
+
+test("resumirPresupuesto marca sobregasto cuando los gastos superan el total", () => {
+  const resumen = resumirPresupuesto({
+    total: 200,
+    gastos: [
+      { categoria: "Excursiones", gasto: 125 },
+      { categoria: "Comida", gasto: 95 }
+    ]
+  });
+
+  assert.equal(resumen.gastado, 220);
+  assert.equal(resumen.disponible, -20);
+  assert.equal(resumen.estadoVisual.clave, ESTADOS_PRESUPUESTO.sobregasto);
+  assert.equal(resumen.estadoVisual.tono, "critico");
+});
+
+test("guardarPresupuesto persiste bajo la clave versionada y obtenerPresupuestoGuardado lo recupera", () => {
+  const store = crearPresupuestoStore();
+  const resumenGuardado = guardarPresupuesto({
+    total: 1000,
+    gastos: [
+      { categoria: "Alojamiento", gasto: 650 },
+      { categoria: "Comida", gasto: 150 }
+    ]
+  });
+
+  assert.equal(globalThis.localStorage.getItem("viaje-en-familia:v1:organizacion/presupuesto"), JSON.stringify({
+    total: 1000,
+    gastos: [
+      { categoria: "Alojamiento", gasto: 650 },
+      { categoria: "Comida", gasto: 150 }
+    ]
+  }));
+  assert.deepEqual(obtenerPresupuestoGuardado(), resumenGuardado);
+  assert.deepEqual(store.get(), {
+    total: 1000,
+    gastos: [
+      { categoria: "Alojamiento", gasto: 650 },
+      { categoria: "Comida", gasto: 150 }
+    ]
+  });
+});

