+  if (disponible === 0) {
+    return {
+      clave: ESTADOS_PRESUPUESTO.agotado,
+      etiqueta: "Presupuesto agotado",
+      tono: "advertencia"
+    };
+  }
+
+  const porcentajeGastado = gastado / total;
+  if (porcentajeGastado >= 0.8) {
+    return {
+      clave: ESTADOS_PRESUPUESTO.advertencia,
+      etiqueta: "Cerca del límite",
+      tono: "advertencia"
+    };
+  }
+
+  return {
+    clave: ESTADOS_PRESUPUESTO.controlado,
+    etiqueta: "En control",
+    tono: "positivo"
+  };
+}
+
+export function resumirPresupuesto(presupuesto = {}) {
+  const total = toNumber(presupuesto.total);
+  const gastos = Array.isArray(presupuesto.gastos) ? presupuesto.gastos : [];
+  const gastosPorCategoria = agruparGastosPorCategoria(gastos);
+  const gastado = gastosPorCategoria.reduce((acumulado, gasto) => acumulado + gasto.gasto, 0);
+  const disponible = total - gastado;
+  const porcentajeGastado = total > 0 ? gastado / total : 0;
+  const porcentajeDisponible = total > 0 ? disponible / total : 0;
+
+  return {
+    total,
+    gastado,
+    disponible,
+    porcentajeGastado,
+    porcentajeDisponible,
+    gastosPorCategoria,
+    estadoVisual: obtenerEstadoPresupuesto({ total, gastado, disponible })
+  };
+}
+
+export function crearPresupuestoStore() {
+  return createStore(STORAGE_KEY);
+}
+
+export function guardarPresupuesto(presupuesto) {
+  const store = crearPresupuestoStore();
+  const siguiente = {
+    total: toNumber(presupuesto?.total),
+    gastos: Array.isArray(presupuesto?.gastos)
+      ? presupuesto.gastos.map((gasto) => ({
+          categoria: toCategoria(gasto?.categoria),
+          gasto: toGasto(gasto?.gasto)
+        }))
+      : []
+  };
+
+  store.set(siguiente);
+  return resumirPresupuesto(siguiente);
+}
+
+export function obtenerPresupuestoGuardado() {
+  const store = crearPresupuestoStore();
+  const presupuesto = store.get();
+  return resumirPresupuesto(presupuesto ?? {});
+}
