+import { createStore } from "../../storage/storage.mjs";
+
+function getStore() {
+  return createStore("itinerary/paradas");
+}
+
+function readParadas() {
+  const paradas = getStore().get();
+  return Array.isArray(paradas) ? paradas : [];
+}
+
+function writeParadas(paradas) {
+  getStore().set(paradas);
+  return paradas;
+}
+
+function createId() {
+  const crypto = globalThis.crypto;
+  if (crypto && typeof crypto.randomUUID === "function") {
+    return crypto.randomUUID();
+  }
+
+  return `parada-${Date.now()}-${Math.random().toString(16).slice(2)}`;
+}
+
+function toParada(value, existing = {}) {
+  if (!value || typeof value !== "object") {
+    throw new TypeError("parada must be an object");
+  }
+
+  const {
+    id = existing.id ?? createId(),
+    nombre,
+    fechaInicio,
+    fechaFin,
+    descripcion
+  } = { ...existing, ...value };
+
+  if (typeof nombre !== "string" || nombre.trim() === "") {
+    throw new TypeError("parada.nombre must be a non-empty string");
+  }
+
+  if (typeof fechaInicio !== "string" || fechaInicio.trim() === "") {
+    throw new TypeError("parada.fechaInicio must be a non-empty string");
+  }
+
+  if (typeof fechaFin !== "string" || fechaFin.trim() === "") {
+    throw new TypeError("parada.fechaFin must be a non-empty string");
+  }
+
+  if (typeof descripcion !== "string") {
+    throw new TypeError("parada.descripcion must be a string");
+  }
+
+  return {
+    id,
+    nombre,
+    fechaInicio,
+    fechaFin,
+    descripcion
+  };
+}
+
+function normalizeId(input) {
+  if (typeof input === "string") {
+    return input;
+  }
+
+  if (input && typeof input === "object" && typeof input.id === "string") {
+    return input.id;
+  }
+
+  throw new TypeError("id must be a string");
+}
+
+function normalizeReorderIds(value) {
+  if (!Array.isArray(value)) {
+    throw new TypeError("reorderParadas expects an array");
+  }
+
+  return value.map((item) => normalizeId(item));
+}
+
+export function listParadas() {
+  return readParadas().slice();
+}
+
+export function addParada(parada) {
+  const created = toParada(parada);
+  writeParadas([...readParadas(), created]);
+  return created;
+}
+
+export function updateParada(target, changes = {}) {
+  const id = normalizeId(target);
+  const current = readParadas();
+  const index = current.findIndex((parada) => parada.id === id);
+
+  if (index === -1) {
+    throw new RangeError(`parada not found: ${id}`);
+  }
+
+  const updated = toParada(
+    typeof target === "object" && target !== null ? { ...target, ...changes, id } : { ...changes, id },
+    current[index]
+  );
+
+  const next = current.slice();
+  next[index] = updated;
+  writeParadas(next);
+  return updated;
+}
+
+export function removeParada(target) {
+  const id = normalizeId(target);
+  const next = readParadas().filter((parada) => parada.id !== id);
+  writeParadas(next);
+}
+
+export function reorderParadas(order) {
+  const ids = normalizeReorderIds(order);
+  const current = readParadas();
+  const byId = new Map(current.map((parada) => [parada.id, parada]));
+  const seen = new Set();
+
+  const next = [];
+  for (const id of ids) {
+    const parada = byId.get(id);
+    if (!parada) {
+      throw new RangeError(`parada not found: ${id}`);
+    }
+    if (!seen.has(id)) {
+      next.push(parada);
+      seen.add(id);
+    }
+  }
+
+  for (const parada of current) {
+    if (!seen.has(parada.id)) {
+      next.push(parada);
+    }
+  }
+
+  writeParadas(next);
+  return next;
+}
