@@ -0,0 +1,116 @@
+import assert from "node:assert/strict";
+import test from "node:test";
+
+import {
+  FILTROS_EQUIPAJE,
+  calcularProgresoEquipaje,
+  crearChecklistEquipaje,
+  filtrarEquipaje
+} from "./equipaje.mjs";
+
+class LocalStorageMock {
+  #map = new Map();
+
+  clear() {
+    this.#map.clear();
+  }
+
+  getItem(key) {
+    return this.#map.has(key) ? this.#map.get(key) : null;
+  }
+
+  setItem(key, value) {
+    this.#map.set(key, String(value));
+  }
+
+  removeItem(key) {
+    this.#map.delete(key);
+  }
+}
+
+test.beforeEach(() => {
+  globalThis.localStorage = new LocalStorageMock();
+});
+
+test.afterEach(() => {
+  delete globalThis.localStorage;
+});
+
+test("agrega equipaje y persiste el checklist en localStorage versionado", () => {
+  const checklist = crearChecklistEquipaje();
+
+  const item = checklist.agregarEquipaje(" Pasaporte ");
+  const state = checklist.get();
+
+  assert.equal(item.nombre, "Pasaporte");
+  assert.equal(item.completado, false);
+  assert.equal(state.items.length, 1);
+  assert.deepEqual(state.items[0], item);
+  assert.equal(
+    globalThis.localStorage.getItem("viaje-en-familia:v1:organizacion/equipaje"),
+    JSON.stringify(state)
+  );
+});
+
+test("completa, filtra y calcula el progreso total del equipaje", () => {
+  const checklist = crearChecklistEquipaje();
+
+  const mochila = checklist.agregarEquipaje("Mochila");
+  const cargador = checklist.agregarEquipaje("Cargador");
+
+  assert.equal(checklist.completarEquipaje(mochila.id)?.completado, true);
+  assert.equal(checklist.completarEquipaje("no-existe"), null);
+
+  const filtradosCompletados = checklist.filtrarEquipaje(FILTROS_EQUIPAJE.COMPLETADOS);
+  assert.deepEqual(filtradosCompletados, [checklist.get().items[0]]);
+  assert.deepEqual(checklist.obtenerEquipajeFiltrado(), filtradosCompletados);
+
+  const progreso = checklist.obtenerProgresoEquipaje();
+  assert.deepEqual(progreso, {
+    total: 2,
+    completados: 1,
+    pendientes: 1,
+    porcentaje: 50
+  });
+
+  assert.deepEqual(
+    filtrarEquipaje(
+      [
+        { id: "1", nombre: "Mochila", completado: true },
+        { id: "2", nombre: "Cargador", completado: false }
+      ],
+      FILTROS_EQUIPAJE.PENDIENTES
+    ),
+    [{ id: "2", nombre: "Cargador", completado: false }]
+  );
+
+  assert.deepEqual(calcularProgresoEquipaje(checklist.get().items), progreso);
+});
+
+test("rehidrata el checklist desde el storage compartido", () => {
+  const storedState = {
+    items: [
+      { id: "a", nombre: "Toalla", completado: true },
+      { id: "b", nombre: "Pijama", completado: false }
+    ],
+    filtro: FILTROS_EQUIPAJE.PENDIENTES
+  };
+
+  globalThis.localStorage.setItem(
+    "viaje-en-familia:v1:organizacion/equipaje",
+    JSON.stringify(storedState)
+  );
+
+  const checklist = crearChecklistEquipaje();
+
+  assert.deepEqual(checklist.get(), storedState);
+  assert.deepEqual(checklist.obtenerEquipajeFiltrado(), [
+    { id: "b", nombre: "Pijama", completado: false }
+  ]);
+  assert.deepEqual(checklist.obtenerProgresoEquipaje(), {
+    total: 2,
+    completados: 1,
+    pendientes: 1,
+    porcentaje: 50
+  });
+});

