+import assert from "node:assert/strict";
+import test from "node:test";
+
+import {
+  addParada,
+  listParadas,
+  removeParada,
+  reorderParadas,
+  updateParada
+} from "./paradas.mjs";
+
+class LocalStorageMock {
+  #map = new Map();
+
+  clear() {
+    this.#map.clear();
+  }
+
+  getItem(key) {
+    return this.#map.has(key) ? this.#map.get(key) : null;
+  }
+
+  setItem(key, value) {
+    this.#map.set(key, String(value));
+  }
+
+  removeItem(key) {
+    this.#map.delete(key);
+  }
+}
+
+test.beforeEach(() => {
+  globalThis.localStorage = new LocalStorageMock();
+});
+
+test.afterEach(() => {
+  delete globalThis.localStorage;
+});
+
+test("listParadas and addParada create and persist paradas with nombre, fechaInicio, fechaFin and descripcion", () => {
+  assert.deepEqual(listParadas(), []);
+
+  const created = addParada({
+    id: "madrid",
+    nombre: "Madrid",
+    fechaInicio: "2026-09-01",
+    fechaFin: "2026-09-03",
+    descripcion: "Llegada y paseo"
+  });
+
+  assert.deepEqual(created, {
+    id: "madrid",
+    nombre: "Madrid",
+    fechaInicio: "2026-09-01",
+    fechaFin: "2026-09-03",
+    descripcion: "Llegada y paseo"
+  });
+  assert.deepEqual(listParadas(), [created]);
+  assert.equal(
+    globalThis.localStorage.getItem("viaje-en-familia:v1:itinerary/paradas"),
+    JSON.stringify([created])
+  );
+});
+
+test("updateParada edits an existing parada without changing its id", () => {
+  addParada({
+    id: "barcelona",
+    nombre: "Barcelona",
+    fechaInicio: "2026-09-04",
+    fechaFin: "2026-09-06",
+    descripcion: "Costa y arquitectura"
+  });
+
+  const updated = updateParada({
+    id: "barcelona",
+    nombre: "Barcelona centro",
+    descripcion: "Museos y comida"
+  });
+
+  assert.deepEqual(updated, {
+    id: "barcelona",
+    nombre: "Barcelona centro",
+    fechaInicio: "2026-09-04",
+    fechaFin: "2026-09-06",
+    descripcion: "Museos y comida"
+  });
+  assert.deepEqual(listParadas(), [updated]);
+});
+
+test("removeParada deletes the requested parada and returns it", () => {
+  const first = addParada({
+    id: "cordoba",
+    nombre: "Córdoba",
+    fechaInicio: "2026-09-07",
+    fechaFin: "2026-09-08",
+    descripcion: "Escala corta"
+  });
+  const second = addParada({
+    id: "sevilla",
+    nombre: "Sevilla",
+    fechaInicio: "2026-09-09",
+    fechaFin: "2026-09-11",
+    descripcion: "Centro histórico"
+  });
+
+  const removed = removeParada("cordoba");
+
+  assert.deepEqual(removed, first);
+  assert.deepEqual(listParadas(), [second]);
+  assert.equal(
+    globalThis.localStorage.getItem("viaje-en-familia:v1:itinerary/paradas"),
+    JSON.stringify([second])
+  );
+});
+
+test("reorderParadas reorders by ids and by indexes", () => {
+  const first = addParada({
+    id: "uno",
+    nombre: "Uno",
+    fechaInicio: "2026-10-01",
+    fechaFin: "2026-10-02",
+    descripcion: "Primera"
+  });
+  const second = addParada({
+    id: "dos",
+    nombre: "Dos",
+    fechaInicio: "2026-10-03",
+    fechaFin: "2026-10-04",
+    descripcion: "Segunda"
+  });
+  const third = addParada({
+    id: "tres",
+    nombre: "Tres",
+    fechaInicio: "2026-10-05",
+    fechaFin: "2026-10-06",
+    descripcion: "Tercera"
+  });
+
+  assert.deepEqual(reorderParadas(["tres", first.id, second.id]), [third, first, second]);
+  assert.deepEqual(reorderParadas({ fromIndex: 0, toIndex: 2 }), [first, second, third]);
+  assert.deepEqual(reorderParadas(2, 0), [third, first, second]);
+});

