index 0000000000000000000000000000000000000000..5babf810be158ce0f78efd73f13441957ad74ac9
--- /dev/null
+++ b/src/itinerary/paradas/paradas.mjs
@@ -0,0 +1,189 @@
+import { createStore } from "../../storage/storage.mjs";
+
+const store = createStore("itinerary/paradas");
+
+function cloneParada(parada) {
+  return {
+    id: parada.id,
+    nombre: parada.nombre,
+    fechaInicio: parada.fechaInicio,
+    fechaFin: parada.fechaFin,
+    descripcion: parada.descripcion
+  };
+}
+
+function isParada(value) {
+  return value !== null && typeof value === "object" && !Array.isArray(value);
+}
+
+function normalizeParada(parada) {
+  if (!isParada(parada)) {
+    throw new TypeError("parada must be an object");
+  }
+
+  return {
+    id: parada.id ?? createId(),
+    nombre: parada.nombre ?? "",
+    fechaInicio: parada.fechaInicio ?? "",
+    fechaFin: parada.fechaFin ?? "",
+    descripcion: parada.descripcion ?? ""
+  };
+}
+
+function createId() {
+  if (typeof crypto !== "undefined" && typeof crypto.randomUUID === "function") {
+    return crypto.randomUUID();
+  }
+
+  return `parada-${Date.now()}-${Math.random().toString(16).slice(2)}`;
+}
+
+function readParadas() {
+  const current = store.get();
+  if (!Array.isArray(current)) {
+    return [];
+  }
+
+  return current.filter(isParada).map(cloneParada);
+}
+
+function writeParadas(paradas) {
+  store.set(paradas.map(cloneParada));
+}
+
+function resolveId(value) {
+  if (isParada(value)) {
+    return value.id;
+  }
+
+  return value;
+}
+
+function moveByIndex(paradas, fromIndex, toIndex) {
+  if (!Number.isInteger(fromIndex) || !Number.isInteger(toIndex)) {
+    return paradas;
+  }
+
+  if (fromIndex < 0 || fromIndex >= paradas.length) {
+    return paradas;
+  }
+
+  const next = paradas.slice();
+  const [item] = next.splice(fromIndex, 1);
+  const targetIndex = Math.max(0, Math.min(toIndex, next.length));
+  next.splice(targetIndex, 0, item);
+  return next;
+}
+
+function reorderByIds(paradas, order) {
+  const ids = order.map(resolveId).filter((id) => id !== undefined && id !== null);
+  if (ids.length === 0) {
+    return paradas;
+  }
+
+  const seen = new Set();
+  const next = [];
+
+  for (const id of ids) {
+    if (seen.has(id)) {
+      continue;
+    }
+
+    const found = paradas.find((parada) => parada.id === id);
+    if (found) {
+      next.push(found);
+      seen.add(id);
+    }
+  }
+
+  for (const parada of paradas) {
+    if (!seen.has(parada.id)) {
+      next.push(parada);
+    }
+  }
+
+  return next;
+}
+
+export function listParadas() {
+  return readParadas();
+}
+
+export function addParada(parada) {
+  const nextParada = normalizeParada(parada);
+  const paradas = readParadas();
+  paradas.push(nextParada);
+  writeParadas(paradas);
+  return cloneParada(nextParada);
+}
+
+export function updateParada(paradaOrId, changes) {
+  const update = isParada(paradaOrId)
+    ? paradaOrId
+    : { id: paradaOrId, ...(isParada(changes) ? changes : {}) };
+  const id = update.id;
+
+  if (id === undefined || id === null) {
+    return undefined;
+  }
+
+  const paradas = readParadas();
+  const index = paradas.findIndex((parada) => parada.id === id);
+  if (index === -1) {
+    return undefined;
+  }
+
+  const nextParada = {
+    ...paradas[index],
+    ...update,
+    id
+  };
+
+  paradas[index] = nextParada;
+  writeParadas(paradas);
+  return cloneParada(nextParada);
+}
+
+export function removeParada(paradaOrId) {
+  const id = resolveId(paradaOrId);
+  if (id === undefined || id === null) {
+    return undefined;
+  }
+
+  const paradas = readParadas();
+  const index = paradas.findIndex((parada) => parada.id === id);
+  if (index === -1) {
+    return undefined;
+  }
+
+  const [removed] = paradas.splice(index, 1);
+  writeParadas(paradas);
+  return cloneParada(removed);
+}
+
+export function reorderParadas(firstArg, secondArg) {
+  const paradas = readParadas();
+
+  if (Array.isArray(firstArg)) {
+    const next = reorderByIds(paradas, firstArg);
+    writeParadas(next);
+    return next.map(cloneParada);
+  }
+
+  if (isParada(firstArg) && Array.isArray(secondArg)) {
+    const next = reorderByIds(paradas, secondArg);
+    writeParadas(next);
+    return next.map(cloneParada);
+  }
+
+  if (typeof firstArg === "object" && firstArg !== null) {
+    const { fromIndex, toIndex } = firstArg;
+    const next = moveByIndex(paradas, fromIndex, toIndex);
+    writeParadas(next);
+    return next.map(cloneParada);
+  }
+
+  const next = moveByIndex(paradas, firstArg, secondArg);
+  writeParadas(next);
+  return next.map(cloneParada);
+}
diff --git a/src/itinerary/paradas/paradas.test.mjs b/src/itinerary/paradas/paradas.test.mjs
new file mode 100644
index 0000000000000000000000000000000000000000..39f5a42e153ef82dd0b8d360597c6cb2e201778b
--- /dev/null
+++ b/src/itinerary/paradas/paradas.test.mjs
@@ -0,0 +1,142 @@
+import assert from "node:assert/strict";
+import test from "node:test";
+
+import {
+  addParada,
+  listParadas,
+  removeParada,
+  reorderParadas,
+  updateParada
+} from "./paradas.mjs";
+
+class LocalStorageMock {
+  #map = new Map();
+
+  clear() {
+    this.#map.clear();
+  }
+
+  getItem(key) {
+    return this.#map.has(key) ? this.#map.get(key) : null;
+  }
+
+  setItem(key, value) {
+    this.#map.set(key, String(value));
+  }
+
+  removeItem(key) {
+    this.#map.delete(key);
+  }
+}
+
+test.beforeEach(() => {
+  globalThis.localStorage = new LocalStorageMock();
+});
+
+test.afterEach(() => {
+  delete globalThis.localStorage;
+});
+
+test("listParadas and addParada create and persist paradas with nombre, fechaInicio, fechaFin and descripcion", () => {
+  assert.deepEqual(listParadas(), []);
+
+  const created = addParada({
+    id: "madrid",
+    nombre: "Madrid",
+    fechaInicio: "2026-09-01",
+    fechaFin: "2026-09-03",
+    descripcion: "Llegada y paseo"
+  });
+
+  assert.deepEqual(created, {
+    id: "madrid",
+    nombre: "Madrid",
+    fechaInicio: "2026-09-01",
+    fechaFin: "2026-09-03",
+    descripcion: "Llegada y paseo"
+  });
+  assert.deepEqual(listParadas(), [created]);
+  assert.equal(
+    globalThis.localStorage.getItem("viaje-en-familia:v1:itinerary/paradas"),
+    JSON.stringify([created])
+  );
+});
+
+test("updateParada edits an existing parada without changing its id", () => {
+  addParada({
+    id: "barcelona",
+    nombre: "Barcelona",
+    fechaInicio: "2026-09-04",
+    fechaFin: "2026-09-06",
+    descripcion: "Costa y arquitectura"
+  });
+
+  const updated = updateParada({
+    id: "barcelona",
+    nombre: "Barcelona centro",
+    descripcion: "Museos y comida"
+  });
+
+  assert.deepEqual(updated, {
+    id: "barcelona",
+    nombre: "Barcelona centro",
+    fechaInicio: "2026-09-04",
+    fechaFin: "2026-09-06",
+    descripcion: "Museos y comida"
+  });
+  assert.deepEqual(listParadas(), [updated]);
+});
+
+test("removeParada deletes the requested parada and returns it", () => {
+  const first = addParada({
+    id: "cordoba",
+    nombre: "Córdoba",
+    fechaInicio: "2026-09-07",
+    fechaFin: "2026-09-08",
+    descripcion: "Escala corta"
+  });
+  const second = addParada({
+    id: "sevilla",
+    nombre: "Sevilla",
+    fechaInicio: "2026-09-09",
+    fechaFin: "2026-09-11",
+    descripcion: "Centro histórico"
+  });
+
+  const removed = removeParada("cordoba");
+
+  assert.deepEqual(removed, first);
+  assert.deepEqual(listParadas(), [second]);
+  assert.equal(
+    globalThis.localStorage.getItem("viaje-en-familia:v1:itinerary/paradas"),
+    JSON.stringify([second])
+  );
+});
+
+test("reorderParadas reorders by ids and by indexes", () => {
+  const first = addParada({
+    id: "uno",
+    nombre: "Uno",
+    fechaInicio: "2026-10-01",
+    fechaFin: "2026-10-02",
+    descripcion: "Primera"
+  });
+  const second = addParada({
+    id: "dos",
+    nombre: "Dos",
+    fechaInicio: "2026-10-03",
+    fechaFin: "2026-10-04",
+    descripcion: "Segunda"
+  });
+  const third = addParada({
+    id: "tres",
+    nombre: "Tres",
+    fechaInicio: "2026-10-05",
+    fechaFin: "2026-10-06",
+    descripcion: "Tercera"
+  });
+
+  assert.deepEqual(reorderParadas(["tres", first.id, second.id]), [third, first, second]);
+  assert.deepEqual(reorderParadas({ fromIndex: 0, toIndex: 2 }), [first, second, third]);
+  assert.deepEqual(reorderParadas(2, 0), [third, first, second]);
+});

diff --git a/src/recuerdos/notas/notas.mjs b/src/recuerdos/notas/notas.mjs
new file mode 100644
index 0000000000000000000000000000000000000000..8c18089c038e0c97e4dc4f9eb40eeff0ed0a8a32
--- /dev/null
+++ b/src/recuerdos/notas/notas.mjs
@@ -0,0 +1,105 @@
+import { createStore } from "../../storage/storage.mjs";
+
+let notasStoreInstance;
+
+function getNotasStore() {
+  if (!notasStoreInstance) {
+    notasStoreInstance = createStore("recuerdos/notas");
+  }
+
+  return notasStoreInstance;
+}
+
+function leerNotas() {
+  return getNotasStore().get() ?? [];
+}
+
+function esCadenaNoVacia(valor) {
+  return typeof valor === "string" && valor.trim().length > 0;
+}
+
+function normalizarNota(nota) {
+  if (nota === null || typeof nota !== "object" || Array.isArray(nota)) {
+    throw new TypeError("La nota debe ser un objeto");
+  }
+
+  const texto = typeof nota.texto === "string" ? nota.texto.trim() : "";
+  if (texto.length === 0) {
+    throw new TypeError("La nota debe incluir texto");
+  }
+
+  const tieneDia = esCadenaNoVacia(nota.diaId);
+  const tieneParada = esCadenaNoVacia(nota.paradaId);
+
+  if (tieneDia === tieneParada) {
+    throw new TypeError("La nota debe asociarse a un día o a una parada");
+  }
+
+  return {
+    id: esCadenaNoVacia(nota.id) ? nota.id.trim() : crypto.randomUUID(),
+    texto,
+    ...(tieneDia ? { diaId: nota.diaId.trim() } : { paradaId: nota.paradaId.trim() })
+  };
+}
+
+export function listarNotas() {
+  return leerNotas();
+}
+
+export function listarNotasPorDia(diaId) {
+  if (!esCadenaNoVacia(diaId)) {
+    return [];
+  }
+
+  return leerNotas().filter((nota) => nota.diaId === diaId.trim());
+}
+
+export function listarNotasPorParada(paradaId) {
+  if (!esCadenaNoVacia(paradaId)) {
+    return [];
+  }
+
+  return leerNotas().filter((nota) => nota.paradaId === paradaId.trim());
+}
+
+export function guardarNota(nota) {
+  const nuevaNota = normalizarNota(nota);
+  const notas = leerNotas();
+  const index = notas.findIndex(({ id }) => id === nuevaNota.id);
+
+  if (index === -1) {
+    const siguientes = [...notas, nuevaNota];
+    getNotasStore().set(siguientes);
+    return nuevaNota;
+  }
+
+  const siguientes = [...notas];
+  siguientes[index] = nuevaNota;
+  getNotasStore().set(siguientes);
+  return nuevaNota;
+}
+
+export function limpiarNotas() {
+  getNotasStore().set([]);
+}
+
+export const notasStore = {
+  get() {
+    return getNotasStore().get();
+  },
+  set(value) {
+    return getNotasStore().set(value);
+  },
+  subscribe(listener) {
+    return getNotasStore().subscribe(listener);
+  }
+};
+
+export default {
+  notasStore,
+  guardarNota,
+  listarNotas,
+  listarNotasPorDia,
+  listarNotasPorParada,
+  limpiarNotas
+};
