+    fechaInicio: "2026-10-01",
+    fechaFin: "2026-10-02",
+    descripcion: "Primera"
+  });
+  const second = addParada({
+    id: "dos",
+    nombre: "Dos",
+    fechaInicio: "2026-10-03",
+    fechaFin: "2026-10-04",
+    descripcion: "Segunda"
+  });
+  const third = addParada({
+    id: "tres",
+    nombre: "Tres",
+    fechaInicio: "2026-10-05",
+    fechaFin: "2026-10-06",
