}

function getFavoritoClave(favorito) {
  const id = getFavoritoId(favorito);
  const tipo = getFavoritoTipo(favorito);

  if (!id) {
    throw new TypeError("favorito must include an identifier");
  }

  return tipo ? `${tipo}:${id}` : id;
}

function normalizeLista(value) {
  return Array.isArray(value) ? value.map(cloneFavorito) : [];
