    if (favoritos.some((item) => sameFavorito(item, favorito))) {
      return favoritos.find((item) => sameFavorito(item, favorito));
    }

    const next = [...favoritos, cloneFavorito(favorito)];
    store.set(next);
    return next[next.length - 1];
  }

  function desmarcarFavorito(favorito) {
