+  const paradaId = actividad.paradaId ?? "";
+  const horario = actividad.horario ?? "";
+  const estado = normalizeEstado(actividad.estado);
+
+  if (fecha === "") {
+    throw new TypeError("fecha is required");
+  }
+
+  if (paradaId === "") {
+    throw new TypeError("paradaId is required");
+  }
+
+  if (horario === "") {
+    throw new TypeError("horario is required");
+  }
+
+  ensureParadaExists(paradaId);
+
+  return {
