+import assert from "node:assert/strict";
+import test from "node:test";
+
+import { createFavoritosStore } from "../../src/recuerdos/favoritos/favoritos.mjs";
+import {
+  guardarNota,
+  listarNotas,
+  limpiarNotas,
+  notasStore
+} from "../../src/recuerdos/notas/notas.mjs";
+
+class LocalStorageMock {
+  #map = new Map();
+
+  clear() {
+    this.#map.clear();
+  }
+
+  getItem(key) {
+    return this.#map.has(key) ? this.#map.get(key) : null;
+  }
+
+  setItem(key, value) {
+    this.#map.set(key, String(value));
+  }
+
+  removeItem(key) {
+    this.#map.delete(key);
+  }
+}
+
+const NOTAS_KEY = "viaje-en-familia:v1:recuerdos/notas";
+const FAVORITOS_KEY = "viaje-en-familia:v1:recuerdos/favoritos";
+
+test.beforeEach(() => {
+  globalThis.localStorage = new LocalStorageMock();
+  limpiarNotas();
+});
+
+test.afterEach(() => {
+  delete globalThis.localStorage;
+});
+
+test("recuerdos keeps notas and favoritos in the same versioned storage area", () => {
+  const favoritos = createFavoritosStore();
+  const lugar = { id: "museo", tipo: "lugar", nombre: "Museo de los Ninos" };
+  const nota = guardarNota({
+    id: "nota-dia-1",
+    texto: "Llevar abrigo",
+    diaId: "dia-2026-08-21"
+  });
+
+  favoritos.marcarFavorito(lugar);
+
+  assert.deepEqual(listarNotas(), [nota]);
+  assert.deepEqual(favoritos.listarFavoritos(), [lugar]);
+  assert.equal(globalThis.localStorage.getItem(NOTAS_KEY), JSON.stringify([nota]));
+  assert.equal(globalThis.localStorage.getItem(FAVORITOS_KEY), JSON.stringify([lugar]));
+  assert.deepEqual(notasStore.get(), [nota]);
+});
+
+test("recuerdos hydrates notas and favoritos independently from shared localStorage", () => {
+  const nota = {
+    id: "nota-parada-1",
+    texto: "Comprar agua",
+    paradaId: "parada-rosario"
+  };
+  const favorito = {
+    id: "picnic",
+    tipo: "actividad",
+    nombre: "Picnic en la plaza"
+  };
+
+  globalThis.localStorage.setItem(NOTAS_KEY, JSON.stringify([nota]));
+  globalThis.localStorage.setItem(FAVORITOS_KEY, JSON.stringify([favorito]));
+
+  const favoritos = createFavoritosStore();
+
+  assert.deepEqual(listarNotas(), [nota]);
+  assert.deepEqual(favoritos.listarFavoritos(), [favorito]);
+  assert.equal(globalThis.localStorage.getItem(NOTAS_KEY), JSON.stringify([nota]));
+  assert.equal(globalThis.localStorage.getItem(FAVORITOS_KEY), JSON.stringify([favorito]));
+});

