+import assert from "node:assert/strict";
+import test from "node:test";
+
+import {
+  addActividad,
+  listActividades,
+  removeActividad,
+  updateActividad
+} from "./agenda.mjs";
+import { addParada } from "../paradas/paradas.mjs";
+
+class LocalStorageMock {
+  #map = new Map();
+
+  clear() {
+    this.#map.clear();
+  }
+
+  getItem(key) {
+    return this.#map.has(key) ? this.#map.get(key) : null;
+  }
+
+  setItem(key, value) {
+    this.#map.set(key, String(value));
+  }
