+  removeItem(key) {
+    this.#map.delete(key);
+  }
+}
+
+test.beforeEach(() => {
+  globalThis.localStorage = new LocalStorageMock();
+});
+
+test.afterEach(() => {
+  delete globalThis.localStorage;
+});
+
+test("listActividades and addActividad persist activities with fecha, paradaId, horario and estado", () => {
+  const parada = addParada({
+    id: "madrid",
+    nombre: "Madrid",
+    fechaInicio: "2026-09-01",
+    fechaFin: "2026-09-03",
+    descripcion: "Llegada y paseo"
+  });
+
+  assert.deepEqual(listActividades(), []);
+
+  const created = addActividad({
+    id: "madrid-desayuno",
+    fecha: "2026-09-02",
+    paradaId: parada.id,
+    horario: "08:30",
+    estado: "pendiente"
+  });
+
+  assert.deepEqual(created, {
+    id: "madrid-desayuno",
+    fecha: "2026-09-02",
+    paradaId: "madrid",
+    horario: "08:30",
+    estado: "pendiente"
+  });
+  assert.deepEqual(listActividades(), [created]);
+  assert.equal(
+    globalThis.localStorage.getItem("viaje-en-familia:v1:itinerary/agenda"),
+    JSON.stringify([created])
+  );
+});
+
+test("updateActividad edits the activity state without changing its association", () => {
+  addParada({
+    id: "sevilla",
+    nombre: "Sevilla",
+    fechaInicio: "2026-09-04",
+    fechaFin: "2026-09-06",
+    descripcion: "Centro histórico"
+  });
+
+  addActividad({
