+    fecha: "2026-09-05",
+    paradaId: "sevilla",
+    horario: "11:00"
+  });
+
+  const updated = updateActividad({
+    id: "sevilla-museo",
+    estado: "completada"
+  });
+
+  assert.deepEqual(updated, {
+    id: "sevilla-museo",
+    fecha: "2026-09-05",
+    paradaId: "sevilla",
+    horario: "11:00",
+    estado: "completada"
+  });
+  assert.deepEqual(listActividades(), [updated]);
+});
+
+test("removeActividad deletes the requested activity and returns it", () => {
+  addParada({
+    id: "cordoba",
+    nombre: "Córdoba",
+    fechaInicio: "2026-09-07",
+    fechaFin: "2026-09-08",
+    descripcion: "Escala corta"
+  });
+
+  const first = addActividad({
+    id: "cordoba-lunch",
+    fecha: "2026-09-07",
