+  });
+  const second = addActividad({
+    id: "cordoba-dinner",
+    fecha: "2026-09-07",
+    paradaId: "cordoba",
+    horario: "20:00",
+    estado: "pendiente"
+  });
+
+  const removed = removeActividad("cordoba-lunch");
+
+  assert.deepEqual(removed, first);
+  assert.deepEqual(listActividades(), [second]);
+  assert.equal(
+    globalThis.localStorage.getItem("viaje-en-familia:v1:itinerary/agenda"),
+    JSON.stringify([second])
+  );
+});

