@@ -0,0 +1,323 @@
+:root {
+  color-scheme: dark;
+  --bg: #09111d;
+  --bg-soft: #111b2b;
+  --panel: rgba(8, 16, 28, 0.86);
+  --panel-strong: #0f1c31;
+  --text: #f5f7fb;
+  --muted: #aebbd0;
+  --line: rgba(177, 199, 231, 0.18);
+  --accent: #f2b544;
+  --accent-strong: #78d0ff;
+  --accent-soft: rgba(120, 208, 255, 0.16);
+  --shadow: 0 24px 80px rgba(1, 6, 15, 0.48);
+}
+
+* {
+  box-sizing: border-box;
+}
+
+html,
+body {
+  min-height: 100%;
+}
+
+body {
+  margin: 0;
+  color: var(--text);
+  font-family: "Avenir Next", "Trebuchet MS", "Gill Sans", sans-serif;
+  background:
+    radial-gradient(circle at top left, rgba(242, 181, 68, 0.22), transparent 30%),
+    radial-gradient(circle at top right, rgba(120, 208, 255, 0.2), transparent 26%),
+    linear-gradient(160deg, #050b13 0%, var(--bg) 48%, #050a12 100%);
+}
+
+body::before {
+  content: "";
+  position: fixed;
+  inset: 0;
+  pointer-events: none;
+  background-image: linear-gradient(rgba(255, 255, 255, 0.025) 1px, transparent 1px),
+    linear-gradient(90deg, rgba(255, 255, 255, 0.025) 1px, transparent 1px);
+  background-size: 42px 42px;
+  mask-image: radial-gradient(circle at center, black 35%, transparent 100%);
+}
+
+.app-shell {
+  min-height: 100vh;
+}
+
+.dashboard-shell {
+  width: min(1200px, calc(100vw - 32px));
+  margin: 0 auto;
+  padding: 32px 0 48px;
+  display: grid;
+  grid-template-columns: repeat(2, minmax(0, 1fr));
+  gap: 20px;
+}
+
+.hero,
+.panel {
+  position: relative;
+  overflow: hidden;
+  border: 1px solid var(--line);
+  border-radius: 24px;
+  background: linear-gradient(180deg, rgba(14, 24, 41, 0.9), rgba(8, 14, 25, 0.92));
+  box-shadow: var(--shadow);
+}
+
+.hero {
+  grid-column: 1 / -1;
+  padding: 32px;
+  display: grid;
+  gap: 24px;
+  grid-template-columns: minmax(0, 1.7fr) minmax(280px, 0.9fr);
+  align-items: end;
+}
+
+.hero::after,
+.panel::after {
+  content: "";
+  position: absolute;
+  inset: auto -8% -18% auto;
+  width: 220px;
+  height: 220px;
+  border-radius: 999px;
+  background: radial-gradient(circle, rgba(242, 181, 68, 0.22), transparent 65%);
+  filter: blur(16px);
+  pointer-events: none;
+}
+
+.panel {
+  padding: 24px;
+}
+
+.span-2 {
+  grid-column: 1 / -1;
+}
+
+.eyebrow {
+  margin: 0 0 8px;
+  color: var(--accent-strong);
+  text-transform: uppercase;
+  letter-spacing: 0.18em;
+  font-size: 0.72rem;
+  font-weight: 700;
+}
+
+h1,
+h2 {
+  margin: 0;
+  font-family: "Georgia", "Times New Roman", serif;
+  letter-spacing: -0.03em;
+}
+
+h1 {
+  font-size: clamp(2.4rem, 4vw, 4.5rem);
+  line-height: 0.95;
+  max-width: 8ch;
+}
+
+h2 {
+  font-size: clamp(1.45rem, 2vw, 1.9rem);
+}
+
+.hero-meta,
+.section-note,
+.subtle {
+  margin: 10px 0 0;
+  color: var(--muted);
+}
+
+.hero-stats,
+.metric-grid,
+.split-grid {
+  display: grid;
+  gap: 12px;
+}
+
+.hero-stats {
+  grid-template-columns: repeat(3, minmax(0, 1fr));
+}
+
+.hero-stats div,
+.metric {
+  padding: 16px;
+  border-radius: 18px;
+  background: rgba(255, 255, 255, 0.03);
+  border: 1px solid rgba(255, 255, 255, 0.07);
+}
+
+.hero-stats span,
+.metric span {
+  display: block;
+  color: var(--muted);
+  font-size: 0.86rem;
+}
+
+.hero-stats strong,
+.metric strong {
+  display: block;
+  margin-top: 10px;
+  font-size: 1.1rem;
+  line-height: 1.15;
+}
+
+.section-head {
+  display: flex;
+  justify-content: space-between;
+  gap: 16px;
+  align-items: start;
+  margin-bottom: 18px;
+}
+
+.section-head > div {
+  min-width: 0;
+}
+
+.metric-grid {
+  grid-template-columns: repeat(3, minmax(0, 1fr));
+  margin-bottom: 16px;
+}
+
+.meter {
+  height: 14px;
+  border-radius: 999px;
+  background: rgba(255, 255, 255, 0.08);
+  overflow: hidden;
+  border: 1px solid rgba(255, 255, 255, 0.06);
+}
+
+.meter-fill {
+  height: 100%;
+  border-radius: inherit;
+  background: linear-gradient(90deg, var(--accent), #ffe08b);
+}
+
+.meter-fill.luggage {
+  background: linear-gradient(90deg, var(--accent-strong), #c4f0ff);
+}
+
+.stack-list,
+.event-list,
+.card-list {
+  list-style: none;
+  padding: 0;
+  margin: 16px 0 0;
+}
+
+.stack-list {
+  display: grid;
+  gap: 10px;
+}
+
+.mini-row,
+.event-row,
+.memory-card,
+.note-card,
+.check-item {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: 12px;
+  padding: 14px 16px;
+  border-radius: 16px;
+  background: rgba(255, 255, 255, 0.04);
+  border: 1px solid rgba(255, 255, 255, 0.07);
+}
+
+.event-list {
+  display: grid;
+  gap: 12px;
+}
+
+.event-row {
+  align-items: start;
+}
+
+.event-date,
+.tag {
+  flex: 0 0 auto;
+  font-size: 0.78rem;
+  font-weight: 700;
+  letter-spacing: 0.06em;
+  text-transform: uppercase;
+  color: var(--accent-strong);
+}
+
+.event-copy,
+.memory-card,
+.note-card {
+  display: grid;
+  gap: 4px;
+}
+
+.event-copy strong,
+.memory-card strong,
+.note-card strong {
+  font-size: 1rem;
+}
+
+.event-copy span,
+.note-card span {
+  color: var(--muted);
+  font-size: 0.92rem;
+}
+
+.bullet {
+  width: 12px;
+  height: 12px;
+  border-radius: 999px;
+  background: linear-gradient(180deg, var(--accent), #ffe59a);
+  box-shadow: 0 0 0 4px rgba(242, 181, 68, 0.14);
+  flex: 0 0 auto;
+}
+
+.check-item {
+  justify-content: start;
+}
+
+.split-grid {
+  grid-template-columns: repeat(2, minmax(0, 1fr));
+}
+
+.card-list {
+  display: grid;
+  gap: 12px;
+}
+
+.empty {
+  padding: 18px;
+  border-radius: 16px;
+  border: 1px dashed rgba(255, 255, 255, 0.14);
+  color: var(--muted);
+  background: rgba(255, 255, 255, 0.02);
+}
+
+:focus-visible {
+  outline: 3px solid var(--accent);
+  outline-offset: 4px;
+}
+
+@media (max-width: 900px) {
+  .dashboard-shell {
+    width: min(100%, calc(100vw - 20px));
+    padding: 20px 0 28px;
+    grid-template-columns: 1fr;
+  }
+
+  .hero,
+  .split-grid,
+  .hero-stats,
+  .metric-grid {
+    grid-template-columns: 1fr;
+  }
+
+  .hero {
+    padding: 24px;
+  }
+
+  .section-head {
+    flex-direction: column;
+  }
+}
