@@ -0,0 +1,344 @@
+const STORAGE_PREFIX = "viaje-en-familia:v1";
+const KEYS = {
+  paradas: `${STORAGE_PREFIX}:itinerary/paradas`,
+  agenda: `${STORAGE_PREFIX}:itinerary/agenda`,
+  presupuesto: `${STORAGE_PREFIX}:organizacion/presupuesto`,
+  equipaje: `${STORAGE_PREFIX}:organizacion/equipaje`,
+  favoritos: `${STORAGE_PREFIX}:recuerdos/favoritos`,
+  notas: `${STORAGE_PREFIX}:recuerdos/notas`
+};
+
+function readJSON(key, fallback) {
+  try {
+    const raw = globalThis.localStorage?.getItem(key);
+    return raw === null || raw === undefined ? fallback : JSON.parse(raw);
+  } catch {
+    return fallback;
+  }
+}
+
+function formatDateHuman(value) {
+  if (!value) {
+    return "Sin fecha";
+  }
+
+  const date = new Date(`${value}T00:00:00`);
+  if (Number.isNaN(date.getTime())) {
+    return value;
+  }
+
+  return new Intl.DateTimeFormat("es-AR", {
+    day: "2-digit",
+    month: "short",
+    year: "numeric"
+  }).format(date);
+}
+
+function formatCurrency(value) {
+  return new Intl.NumberFormat("es-AR", {
+    style: "currency",
+    currency: "ARS",
+    maximumFractionDigits: 0
+  }).format(Number(value) || 0);
+}
+
+function escapeHtml(value) {
+  return String(value)
+    .replaceAll("&", "&amp;")
+    .replaceAll("<", "&lt;")
+    .replaceAll(">", "&gt;")
+    .replaceAll('"', "&quot;")
+    .replaceAll("'", "&#39;");
+}
+
+function getTripName(paradas) {
+  if (paradas.length === 0) {
+    return "Viaje en familia";
+  }
+
+  if (paradas.length === 1) {
+    return `Viaje a ${paradas[0].nombre}`;
+  }
+
+  return `Ruta ${paradas[0].nombre} - ${paradas[paradas.length - 1].nombre}`;
+}
+
+function getTripRange(paradas) {
+  if (paradas.length === 0) {
+    return "Fechas por definir";
+  }
+
+  const ordered = [...paradas].sort((left, right) => {
+    const compareStart = `${left.fechaInicio ?? ""}`.localeCompare(`${right.fechaInicio ?? ""}`);
+    if (compareStart !== 0) {
+      return compareStart;
+    }
+
+    return `${left.fechaFin ?? ""}`.localeCompare(`${right.fechaFin ?? ""}`);
+  });
+
+  const first = ordered[0];
+  const last = [...ordered].sort((left, right) => `${right.fechaFin ?? ""}`.localeCompare(`${left.fechaFin ?? ""}`))[0];
+  return `${formatDateHuman(first.fechaInicio)} - ${formatDateHuman(last.fechaFin)}`;
+}
+
+function buildUpcomingEvents(paradas, actividades) {
+  const events = [
+    ...paradas.map((parada) => ({
+      kind: "parada",
+      fecha: parada.fechaInicio ?? "",
+      title: parada.nombre,
+      detail: parada.descripcion || "Parada planificada",
+      subtitle:
+        parada.fechaInicio === parada.fechaFin
+          ? formatDateHuman(parada.fechaInicio)
+          : `${formatDateHuman(parada.fechaInicio)} - ${formatDateHuman(parada.fechaFin)}`
+    })),
+    ...actividades.map((actividad) => ({
+      kind: "actividad",
+      fecha: actividad.fecha ?? "",
+      horario: actividad.horario ?? "",
+      title: `${actividad.horario} · ${actividad.estado}`,
+      detail: `${actividad.paradaId ?? "Parada"} · ${formatDateHuman(actividad.fecha)}`,
+      subtitle: "Actividad"
+    }))
+  ]
+    .filter((item) => item.fecha)
+    .sort((left, right) => `${left.fecha} ${left.horario ?? ""}`.localeCompare(`${right.fecha} ${right.horario ?? ""}`));
+
+  return events.slice(0, 4);
+}
+
+function summarizeBudget() {
+  const presupuesto = readJSON(KEYS.presupuesto, {});
+  const gastos = Array.isArray(presupuesto.gastos) ? presupuesto.gastos : [];
+  const total = Number(presupuesto.total) || 0;
+  const gastado = gastos.reduce((sum, gasto) => sum + (Number(gasto?.gasto ?? gasto?.monto ?? gasto?.importe) || 0), 0);
+  const disponible = total - gastado;
+  const porcentaje = total > 0 ? Math.round((gastado / total) * 100) : 0;
+
+  return { total, gastado, disponible, porcentaje, gastos };
+}
+
+function summarizePacking() {
+  const state = readJSON(KEYS.equipaje, {});
+  const items = Array.isArray(state.items) ? state.items : [];
+  const completados = items.filter((item) => Boolean(item.completado)).length;
+  const pendientes = items.filter((item) => !item.completado).slice(0, 3);
+
+  return {
+    total: items.length,
+    completados,
+    pendientes: items.length - completados,
+    porcentaje: items.length === 0 ? 0 : Math.round((completados / items.length) * 100),
+    pendientesLista: pendientes
+  };
+}
+
+function buildModel() {
+  const paradas = [...(readJSON(KEYS.paradas, []) ?? [])].sort((left, right) =>
+    `${left.fechaInicio ?? ""} ${left.fechaFin ?? ""}`.localeCompare(`${right.fechaInicio ?? ""} ${right.fechaFin ?? ""}`)
+  );
+  const actividades = [...(readJSON(KEYS.agenda, []) ?? [])].sort((left, right) =>
+    `${left.fecha ?? ""} ${left.horario ?? ""}`.localeCompare(`${right.fecha ?? ""} ${right.horario ?? ""}`)
+  );
+  const favoritos = [...(readJSON(KEYS.favoritos, []) ?? [])].slice(0, 4);
+  const notas = [...(readJSON(KEYS.notas, []) ?? [])].slice(0, 3);
+
+  return {
+    viaje: {
+      nombre: getTripName(paradas),
+      rango: getTripRange(paradas),
+      paradas: paradas.length,
+      actividades: actividades.length
+    },
+    eventos: buildUpcomingEvents(paradas, actividades),
+    presupuesto: summarizeBudget(),
+    equipaje: summarizePacking(),
+    recuerdos: { favoritos, notas }
+  };
+}
+
+function renderList(items, emptyMessage, renderItem) {
+  if (items.length === 0) {
+    return `<li class="empty">${emptyMessage}</li>`;
+  }
+
+  return items.map(renderItem).join("");
+}
+
+function renderDashboard(model) {
+  const budgetCategories = model.presupuesto.gastos.length > 0
+    ? model.presupuesto.gastos
+        .map(
+          (item) => `
+            <li class="mini-row">
+              <span>${escapeHtml(item.categoria ?? "Sin categoría")}</span>
+              <strong>${escapeHtml(formatCurrency(item.gasto ?? 0))}</strong>
+            </li>
+          `
+        )
+        .join("")
+    : `<li class="empty">Aún no hay gastos cargados.</li>`;
+
+  const pendingItems = renderList(
+    model.equipaje.pendientesLista,
+    "La valija ya está casi lista.",
+    (item) => `
+      <li class="check-item">
+        <span class="bullet"></span>
+        <span>${escapeHtml(item.nombre)}</span>
+      </li>
+    `
+  );
+
+  const favorites = renderList(
+    model.recuerdos.favoritos,
+    "Todavía no hay recuerdos destacados.",
+    (item) => `
+      <li class="memory-card">
+        <span class="tag">${escapeHtml(item.tipo ?? "recuerdo")}</span>
+        <strong>${escapeHtml(item.nombre ?? item.titulo ?? item.title ?? "Sin nombre")}</strong>
+      </li>
+    `
+  );
+
+  const notes = renderList(
+    model.recuerdos.notas,
+    "Aún no se registraron notas.",
+    (item) => `
+      <li class="note-card">
+        <strong>${escapeHtml(item.texto ?? "Sin texto")}</strong>
+        <span>${escapeHtml(item.diaId ?? item.paradaId ?? "Sin contexto")}</span>
+      </li>
+    `
+  );
+
+  const events = renderList(
+    model.eventos,
+    "No hay eventos próximos cargados.",
+    (item) => `
+      <li class="event-row">
+        <div class="event-date">${escapeHtml(item.subtitle)}</div>
+        <div class="event-copy">
+          <strong>${escapeHtml(item.title)}</strong>
+          <span>${escapeHtml(item.detail)}</span>
+        </div>
+      </li>
+    `
+  );
+
+  return `
+    <main class="dashboard-shell">
+      <section class="hero">
+        <div>
+          <p class="eyebrow">Dashboard del viaje</p>
+          <h1>${escapeHtml(model.viaje.nombre)}</h1>
+          <p class="hero-meta">${escapeHtml(model.viaje.rango)}</p>
+        </div>
+        <div class="hero-stats">
+          <div>
+            <span>Paradas</span>
+            <strong>${model.viaje.paradas}</strong>
+          </div>
+          <div>
+            <span>Actividades</span>
+            <strong>${model.viaje.actividades}</strong>
+          </div>
+          <div>
+            <span>Rango</span>
+            <strong>${escapeHtml(model.viaje.rango)}</strong>
+          </div>
+        </div>
+      </section>
+
+      <section class="panel span-2">
+        <div class="section-head">
+          <div>
+            <p class="eyebrow">Itinerario</p>
+            <h2>Próximos eventos</h2>
+          </div>
+          <p class="section-note">Paradas y actividades ordenadas para ver el viaje de un vistazo.</p>
+        </div>
+        <ul class="event-list">${events}</ul>
+      </section>
+
+      <section class="panel">
+        <div class="section-head">
+          <div>
+            <p class="eyebrow">Organización</p>
+            <h2>Presupuesto</h2>
+          </div>
+        </div>
+        <div class="metric-grid">
+          <article class="metric">
+            <span>Total</span>
+            <strong>${escapeHtml(formatCurrency(model.presupuesto.total))}</strong>
+          </article>
+          <article class="metric">
+            <span>Gastado</span>
+            <strong>${escapeHtml(formatCurrency(model.presupuesto.gastado))}</strong>
+          </article>
+          <article class="metric">
+            <span>Disponible</span>
+            <strong>${escapeHtml(formatCurrency(model.presupuesto.disponible))}</strong>
+          </article>
+        </div>
+        <div class="meter">
+          <div class="meter-fill" style="width:${Math.max(0, Math.min(100, model.presupuesto.porcentaje))}%"></div>
+        </div>
+        <ul class="stack-list">${budgetCategories}</ul>
+      </section>
+
+      <section class="panel">
+        <div class="section-head">
+          <div>
+            <p class="eyebrow">Organización</p>
+            <h2>Equipaje</h2>
+          </div>
+        </div>
+        <div class="metric-grid">
+          <article class="metric">
+            <span>Completados</span>
+            <strong>${model.equipaje.completados}/${model.equipaje.total}</strong>
+          </article>
+          <article class="metric">
+            <span>Pendientes</span>
+            <strong>${model.equipaje.pendientes}</strong>
+          </article>
+          <article class="metric">
+            <span>Progreso</span>
+            <strong>${model.equipaje.porcentaje}%</strong>
+          </article>
+        </div>
+        <div class="meter">
+          <div class="meter-fill luggage" style="width:${model.equipaje.porcentaje}%"></div>
+        </div>
+        <ul class="stack-list">${pendingItems}</ul>
+      </section>
+
+      <section class="panel span-2">
+        <div class="section-head">
+          <div>
+            <p class="eyebrow">Recuerdos</p>
+            <h2>Destacados</h2>
+          </div>
+          <p class="section-note">Favoritos y notas que mantienen visible la parte emocional del viaje.</p>
+        </div>
+        <div class="split-grid">
+          <div>
+            <p class="eyebrow">Favoritos</p>
+            <ul class="card-list">${favorites}</ul>
+          </div>
+          <div>
+            <p class="eyebrow">Notas</p>
+            <ul class="card-list">${notes}</ul>
+          </div>
+        </div>
+      </section>
+    </main>
+  `;
+}
+
+const app = document.getElementById("app") ?? document.body;
+app.innerHTML = renderDashboard(buildModel());
