+
+.meter-fill {
+  height: 100%;
+  border-radius: inherit;
+  background: linear-gradient(90deg, var(--accent), #ffe08b);
+}
+
+.meter-fill.luggage {
+  background: linear-gradient(90deg, var(--accent-strong), #c4f0ff);
+}
+
+.stack-list,
+.event-list,
+.card-list {
+  list-style: none;
+  padding: 0;
+  margin: 16px 0 0;
+}
+
+.stack-list {
+  display: grid;
+  gap: 10px;
+}
+
+.mini-row,
+.event-row,
+.memory-card,
+.note-card,
+.check-item {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: 12px;
+  padding: 14px 16px;
+  border-radius: 16px;
+  background: rgba(255, 255, 255, 0.04);
+  border: 1px solid rgba(255, 255, 255, 0.07);
+}
+
+.event-list {
+  display: grid;
+  gap: 12px;
+}
+
+.event-row {
+  align-items: start;
+}
+
+.event-date,
+.tag {
+  flex: 0 0 auto;
+  font-size: 0.78rem;
+  font-weight: 700;
+  letter-spacing: 0.06em;
+  text-transform: uppercase;
+  color: var(--accent-strong);
+}
+
+.event-copy,
+.memory-card,
+.note-card {
+  display: grid;
+  gap: 4px;
+}
+
+.event-copy strong,
+.memory-card strong,
+.note-card strong {
+  font-size: 1rem;
+}
+
+.event-copy span,
+.note-card span {
+  color: var(--muted);
+  font-size: 0.92rem;
+}
+
+.bullet {
+  width: 12px;
+  height: 12px;
+  border-radius: 999px;
+  background: linear-gradient(180deg, var(--accent), #ffe59a);
+  box-shadow: 0 0 0 4px rgba(242, 181, 68, 0.14);
+  flex: 0 0 auto;
+}
+
+.check-item {
+  justify-content: start;
+}
+
+.split-grid {
+  grid-template-columns: repeat(2, minmax(0, 1fr));
+}
+
+.card-list {
+  display: grid;
+  gap: 12px;
+}
+
+.empty {
+  padding: 18px;
+  border-radius: 16px;
+  border: 1px dashed rgba(255, 255, 255, 0.14);
+  color: var(--muted);
+  background: rgba(255, 255, 255, 0.02);
+}
+
+:focus-visible {
+  outline: 3px solid var(--accent);
+  outline-offset: 4px;
+}
+
+@media (max-width: 900px) {
+  .dashboard-shell {
+    width: min(100%, calc(100vw - 20px));
+    padding: 20px 0 28px;
+    grid-template-columns: 1fr;
+  }
+
+  .hero,
+  .split-grid,
+  .hero-stats,
+  .metric-grid {
+    grid-template-columns: 1fr;
+  }
+
+  .hero {
+    padding: 24px;
+  }
+
+  .section-head {
+    flex-direction: column;
+  }
+}
diff --git a/src/dashboard/dashboard.mjs b/src/dashboard/dashboard.mjs
