+:root {
+  color-scheme: dark;
+  --bg: #09111d;
+  --bg-soft: #111b2b;
+  --panel: rgba(8, 16, 28, 0.86);
+  --panel-strong: #0f1c31;
+  --text: #f5f7fb;
