diff --git a/src/dashboard/dashboard.mjs b/src/dashboard/dashboard.mjs
new file mode 100644
index 0000000000000000000000000000000000000000..0a1e09dbb4e1471cba7b52c80809b12e2c6cfe43
--- /dev/null
+++ b/src/dashboard/dashboard.mjs
@@ -0,0 +1,429 @@
+import { listParadas } from "../itinerary/paradas/paradas.mjs";
+import { listActividades } from "../itinerary/agenda/agenda.mjs";
+import { obtenerPresupuestoGuardado } from "../organizacion/presupuesto/presupuesto.mjs";
+import { crearChecklistEquipaje } from "../organizacion/equipaje/equipaje.mjs";
+import { createFavoritosStore } from "../recuerdos/favoritos/favoritos.mjs";
+import { listarNotas } from "../recuerdos/notas/notas.mjs";
+
+function toDateKey(value) {
+  if (typeof value === "string") {
+    return value;
+  }
+
+  if (value instanceof Date) {
+    return new Intl.DateTimeFormat("sv-SE").format(value);
+  }
+
+  return "";
+}
+
+function formatDateHuman(value) {
+  if (!value) {
+    return "Sin fecha";
+  }
+
+  const date = new Date(`${value}T00:00:00`);
+  if (Number.isNaN(date.getTime())) {
+    return value;
+  }
+
+  return new Intl.DateTimeFormat("es-AR", {
+    day: "2-digit",
+    month: "short",
+    year: "numeric"
+  }).format(date);
+}
+
+function formatCurrency(value) {
+  return new Intl.NumberFormat("es-AR", {
+    style: "currency",
+    currency: "ARS",
+    maximumFractionDigits: 0
+  }).format(value);
+}
+
+function escapeHtml(value) {
+  return String(value)
+    .replaceAll("&", "&amp;")
+    .replaceAll("<", "&lt;")
+    .replaceAll(">", "&gt;")
+    .replaceAll('"', "&quot;")
+    .replaceAll("'", "&#39;");
+}
+
+function sortByDateThenTime(left, right) {
+  const leftKey = `${left.fecha ?? ""} ${left.horario ?? ""}`.trim();
+  const rightKey = `${right.fecha ?? ""} ${right.horario ?? ""}`.trim();
+  return leftKey.localeCompare(rightKey);
+}
+
+function getTripName(paradas) {
+  if (paradas.length === 0) {
+    return "Viaje en familia";
+  }
+
+  if (paradas.length === 1) {
+    return `Viaje a ${paradas[0].nombre}`;
+  }
+
+  const first = paradas[0].nombre;
+  const last = paradas[paradas.length - 1].nombre;
+  return `Ruta ${first} - ${last}`;
+}
+
+function getTripRange(paradas) {
+  if (paradas.length === 0) {
+    return {
+      inicio: null,
+      fin: null,
+      etiqueta: "Fechas por definir"
+    };
+  }
+
+  const ordered = [...paradas].sort((left, right) => {
+    const compareStart = `${left.fechaInicio ?? ""}`.localeCompare(`${right.fechaInicio ?? ""}`);
+    if (compareStart !== 0) {
+      return compareStart;
+    }
+
+    return `${left.fechaFin ?? ""}`.localeCompare(`${right.fechaFin ?? ""}`);
+  });
+
+  const inicio = ordered[0].fechaInicio ?? null;
+  const fin = [...ordered].sort((left, right) => `${right.fechaFin ?? ""}`.localeCompare(`${left.fechaFin ?? ""}`))[0].fechaFin ?? null;
+
+  return {
+    inicio,
+    fin,
+    etiqueta:
+      inicio && fin
+        ? `${formatDateHuman(inicio)} - ${formatDateHuman(fin)}`
+        : "Fechas por definir"
+  };
+}
+
+function buildEventLabel(evento, paradasPorId) {
+  if (evento.tipo === "parada") {
+    return {
+      titulo: evento.nombre,
+      detalle: evento.descripcion || "Parada planificada",
+      subtitulo: evento.fechaInicio === evento.fechaFin
+        ? formatDateHuman(evento.fechaInicio)
+        : `${formatDateHuman(evento.fechaInicio)} - ${formatDateHuman(evento.fechaFin)}`
+    };
+  }
+
+  const parada = paradasPorId.get(evento.paradaId);
+  return {
+    titulo: `${evento.horario} · ${evento.estado}`,
+    detalle: `${parada?.nombre ?? "Parada sin nombre"} · ${formatDateHuman(evento.fecha)}`,
+    subtitulo: "Actividad"
+  };
+}
+
+function buildUpcomingEvents(paradas, actividades, hoy) {
+  const paradasPorId = new Map(paradas.map((parada) => [parada.id, parada]));
+  const eventos = [
+    ...paradas.map((parada) => ({
+      tipo: "parada",
+      fecha: parada.fechaInicio ?? "",
+      fechaInicio: parada.fechaInicio ?? "",
+      fechaFin: parada.fechaFin ?? "",
+      nombre: parada.nombre,
+      descripcion: parada.descripcion
+    })),
+    ...actividades.map((actividad) => ({
+      tipo: "actividad",
+      fecha: actividad.fecha ?? "",
+      horario: actividad.horario ?? "",
+      estado: actividad.estado ?? "pendiente",
+      paradaId: actividad.paradaId
+    }))
+  ]
+    .filter((evento) => evento.fecha)
+    .sort(sortByDateThenTime);
+
+  const upcoming = eventos.filter((evento) => evento.fecha >= hoy);
+  const source = upcoming.length > 0 ? upcoming : eventos;
+
+  return source.slice(0, 4).map((evento) => ({
+    ...evento,
+    ...buildEventLabel(evento, paradasPorId)
+  }));
+}
+
+function buildBudgetSummary() {
+  return obtenerPresupuestoGuardado();
+}
+
+function buildPackingSummary() {
+  const checklist = crearChecklistEquipaje();
+  const progreso = checklist.obtenerProgresoEquipaje();
+  const pendientes = checklist
+    .get()
+    .items.filter((item) => !item.completado)
+    .slice(0, 3);
+
+  return {
+    progreso,
+    pendientes
+  };
+}
+
+function buildMemoriesSummary() {
+  const favoritos = createFavoritosStore().listarFavoritos().slice(0, 4);
+  const notas = [...listarNotas()]
+    .sort((left, right) => `${right.id ?? ""}`.localeCompare(`${left.id ?? ""}`))
+    .slice(0, 3);
+
+  return {
+    favoritos,
+    notas
+  };
+}
+
+export function crearDashboardModel({ hoy = new Date() } = {}) {
+  const paradas = [...listParadas()].sort((left, right) => {
+    const leftKey = `${left.fechaInicio ?? ""} ${left.fechaFin ?? ""}`;
+    const rightKey = `${right.fechaInicio ?? ""} ${right.fechaFin ?? ""}`;
+    return leftKey.localeCompare(rightKey);
+  });
+  const actividades = [...listActividades()].sort(sortByDateThenTime);
+  const tripRange = getTripRange(paradas);
+  const upcomingEvents = buildUpcomingEvents(paradas, actividades, toDateKey(hoy));
+  const budget = buildBudgetSummary();
+  const packing = buildPackingSummary();
+  const memories = buildMemoriesSummary();
+
+  return {
+    viaje: {
+      nombre: getTripName(paradas),
+      inicio: tripRange.inicio,
+      fin: tripRange.fin,
+      etiqueta: tripRange.etiqueta,
+      paradas: paradas.length,
+      actividades: actividades.length
+    },
+    itinerario: {
+      paradas,
+      actividades,
+      proximosEventos: upcomingEvents
+    },
+    organizacion: {
+      presupuesto: budget,
+      equipaje: packing
+    },
+    recuerdos: memories
+  };
+}
+
+function renderBudget(budget) {
+  const porcentaje = Math.round(budget.porcentajeGastado * 100);
+  const categorias = budget.gastosPorCategoria.length > 0
+    ? budget.gastosPorCategoria
+        .map(
+          (item) => `
+            <li class="mini-row">
+              <span>${escapeHtml(item.categoria)}</span>
+              <strong>${escapeHtml(formatCurrency(item.gasto))}</strong>
+            </li>
+          `
+        )
+        .join("")
+    : `<li class="empty">Aún no hay gastos cargados.</li>`;
+
+  return `
+    <div class="metric-grid">
+      <article class="metric">
+        <span>Total</span>
+        <strong>${escapeHtml(formatCurrency(budget.total))}</strong>
+      </article>
+      <article class="metric">
+        <span>Gastado</span>
+        <strong>${escapeHtml(formatCurrency(budget.gastado))}</strong>
+      </article>
+      <article class="metric">
+        <span>Disponible</span>
+        <strong>${escapeHtml(formatCurrency(budget.disponible))}</strong>
+      </article>
+    </div>
+    <div class="meter">
+      <div class="meter-fill" style="width:${Math.max(0, Math.min(100, porcentaje))}%"></div>
+    </div>
+    <p class="subtle">${escapeHtml(budget.estadoVisual.etiqueta)}</p>
+    <ul class="stack-list">${categorias}</ul>
+  `;
+}
+
+function renderPacking(equipaje) {
+  const pendingItems = equipaje.pendientes.length > 0
+    ? equipaje.pendientes
+        .map(
+          (item) => `
+            <li class="check-item">
+              <span class="bullet"></span>
+              <span>${escapeHtml(item.nombre)}</span>
+            </li>
+          `
+        )
+        .join("")
+    : `<li class="empty">La valija ya está casi lista.</li>`;
+
+  return `
+    <div class="metric-grid">
+      <article class="metric">
+        <span>Completados</span>
+        <strong>${equipaje.progreso.completados}/${equipaje.progreso.total}</strong>
+      </article>
+      <article class="metric">
+        <span>Pendientes</span>
+        <strong>${equipaje.progreso.pendientes}</strong>
+      </article>
+      <article class="metric">
+        <span>Progreso</span>
+        <strong>${equipaje.progreso.porcentaje}%</strong>
+      </article>
+    </div>
+    <div class="meter">
+      <div class="meter-fill luggage" style="width:${equipaje.progreso.porcentaje}%"></div>
+    </div>
+    <ul class="stack-list">${pendingItems}</ul>
+  `;
+}
+
+function renderMemories(recuerdos) {
+  const favorites = recuerdos.favoritos.length > 0
+    ? recuerdos.favoritos
+        .map(
+          (item) => `
+            <li class="memory-card">
+              <span class="tag">${escapeHtml(item.tipo ?? "recuerdo")}</span>
+              <strong>${escapeHtml(item.nombre ?? item.titulo ?? item.title ?? "Sin nombre")}</strong>
+            </li>
+          `
+        )
+        .join("")
+    : `<li class="empty">Todavía no hay recuerdos destacados.</li>`;
+
+  const notes = recuerdos.notas.length > 0
+    ? recuerdos.notas
+        .map(
+          (item) => `
+            <li class="note-card">
+              <strong>${escapeHtml(item.texto)}</strong>
+              <span>${escapeHtml(item.diaId ?? item.paradaId ?? "Sin contexto")}</span>
+            </li>
+          `
+        )
+        .join("")
+    : `<li class="empty">Aún no se registraron notas.</li>`;
+
+  return `
+    <div class="split-grid">
+      <div>
+        <p class="eyebrow">Favoritos</p>
+        <ul class="card-list">${favorites}</ul>
+      </div>
+      <div>
+        <p class="eyebrow">Notas</p>
+        <ul class="card-list">${notes}</ul>
+      </div>
+    </div>
+  `;
+}
+
+function renderEvents(events) {
+  return events.length > 0
+    ? events
+        .map(
+          (evento) => `
+            <li class="event-row">
+              <div class="event-date">${escapeHtml(evento.subtitulo)}</div>
+              <div class="event-copy">
+                <strong>${escapeHtml(evento.titulo)}</strong>
+                <span>${escapeHtml(evento.detalle)}</span>
+              </div>
+            </li>
+          `
+        )
+        .join("")
+    : `<li class="empty">No hay eventos próximos cargados.</li>`;
+}
+
+export function renderDashboard(root, options = {}) {
+  const model = crearDashboardModel(options);
+  root.innerHTML = `
+    <main class="dashboard-shell">
+      <section class="hero">
+        <div>
+          <p class="eyebrow">Dashboard del viaje</p>
+          <h1>${escapeHtml(model.viaje.nombre)}</h1>
+          <p class="hero-meta">${escapeHtml(model.viaje.etiqueta)}</p>
+        </div>
+        <div class="hero-stats" aria-label="Resumen del viaje">
+          <div>
+            <span>Paradas</span>
+            <strong>${model.viaje.paradas}</strong>
+          </div>
+          <div>
+            <span>Actividades</span>
+            <strong>${model.viaje.actividades}</strong>
+          </div>
+          <div>
+            <span>Rango</span>
+            <strong>${escapeHtml(model.viaje.etiqueta)}</strong>
+          </div>
+        </div>
+      </section>
+
+      <section class="panel span-2" aria-labelledby="itinerario-title">
+        <div class="section-head">
+          <div>
+            <p class="eyebrow">Itinerario</p>
+            <h2 id="itinerario-title">Próximos eventos</h2>
+          </div>
+          <p class="section-note">Paradas y actividades ordenadas para ver el viaje de un vistazo.</p>
+        </div>
+        <ul class="event-list">${renderEvents(model.itinerario.proximosEventos)}</ul>
+      </section>
+
+      <section class="panel" aria-labelledby="presupuesto-title">
+        <div class="section-head">
+          <div>
+            <p class="eyebrow">Organización</p>
+            <h2 id="presupuesto-title">Resumen de presupuesto</h2>
+          </div>
+        </div>
+        ${renderBudget(model.organizacion.presupuesto)}
+      </section>
+
+      <section class="panel" aria-labelledby="equipaje-title">
+        <div class="section-head">
+          <div>
+            <p class="eyebrow">Organización</p>
+            <h2 id="equipaje-title">Progreso de equipaje</h2>
+          </div>
+        </div>
+        ${renderPacking(model.organizacion.equipaje)}
+      </section>
+
+      <section class="panel span-2" aria-labelledby="recuerdos-title">
+        <div class="section-head">
+          <div>
+            <p class="eyebrow">Recuerdos</p>
+            <h2 id="recuerdos-title">Recuerdos destacados</h2>
+          </div>
+          <p class="section-note">Favoritos y notas que mantienen visible la parte emocional del viaje.</p>
+        </div>
+        ${renderMemories(model.recuerdos)}
+      </section>
+    </main>
+  `;
+
+  return model;
+}
+
+export default {
+  crearDashboardModel,
+  renderDashboard
+};
