  const total = toNumber(presupuesto.total);
  const gastos = extraerGastos(presupuesto);
  const gastosPorCategoria = agruparGastosPorCategoria(gastos);
  const gastado = gastosPorCategoria.reduce((acumulado, gasto) => acumulado + gasto.gasto, 0);
  const disponible = total - gastado;
  const porcentajeGastado = total > 0 ? gastado / total : 0;
  const porcentajeDisponible = total > 0 ? disponible / total : 0;

  return {
    total,
    gastado,
    disponible,
    porcentajeGastado,
    porcentajeDisponible,
    gastosPorCategoria,
    estadoVisual: obtenerEstadoPresupuesto({ total, gastado, disponible })
  };
