+import { listActividades } from "../agenda/agenda.mjs";
+import { listParadas } from "../paradas/paradas.mjs";
+
+function isObject(value) {
+  return value !== null && typeof value === "object" && !Array.isArray(value);
+}
+
+function normalizeText(value) {
+  return String(value ?? "").trim().toLocaleLowerCase("es");
+}
+
+function matchesText(value, query) {
+  const normalizedQuery = normalizeText(query);
+  if (normalizedQuery === "") {
+    return true;
+  }
+
+  return normalizeText(value).includes(normalizedQuery);
+}
+
+function matchesAnyText(values, query) {
+  return values.some((value) => matchesText(value, query));
+}
+
+function filterByFields(items, fields, query) {
+  return items.filter((item) => matchesAnyText(fields.map((field) => item[field]), query));
+}
+
+function coerceCriteria(criteria) {
+  if (typeof criteria === "string") {
+    return { query: criteria };
+  }
+
+  if (!isObject(criteria)) {
+    return {};
+  }
+
+  return criteria;
+}
+
+function cloneParada(parada) {
+  return {
+    id: parada.id,
+    nombre: parada.nombre,
+    fechaInicio: parada.fechaInicio,
+    fechaFin: parada.fechaFin,
+    descripcion: parada.descripcion
+  };
+}
+
+function cloneActividad(actividad) {
+  return {
+    id: actividad.id,
+    fecha: actividad.fecha,
+    paradaId: actividad.paradaId,
+    horario: actividad.horario,
+    estado: actividad.estado
+  };
+}
+
+function filterParadasByCriteria(parada, criteria) {
+  const { query, nombre, descripcion, fechaInicio, fechaFin } = criteria;
+
+  if (!matchesText(parada.nombre, query)) {
+    return false;
+  }
+
+  if (nombre !== undefined && !matchesText(parada.nombre, nombre)) {
+    return false;
+  }
+
+  if (descripcion !== undefined && !matchesText(parada.descripcion, descripcion)) {
+    return false;
+  }
+
+  if (fechaInicio !== undefined && !matchesText(parada.fechaInicio, fechaInicio)) {
+    return false;
+  }
+
+  if (fechaFin !== undefined && !matchesText(parada.fechaFin, fechaFin)) {
+    return false;
+  }
+
+  return true;
+}
+
+function filterActividadesByCriteria(actividad, criteria, paradasById) {
+  const { query, fecha, paradaId, horario, estado } = criteria;
+  const parada = paradasById.get(actividad.paradaId);
+  const searchableValues = [
+    actividad.id,
+    actividad.fecha,
+    actividad.paradaId,
+    parada?.nombre,
+    actividad.horario,
+    actividad.estado
+  ];
+
+  if (!matchesAnyText(searchableValues, query)) {
+    return false;
+  }
+
+  if (fecha !== undefined && !matchesText(actividad.fecha, fecha)) {
+    return false;
+  }
+
+  if (paradaId !== undefined && !matchesText(actividad.paradaId, paradaId)) {
+    return false;
+  }
+
+  if (horario !== undefined && !matchesText(actividad.horario, horario)) {
+    return false;
+  }
+
+  if (estado !== undefined && !matchesText(actividad.estado, estado)) {
+    return false;
+  }
+
+  return true;
+}
+
+export function explorarParadas(criteria = {}) {
+  const paradas = listParadas();
+  const normalizedCriteria = coerceCriteria(criteria);
+  const filtered = paradas.filter((parada) => filterParadasByCriteria(parada, normalizedCriteria));
+  return filtered.map(cloneParada);
+}
+
+export function buscarParadas(query = "") {
+  return explorarParadas({ query });
+}
+
+export function filtrarParadas(criteria = {}) {
+  return explorarParadas(criteria);
+}
+
+export function explorarActividades(criteria = {}) {
+  const actividades = listActividades();
+  const paradasById = new Map(listParadas().map((parada) => [parada.id, parada]));
+  const normalizedCriteria = coerceCriteria(criteria);
+  const filtered = actividades.filter((actividad) => filterActividadesByCriteria(actividad, normalizedCriteria, paradasById));
+  return filtered.map(cloneActividad);
+}
+
+export function buscarActividades(query = "") {
+  return explorarActividades({ query });
+}
+
+export function filtrarActividades(criteria = {}) {
+  return explorarActividades(criteria);
+}
