+      </section>
+    </main>
+  `;
+}
+
+export function bootstrapDashboard(root = document.getElementById("app")) {
+  if (!root) {
+    return null;
+  }
+
+  root.innerHTML = renderDashboardMarkup();
+  return root;
+}
+
diff --git a/src/dashboard/dashboard.test.mjs b/src/dashboard/dashboard.test.mjs
