index 0000000000000000000000000000000000000000..0308de8e2db8cafde58c188fb0faf9fad0658500
--- /dev/null
+++ b/src/dashboard/dashboard.mjs
@@ -0,0 +1,503 @@
+import { listParadas } from "../itinerary/paradas/paradas.mjs";
+import { listActividades } from "../itinerary/agenda/agenda.mjs";
+import { obtenerPresupuestoGuardado, resumirPresupuesto } from "../organizacion/presupuesto/presupuesto.mjs";
+import { crearChecklistEquipaje } from "../organizacion/equipaje/equipaje.mjs";
+import { createFavoritosStore } from "../recuerdos/favoritos/favoritos.mjs";
+import { listarNotas } from "../recuerdos/notas/notas.mjs";
+
+const MONTHS = [
+  "ene",
+  "feb",
+  "mar",
+  "abr",
+  "may",
+  "jun",
+  "jul",
+  "ago",
+  "sep",
+  "oct",
+  "nov",
+  "dic"
+];
+
+const DEFAULT_TRIP_NAME = "Viaje en Familia";
+
+function escapeHtml(value) {
+  return String(value)
+    .replaceAll("&", "&amp;")
+    .replaceAll("<", "&lt;")
+    .replaceAll(">", "&gt;")
+    .replaceAll('"', "&quot;")
+    .replaceAll("'", "&#39;");
+}
+
+function toArray(value) {
+  return Array.isArray(value) ? value : [];
+}
+
+function isIsoDate(value) {
+  return typeof value === "string" && /^\d{4}-\d{2}-\d{2}$/.test(value);
+}
+
+function parseIsoDate(value) {
+  if (!isIsoDate(value)) {
+    return null;
+  }
+
+  const [year, month, day] = value.split("-").map(Number);
+  return new Date(Date.UTC(year, month - 1, day));
+}
+
+function compareIsoDates(a, b) {
+  if (a === b) {
+    return 0;
+  }
+
+  if (!isIsoDate(a)) {
+    return 1;
+  }
+
+  if (!isIsoDate(b)) {
+    return -1;
+  }
+
+  return a.localeCompare(b);
+}
+
+function formatIsoDate(value) {
+  const date = parseIsoDate(value);
+  if (!date) {
+    return "";
+  }
+
+  const day = date.getUTCDate();
+  const month = MONTHS[date.getUTCMonth()] ?? "";
+  const year = date.getUTCFullYear();
+  return `${day} ${month} ${year}`;
+}
+
+function formatDateRange(start, end) {
+  const startLabel = formatIsoDate(start);
+  const endLabel = formatIsoDate(end);
+
+  if (startLabel && endLabel) {
+    if (start === end) {
+      return startLabel;
+    }
+
+    return `${startLabel} - ${endLabel}`;
+  }
+
+  return startLabel || endLabel || "Fechas por definir";
+}
+
+function formatMoney(value) {
+  const number = Number(value);
+  if (!Number.isFinite(number)) {
+    return "$0";
+  }
+
+  return new Intl.NumberFormat("es-AR", {
+    style: "currency",
+    currency: "ARS",
+    maximumFractionDigits: 0
+  }).format(number);
+}
+
+function normalizeTripName(value) {
+  const text = typeof value === "string" ? value.trim() : "";
+  return text || DEFAULT_TRIP_NAME;
+}
+
+function resolveTripRange(paradas) {
+  const validDates = toArray(paradas)
+    .flatMap((parada) => [parada?.fechaInicio, parada?.fechaFin])
+    .filter(isIsoDate)
+    .sort(compareIsoDates);
+
+  if (validDates.length === 0) {
+    return {
+      start: "",
+      end: "",
+      label: "Fechas por definir"
+    };
+  }
+
+  return {
+    start: validDates[0],
+    end: validDates[validDates.length - 1],
+    label: formatDateRange(validDates[0], validDates[validDates.length - 1])
+  };
+}
+
+function resolveParadaName(paradas, paradaId) {
+  if (!paradaId) {
+    return "Parada sin nombre";
+  }
+
+  const match = toArray(paradas).find((parada) => parada?.id === paradaId);
+  return typeof match?.nombre === "string" && match.nombre.trim() ? match.nombre.trim() : "Parada";
+}
+
+function resolveUpcomingEvents({ paradas, actividades, today }) {
+  const reference = isIsoDate(today) ? today : "";
+  const events = toArray(actividades)
+    .filter((actividad) => isIsoDate(actividad?.fecha))
+    .map((actividad) => ({
+      fecha: actividad.fecha,
+      hora: typeof actividad?.horario === "string" ? actividad.horario.trim() : "",
+      titulo: typeof actividad?.horario === "string" && actividad.horario.trim()
+        ? `${actividad.horario.trim()} · ${resolveParadaName(paradas, actividad.paradaId)}`
+        : resolveParadaName(paradas, actividad.paradaId),
+      descripcion: typeof actividad?.estado === "string" && actividad.estado === "completada"
+        ? "Completada"
+        : "Pendiente",
+      estado: typeof actividad?.estado === "string" ? actividad.estado : "pendiente"
+    }))
+    .sort((a, b) => {
+      const dateOrder = compareIsoDates(a.fecha, b.fecha);
+      if (dateOrder !== 0) {
+        return dateOrder;
+      }
+
+      return a.hora.localeCompare(b.hora);
+    });
+
+  const upcoming = reference
+    ? events.filter((event) => event.fecha >= reference)
+    : events;
+
+  const source = upcoming.length > 0 ? upcoming : events;
+
+  return source.slice(0, 4).map((event) => ({
+    ...event,
+    fechaLabel: formatIsoDate(event.fecha)
+  }));
+}
+
+function normalizeBudget(summary) {
+  if (summary && typeof summary === "object" && summary.estadoVisual && Array.isArray(summary.gastosPorCategoria)) {
+    return summary;
+  }
+
+  return resumirPresupuesto(summary && typeof summary === "object" ? summary : {});
+}
+
+function normalizePacking(checklist) {
+  const items = toArray(checklist?.items)
+    .filter((item) => item && typeof item === "object")
+    .map((item) => ({
+      id: item.id,
+      nombre: typeof item.nombre === "string" ? item.nombre.trim() : "",
+      completado: Boolean(item.completado)
+    }))
+    .filter((item) => item.nombre);
+
+  const completados = items.filter((item) => item.completado).length;
+  const total = items.length;
+  const pendientes = total - completados;
+  const porcentaje = total === 0 ? 0 : Math.round((completados / total) * 100);
+
+  return {
+    total,
+    completados,
+    pendientes,
+    porcentaje,
+    items
+  };
+}
+
+function normalizeMemories({ favoritos, notas }) {
+  const favoriteItems = toArray(favoritos)
+    .filter((item) => item && typeof item === "object")
+    .map((item) => ({
+      nombre: typeof item.nombre === "string" ? item.nombre.trim() : "",
+      tipo: typeof item.tipo === "string" ? item.tipo.trim() : ""
+    }))
+    .filter((item) => item.nombre)
+    .slice(0, 3);
+
+  const noteItems = toArray(notas)
+    .filter((item) => item && typeof item === "object")
+    .map((item) => ({
+      texto: typeof item.texto === "string" ? item.texto.trim() : "",
+      diaId: typeof item.diaId === "string" ? item.diaId.trim() : "",
+      paradaId: typeof item.paradaId === "string" ? item.paradaId.trim() : ""
+    }))
+    .filter((item) => item.texto)
+    .slice(0, 3);
+
+  return {
+    favoritos: favoriteItems,
+    notas: noteItems
+  };
+}
+
+export function buildDashboardModel({
+  tripName = DEFAULT_TRIP_NAME,
+  today = "",
+  paradas = [],
+  actividades = [],
+  presupuesto = {},
+  equipaje = {},
+  favoritos = [],
+  notas = []
+} = {}) {
+  const range = resolveTripRange(paradas);
+  const budget = normalizeBudget(presupuesto);
+  const packing = normalizePacking(equipaje);
+  const memories = normalizeMemories({ favoritos, notas });
+
+  return {
+    tripName: normalizeTripName(tripName),
+    tripRange: range,
+    stopsCount: toArray(paradas).length,
+    eventsCount: toArray(actividades).length,
+    upcomingEvents: resolveUpcomingEvents({ paradas, actividades, today }),
+    budget,
+    packing,
+    memories
+  };
+}
+
+export function createDashboardSnapshot() {
+  const checklist = crearChecklistEquipaje();
+  const favoritosStore = createFavoritosStore();
+
+  return buildDashboardModel({
+    tripName: DEFAULT_TRIP_NAME,
+    today: new Date().toISOString().slice(0, 10),
+    paradas: listParadas(),
+    actividades: listActividades(),
+    presupuesto: obtenerPresupuestoGuardado(),
+    equipaje: checklist.get(),
+    favoritos: favoritosStore.listarFavoritos(),
+    notas: listarNotas()
+  });
+}
+
+function renderListItems(items, emptyLabel, renderItem) {
+  if (!items.length) {
+    return `<li class="empty-state">${escapeHtml(emptyLabel)}</li>`;
+  }
+
+  return items.map(renderItem).join("");
+}
+
+function renderBudgetCategories(categories) {
+  if (!categories.length) {
+    return `<li class="empty-state">Sin gastos registrados</li>`;
+  }
+
+  return categories
+    .map(
+      (item) => `
+        <li class="mini-row">
+          <span>${escapeHtml(item.categoria)}</span>
+          <strong>${escapeHtml(formatMoney(item.gasto))}</strong>
+        </li>`
+    )
+    .join("");
+}
+
+function renderPackingItems(items) {
+  if (!items.length) {
+    return `<li class="empty-state">Checklist vacío</li>`;
+  }
+
+  return items
+    .map(
+      (item) => `
+        <li class="mini-row ${item.completado ? "is-done" : "is-pending"}">
+          <span>${escapeHtml(item.nombre)}</span>
+          <strong>${item.completado ? "Listo" : "Pendiente"}</strong>
+        </li>`
+    )
+    .join("");
+}
+
+function renderMemoryItems(model) {
+  const items = [
+    ...model.memories.favoritos.map((item) => ({
+      label: "Favorito",
+      text: item.nombre,
+      tone: "accent"
+    })),
+    ...model.memories.notas.map((item) => ({
+      label: item.diaId ? "Nota del día" : "Nota de parada",
+      text: item.texto,
+      tone: "neutral"
+    }))
+  ];
+
+  if (!items.length) {
+    return `<li class="empty-state">Todavía no hay recuerdos destacados</li>`;
+  }
+
+  return items
+    .map(
+      (item) => `
+        <li class="memory-card memory-card--${item.tone}">
+          <span class="memory-card__label">${escapeHtml(item.label)}</span>
+          <p>${escapeHtml(item.text)}</p>
+        </li>`
+    )
+    .join("");
+}
+
+export function renderDashboardMarkup(model = createDashboardSnapshot()) {
+  const heroClasses = ["hero-status"];
+  if (model.budget?.estadoVisual?.tono) {
+    heroClasses.push(`hero-status--${model.budget.estadoVisual.tono}`);
+  }
+
+  return `
+    <main class="dashboard-shell" id="contenido">
+      <section class="hero-card">
+        <div class="hero-copy">
+          <p class="eyebrow">Dashboard del viaje</p>
+          <h1>${escapeHtml(model.tripName)}</h1>
+          <p class="hero-dates">${escapeHtml(model.tripRange.label)}</p>
+          <p class="hero-meta">
+            ${escapeHtml(String(model.stopsCount))} paradas planificadas
+            <span aria-hidden="true">•</span>
+            ${escapeHtml(String(model.eventsCount))} eventos próximos
+          </p>
+        </div>
+        <aside class="${heroClasses.join(" ")}" aria-label="Estado del presupuesto">
+          <span class="hero-status__label">${escapeHtml(model.budget.estadoVisual.etiqueta)}</span>
+          <strong>${escapeHtml(formatMoney(model.budget.disponible))}</strong>
+          <small>Disponible para el resto del viaje</small>
+        </aside>
+      </section>
+
+      <section class="dashboard-grid" aria-label="Resumen del viaje">
+        <article class="panel panel--itinerary">
+          <div class="panel__header">
+            <div>
+              <p class="panel__kicker">Itinerario</p>
+              <h2>Próximos eventos</h2>
+            </div>
+            <span class="panel__badge">${escapeHtml(model.tripRange.label)}</span>
+          </div>
+
+          <div class="timeline-summary">
+            <div class="timeline-summary__range">
+              <span>Salida</span>
+              <strong>${escapeHtml(formatIsoDate(model.tripRange.start) || "Por definir")}</strong>
+            </div>
+            <div class="timeline-summary__range">
+              <span>Llegada</span>
+              <strong>${escapeHtml(formatIsoDate(model.tripRange.end) || "Por definir")}</strong>
+            </div>
+          </div>
+
+          <ul class="event-list">
+            ${renderListItems(model.upcomingEvents, "No hay eventos programados", (event) => `
+              <li class="event-card">
+                <div class="event-card__date">
+                  <span>${escapeHtml(event.fechaLabel)}</span>
+                  <strong>${escapeHtml(event.hora || "Todo el día")}</strong>
+                </div>
+                <div class="event-card__body">
+                  <h3>${escapeHtml(event.titulo)}</h3>
+                  <p>${escapeHtml(event.descripcion)}</p>
+                </div>
+                <span class="status-pill status-pill--${escapeHtml(event.estado)}">${escapeHtml(event.estado)}</span>
+              </li>`)}
+          </ul>
+        </article>
+
+        <article class="panel panel--organization">
+          <div class="panel__header">
+            <div>
+              <p class="panel__kicker">Organización</p>
+              <h2>Resumen de presupuesto</h2>
+            </div>
+            <span class="panel__badge">${escapeHtml(model.budget.estadoVisual.etiqueta)}</span>
+          </div>
+
+          <div class="budget-figure">
+            <div>
+              <span>Total</span>
+              <strong>${escapeHtml(formatMoney(model.budget.total))}</strong>
+            </div>
+            <div>
+              <span>Gastado</span>
+              <strong>${escapeHtml(formatMoney(model.budget.gastado))}</strong>
+            </div>
+            <div>
+              <span>Disponible</span>
+              <strong>${escapeHtml(formatMoney(model.budget.disponible))}</strong>
+            </div>
+          </div>
+
+          <div class="progress-block">
+            <div class="progress-block__header">
+              <span>Uso del presupuesto</span>
+              <strong>${escapeHtml(String(Math.round((model.budget.porcentajeGastado ?? 0) * 100)))}%</strong>
+            </div>
+            <div class="progress-track" aria-hidden="true">
+              <div class="progress-fill progress-fill--budget" style="width: ${Math.min(100, Math.max(0, Math.round((model.budget.porcentajeGastado ?? 0) * 100)))}%"></div>
+            </div>
+          </div>
+
+          <ul class="compact-list">
+            ${renderBudgetCategories(model.budget.gastosPorCategoria)}
+          </ul>
+
+          <div class="progress-block">
+            <div class="progress-block__header">
+              <span>Progreso de equipaje</span>
+              <strong>${escapeHtml(String(model.packing.porcentaje))}%</strong>
+            </div>
+            <div class="progress-track" aria-hidden="true">
+              <div class="progress-fill progress-fill--packing" style="width: ${Math.min(100, Math.max(0, model.packing.porcentaje))}%"></div>
+            </div>
+            <p class="support-text">
+              ${escapeHtml(String(model.packing.completados))} listos y ${escapeHtml(String(model.packing.pendientes))} pendientes
+            </p>
+          </div>
+
+          <ul class="compact-list compact-list--packing">
+            ${renderPackingItems(model.packing.items.slice(0, 4))}
+          </ul>
+        </article>
+
+        <article class="panel panel--memories">
+          <div class="panel__header">
+            <div>
+              <p class="panel__kicker">Recuerdos</p>
+              <h2>Destacados</h2>
+            </div>
+            <span class="panel__badge">Favoritos y notas</span>
+          </div>
+
+          <div class="memory-intro">
+            <span class="memory-intro__metric">
+              <strong>${escapeHtml(String(model.memories.favoritos.length))}</strong>
+              <small>favoritos</small>
+            </span>
+            <span class="memory-intro__metric">
+              <strong>${escapeHtml(String(model.memories.notas.length))}</strong>
+              <small>notas</small>
+            </span>
+          </div>
+
+          <ul class="memory-list">
+            ${renderMemoryItems(model)}
+          </ul>
+        </article>
+      </section>
+    </main>
+  `;
+}
+
+export function bootstrapDashboard(root = document.getElementById("app")) {
+  if (!root) {
+    return null;
+  }
+
+  root.innerHTML = renderDashboardMarkup();
+  return root;
+}
