+:root {
+  color-scheme: dark;
+  --bg: #07111f;
+  --bg-elevated: rgba(10, 18, 32, 0.82);
+  --bg-card: #ffffff;
+  --bg-soft: #f3f6fb;
+  --text: #0b1220;
+  --text-muted: #42526b;
+  --hero-text: #f4f7fb;
+  --hero-muted: rgba(244, 247, 251, 0.76);
+  --accent: #ffbf47;
+  --accent-strong: #e08a00;
+  --success: #13795b;
+  --warning: #a05400;
+  --critical: #b42318;
+  --neutral: #55637b;
+  --border: rgba(8, 16, 31, 0.12);
+  --shadow-lg: 0 28px 80px rgba(6, 10, 20, 0.32);
+  --shadow-md: 0 18px 40px rgba(6, 10, 20, 0.18);
+  --radius-xl: 28px;
+  --radius-lg: 22px;
+  --radius-md: 16px;
+  --radius-sm: 12px;
+  --max-width: 1180px;
+  font-family: Inter, "Segoe UI", system-ui, -apple-system, BlinkMacSystemFont, sans-serif;
+}
+
+* {
+  box-sizing: border-box;
+}
+
+html {
+  min-height: 100%;
+}
+
+body {
+  margin: 0;
+  min-height: 100vh;
+  color: var(--hero-text);
+  background:
+    radial-gradient(circle at top left, rgba(255, 191, 71, 0.22), transparent 32%),
+    radial-gradient(circle at 85% 10%, rgba(69, 123, 157, 0.3), transparent 24%),
+    linear-gradient(180deg, #06101e 0%, #0b1527 100%);
+}
+
+body::before {
+  content: "";
+  position: fixed;
+  inset: 0;
+  pointer-events: none;
+  background-image:
+    linear-gradient(rgba(255, 255, 255, 0.03) 1px, transparent 1px),
+    linear-gradient(90deg, rgba(255, 255, 255, 0.03) 1px, transparent 1px);
+  background-size: 52px 52px;
+  mask-image: radial-gradient(circle at center, rgba(0, 0, 0, 0.9), transparent 88%);
+  opacity: 0.38;
+}
+
+a {
+  color: inherit;
+}
+
+.skip-link {
+  position: absolute;
+  left: 1rem;
+  top: 1rem;
+  z-index: 30;
+  padding: 0.8rem 1.1rem;
+  border-radius: 999px;
+  background: #ffffff;
+  color: #08111f;
+  text-decoration: none;
+  transform: translateY(-160%);
+  transition: transform 140ms ease;
+  box-shadow: var(--shadow-md);
+}
+
+.skip-link:focus-visible {
+  transform: translateY(0);
+  outline: 3px solid var(--accent);
+  outline-offset: 4px;
+}
+
+#app {
+  width: 100%;
+}
+
+.dashboard-shell {
+  width: min(calc(100% - 2rem), var(--max-width));
+  margin: 0 auto;
+  padding: 2rem 0 3rem;
+}
+
+.hero-card {
+  display: grid;
+  gap: 1.5rem;
+  grid-template-columns: minmax(0, 1fr) minmax(240px, 300px);
+  align-items: stretch;
+  padding: 2rem;
+  border-radius: var(--radius-xl);
+  background:
+    linear-gradient(145deg, rgba(13, 21, 37, 0.98), rgba(7, 14, 26, 0.94)),
+    linear-gradient(135deg, rgba(255, 191, 71, 0.2), transparent 54%);
+  box-shadow: var(--shadow-lg);
+  border: 1px solid rgba(255, 255, 255, 0.08);
+}
+
+.hero-copy h1 {
+  margin: 0;
+  font-size: clamp(2.2rem, 5vw, 4.6rem);
+  line-height: 0.96;
+  letter-spacing: -0.05em;
+  max-width: 10ch;
+}
+
+.eyebrow,
+.panel__kicker {
+  margin: 0 0 0.75rem;
+  text-transform: uppercase;
+  letter-spacing: 0.18em;
+  font-size: 0.74rem;
+  font-weight: 700;
+  color: var(--accent);
+}
+
+.hero-dates {
+  margin: 1rem 0 0;
+  font-size: clamp(1.05rem, 2vw, 1.35rem);
+  font-weight: 700;
+}
+
+.hero-meta,
+.support-text {
+  margin: 0.6rem 0 0;
+  color: var(--hero-muted);
+}
+
+.hero-status {
+  display: grid;
+  gap: 0.6rem;
+  align-content: center;
+  padding: 1.3rem;
+  border-radius: var(--radius-lg);
+  background: rgba(255, 255, 255, 0.08);
+  border: 1px solid rgba(255, 255, 255, 0.12);
+}
+
+.hero-status strong {
+  font-size: clamp(2rem, 4vw, 2.8rem);
+  line-height: 1;
+}
+
+.hero-status__label {
+  display: inline-flex;
+  width: fit-content;
+  align-items: center;
+  gap: 0.4rem;
+  padding: 0.4rem 0.7rem;
+  border-radius: 999px;
+  background: rgba(255, 255, 255, 0.11);
+  text-transform: uppercase;
+  font-size: 0.72rem;
+  letter-spacing: 0.16em;
+  font-weight: 700;
+}
