+
+@media (max-width: 700px) {
+  .dashboard {
+    padding: 16px;
+  }
+
+  .hero,
+  .panel {
+    padding: 18px;
+  }
+
+  .hero__meta,
+  .budget__summary,
+  .memory-list {
+    grid-template-columns: 1fr;
+  }
+
+  .event {
+    grid-template-columns: 1fr;
+  }
+
+  .panel__header {
+    flex-direction: column;
+  }
+
+  .luggage__headline {
+    flex-direction: column;
+    align-items: flex-start;
+  }
+}
diff --git a/src/dashboard/dashboard.mjs b/src/dashboard/dashboard.mjs
new file mode 100644
index 0000000000000000000000000000000000000000..3536c4a037d3f7110292a7d4c91d490438f4a24b
--- /dev/null
+++ b/src/dashboard/dashboard.mjs
@@ -0,0 +1,415 @@
+import { listParadas } from "../itinerary/paradas/paradas.mjs";
+import { listActividades } from "../itinerary/agenda/agenda.mjs";
+import { obtenerPresupuestoGuardado } from "../organizacion/presupuesto/presupuesto.mjs";
+import { crearChecklistEquipaje } from "../organizacion/equipaje/equipaje.mjs";
+import { createFavoritosStore } from "../recuerdos/favoritos/favoritos.mjs";
+import { listarNotas } from "../recuerdos/notas/notas.mjs";
+
+const DATE_FORMAT = new Intl.DateTimeFormat("es-AR", {
+  day: "2-digit",
+  month: "short",
+  year: "numeric"
+});
+
+const NUMBER_FORMAT = new Intl.NumberFormat("es-AR", {
+  maximumFractionDigits: 0
+});
+
+const MONTHS = ["ene.", "feb.", "mar.", "abr.", "may.", "jun.", "jul.", "ago.", "sept.", "oct.", "nov.", "dic."];
+
+function escapeHtml(value) {
+  return String(value)
+    .replaceAll("&", "&amp;")
+    .replaceAll("<", "&lt;")
+    .replaceAll(">", "&gt;")
+    .replaceAll('"', "&quot;")
+    .replaceAll("'", "&#39;");
+}
+
+function toIsoDate(value) {
+  if (typeof value !== "string" || value.length < 10) {
+    return null;
+  }
+
+  const candidate = value.slice(0, 10);
+  return /^\d{4}-\d{2}-\d{2}$/.test(candidate) ? candidate : null;
+}
+
+function parseDateTime(fecha, horario = "") {
+  const isoDate = toIsoDate(fecha);
+  if (!isoDate) {
+    return Number.POSITIVE_INFINITY;
+  }
+
+  const normalizedTime = typeof horario === "string" && /^\d{2}:\d{2}$/.test(horario) ? `${horario}:00` : "00:00:00";
+  const timestamp = Date.parse(`${isoDate}T${normalizedTime}`);
+  return Number.isFinite(timestamp) ? timestamp : Number.POSITIVE_INFINITY;
+}
+
+function formatDate(value) {
+  const isoDate = toIsoDate(value);
+  if (!isoDate) {
+    return value ? String(value) : "Fechas por definir";
+  }
+
+  const [year, month, day] = isoDate.split("-").map(Number);
+  return `${String(day).padStart(2, "0")} ${MONTHS[month - 1]} ${year}`;
+}
+
+function formatDateTime(fecha, horario) {
+  const date = formatDate(fecha);
+  return horario ? `${date}, ${horario}` : date;
+}
+
+function formatNumber(value) {
+  const numeric = Number(value);
+  return NUMBER_FORMAT.format(Number.isFinite(numeric) ? numeric : 0);
+}
+
+function getTripWindow(paradas) {
+  const dates = paradas
+    .map((parada) => ({
+      inicio: toIsoDate(parada.fechaInicio),
+      fin: toIsoDate(parada.fechaFin)
+    }))
+    .filter((parada) => parada.inicio || parada.fin);
+
+  if (dates.length === 0) {
+    return {
+      start: null,
+      end: null
+    };
+  }
+
+  const starts = dates.map((parada) => parada.inicio ?? parada.fin).filter(Boolean).sort();
+  const ends = dates.map((parada) => parada.fin ?? parada.inicio).filter(Boolean).sort();
+
+  return {
+    start: starts[0] ?? null,
+    end: ends.at(-1) ?? null
+  };
+}
+
+function getTripName() {
+  return "Viaje en Familia";
+}
+
+function getParadaNameById(paradas, paradaId) {
+  return paradas.find((parada) => parada.id === paradaId)?.nombre ?? "Parada sin nombre";
+}
+
+function getUpcomingEvents(actividades, paradas, limit = 4) {
+  const sorted = actividades
+    .map((actividad) => ({
+      ...actividad,
+      timestamp: parseDateTime(actividad.fecha, actividad.horario),
+      paradaNombre: getParadaNameById(paradas, actividad.paradaId)
+    }))
+    .sort((a, b) => a.timestamp - b.timestamp);
+
+  const now = Date.now();
+  const future = sorted.filter((actividad) => actividad.timestamp >= now);
+  const source = future.length > 0 ? future : sorted;
+
+  return source.slice(0, limit).map((actividad) => ({
+    ...actividad,
+    fechaTexto: formatDateTime(actividad.fecha, actividad.horario)
+  }));
+}
+
+function getMemoryLabel(memory) {
+  return (
+    memory.nombre ??
+    memory.name ??
+    memory.title ??
+    memory.titulo ??
+    memory.texto ??
+    memory.descripcion ??
+    memory.id ??
+    "Recuerdo"
+  );
+}
+
+function getMemoryType(memory) {
+  return memory.tipo ?? memory.type ?? memory.kind ?? memory.categoria ?? "recuerdo";
+}
+
+function getMemoryMeta(memory) {
+  const parts = [];
+  if (memory.paradaId) {
+    parts.push(`Parada ${memory.paradaId}`);
+  }
+  if (memory.diaId) {
+    parts.push(`Día ${memory.diaId}`);
+  }
+  return parts.join(" · ");
+}
+
+function buildMemoryHighlights(favoritos, notas, limit = 4) {
+  const favoriteCards = favoritos.map((favorito) => ({
+    type: getMemoryType(favorito),
+    title: getMemoryLabel(favorito),
+    meta: favorito.descripcion ?? favorito.detalle ?? favorito.ubicacion ?? ""
+  }));
+
+  const noteCards = notas.map((nota) => ({
+    type: "nota",
+    title: nota.texto,
+    meta: getMemoryMeta(nota)
+  }));
+
+  return [...favoriteCards, ...noteCards].slice(0, limit);
+}
+
+function buildBudgetSummary() {
+  return obtenerPresupuestoGuardado();
+}
+
+function buildLuggageSummary() {
+  const checklist = crearChecklistEquipaje();
+  const state = checklist.get();
+  const progress = checklist.obtenerProgresoEquipaje();
+  const pendingItems = (state.items ?? []).filter((item) => !item.completado).slice(0, 3);
+
+  return {
+    ...progress,
+    pendingItems
+  };
+}
+
+export function collectDashboardData() {
+  const paradas = listParadas();
+  const actividades = listActividades();
+  const favoritosStore = createFavoritosStore();
+  const favoritos = favoritosStore.get();
+  const notas = listarNotas();
+  const budget = buildBudgetSummary();
+  const luggage = buildLuggageSummary();
+  const tripWindow = getTripWindow(paradas);
+  const upcomingEvents = getUpcomingEvents(actividades, paradas);
+  const memories = buildMemoryHighlights(favoritos, notas);
+
+  return {
+    trip: {
+      name: getTripName(),
+      start: tripWindow.start,
+      end: tripWindow.end,
+      stopCount: paradas.length,
+      activityCount: actividades.length,
+      memoryCount: favoritos.length + notas.length
+    },
+    upcomingEvents,
+    budget,
+    luggage,
+    memories
+  };
+}
+
+export const buildDashboardData = collectDashboardData;
+
+export function buildDashboardMarkup(data = collectDashboardData()) {
+  const tripDates =
+    data.trip.start && data.trip.end
+      ? `<p class="hero__dates">Del <time datetime="${escapeHtml(data.trip.start)}">${escapeHtml(formatDate(data.trip.start))}</time> al <time datetime="${escapeHtml(data.trip.end)}">${escapeHtml(formatDate(data.trip.end))}</time></p>`
+      : `<p class="hero__dates">Fechas del viaje por definir</p>`;
+
+  const budgetPercent = Math.max(0, Math.min(100, Math.round((data.budget.porcentajeGastado ?? 0) * 100)));
+  const luggagePercent = Math.max(0, Math.min(100, data.luggage.porcentaje ?? 0));
+  const statusClass =
+    data.budget.estadoVisual.tono === "critico"
+      ? "status-pill--critical"
+      : data.budget.estadoVisual.tono === "advertencia"
+        ? "status-pill--warning"
+        : "status-pill--positive";
+
+  const eventMarkup =
+    data.upcomingEvents.length > 0
+      ? data.upcomingEvents
+          .map(
+            (actividad) => `
+              <li class="event">
+                <div class="event__time">
+                  <time datetime="${escapeHtml(actividad.fecha)}">${escapeHtml(formatDate(actividad.fecha))}</time>
+                  <small>${escapeHtml(actividad.horario || "Sin horario")}</small>
+                </div>
+                <div>
+                  <p class="event__title">${escapeHtml(actividad.paradaNombre)}</p>
+                  <p class="event__meta">${escapeHtml(actividad.estado)} · ${escapeHtml(actividad.fechaTexto)}</p>
+                </div>
+              </li>`
+          )
+          .join("")
+      : `<li class="empty-state">No hay eventos próximos cargados todavía.</li>`;
+
+  const budgetRows = [
+    { label: "Total", value: formatNumber(data.budget.total) },
+    { label: "Gastado", value: formatNumber(data.budget.gastado) },
+    { label: "Disponible", value: formatNumber(data.budget.disponible) }
+  ]
+    .map(
+      (row) => `
+        <div class="detail-row">
+          <span class="detail-row__label">${escapeHtml(row.label)}</span>
+          <span class="detail-row__value">${escapeHtml(row.value)}</span>
+        </div>`
+    )
+    .join("");
+
+  const luggageItems =
+    data.luggage.pendingItems.length > 0
+      ? data.luggage.pendingItems
+          .map((item) => `<li>${escapeHtml(item.nombre)}</li>`)
+          .join("")
+      : `<li class="empty-state">El equipaje está al día.</li>`;
+
+  const memoryMarkup =
+    data.memories.length > 0
+      ? data.memories
+          .map(
+            (memory) => `
+              <li class="memory-card">
+                <span class="memory-card__type">${escapeHtml(memory.type)}</span>
+                <h3 class="memory-card__title">${escapeHtml(memory.title)}</h3>
+                <p class="memory-card__meta">${escapeHtml(memory.meta || "Destacado del viaje")}</p>
+              </li>`
+          )
+          .join("")
+      : `<li class="empty-state">Aún no hay recuerdos destacados.</li>`;
+
+  return `
+    <main class="dashboard" id="contenido">
+      <a class="skip-link" href="#contenido">Saltar al contenido</a>
+      <header class="hero" aria-labelledby="trip-title">
+        <p class="hero__eyebrow">Itinerario, organización y recuerdos</p>
+        <h1 class="hero__title" id="trip-title">${escapeHtml(data.trip.name)}</h1>
+        ${tripDates}
+        <div class="hero__meta" aria-label="Resumen del viaje">
+          <div class="meta-chip">
+            <span class="meta-chip__label">Paradas</span>
+            <span class="meta-chip__value">${escapeHtml(formatNumber(data.trip.stopCount))}</span>
+          </div>
+          <div class="meta-chip">
+            <span class="meta-chip__label">Eventos</span>
+            <span class="meta-chip__value">${escapeHtml(formatNumber(data.trip.activityCount))}</span>
+          </div>
+          <div class="meta-chip">
+            <span class="meta-chip__label">Recuerdos</span>
+            <span class="meta-chip__value">${escapeHtml(formatNumber(data.trip.memoryCount))}</span>
+          </div>
+          <div class="meta-chip">
+            <span class="meta-chip__label">Equipaje</span>
+            <span class="meta-chip__value">${escapeHtml(formatNumber(data.luggage.porcentaje))}%</span>
+          </div>
+        </div>
+      </header>
+
+      <nav class="section-links" aria-label="Secciones del dashboard">
+        <a href="#itinerario">Itinerario</a>
+        <a href="#presupuesto">Organización</a>
+        <a href="#equipaje">Equipaje</a>
+        <a href="#recuerdos">Recuerdos</a>
+      </nav>
+
+      <section class="dashboard-grid">
+        <article class="panel panel--dark section" id="itinerario">
+          <div class="panel__header">
+            <div>
+              <p class="panel__eyebrow">Itinerario</p>
+              <h2 class="panel__title">Próximos eventos</h2>
+              <p class="panel__description">El recorrido se ordena por fecha y horario para mantener visible lo inmediato.</p>
+            </div>
+            <span class="panel__badge">${escapeHtml(formatNumber(data.upcomingEvents.length))} visibles</span>
+          </div>
+          <ol class="events">
+            ${eventMarkup}
+          </ol>
+        </article>
+
+        <div class="stack">
+          <article class="panel section" id="presupuesto">
+            <div class="panel__header">
+              <div>
+                <p class="panel__eyebrow">Organización</p>
+                <h2 class="panel__title">Resumen de presupuesto</h2>
+                <p class="panel__description">Control visual claro para identificar gasto, saldo disponible y estado general.</p>
+              </div>
+              <span class="status-pill ${statusClass}">${escapeHtml(data.budget.estadoVisual.etiqueta)}</span>
+            </div>
+            <div class="budget">
+              <div class="budget__summary">
+                ${budgetRows}
+              </div>
+              <div class="budget__bar">
+                <div class="progress" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${escapeHtml(String(budgetPercent))}">
+                  <span class="progress__fill" style="--value: ${budgetPercent}%;"></span>
+                </div>
+                <p class="panel__description">Gastado: ${escapeHtml(formatNumber(Math.round((data.budget.porcentajeGastado ?? 0) * 100)))}% del total.</p>
+              </div>
+            </div>
+          </article>
+
+          <article class="panel section" id="equipaje">
+            <div class="panel__header">
+              <div>
+                <p class="panel__eyebrow">Equipaje</p>
+                <h2 class="panel__title">Progreso del checklist</h2>
+                <p class="panel__description">La carga pendiente queda a la vista para completar antes de salir.</p>
+              </div>
+              <span class="panel__badge">${escapeHtml(formatNumber(data.luggage.porcentaje))}% listo</span>
+            </div>
+            <div class="luggage">
+              <div class="luggage__layout">
+                <div class="luggage__headline">
+                  <span>${escapeHtml(formatNumber(data.luggage.completados))} de ${escapeHtml(formatNumber(data.luggage.total))}</span>
+                  <small>Completado</small>
+                </div>
+                <div class="progress" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${escapeHtml(String(luggagePercent))}">
+                  <span class="progress__fill" style="--value: ${luggagePercent}%;"></span>
+                </div>
+              </div>
+              <ul class="luggage-list">
+                ${luggageItems}
+              </ul>
+            </div>
+          </article>
+        </div>
+
+        <article class="panel section memories" id="recuerdos">
+          <div class="panel__header">
+            <div>
+              <p class="panel__eyebrow">Recuerdos</p>
+              <h2 class="panel__title">Momentos destacados</h2>
+              <p class="panel__description">Favoritos y notas recientes se agrupan en una lectura rápida y contrastada.</p>
+            </div>
+            <a class="brand-pill" href="#trip-title">Volver arriba</a>
+          </div>
+          <ul class="memory-list">
+            ${memoryMarkup}
+          </ul>
+        </article>
+      </section>
+    </main>
+  `;
+}
+
+export function mountDashboard(root) {
+  const target =
+    typeof root === "string" && typeof document !== "undefined"
+      ? document.querySelector(root)
+      : root;
+
+  if (!target) {
+    return null;
+  }
+
+  const markup = buildDashboardMarkup();
+  target.innerHTML = markup;
+  return markup;
+}
+
+export default {
+  collectDashboardData,
+  buildDashboardData,
+  buildDashboardMarkup,
+  mountDashboard
+};
diff --git a/src/dashboard/dashboard.test.mjs b/src/dashboard/dashboard.test.mjs
