+:root {
+  color-scheme: light;
+  --bg: #f3efe6;
+  --bg-accent: #efe4d1;
+  --panel: #fffdf8;
+  --panel-strong: #1f2937;
+  --panel-muted: #f7f3ea;
+  --text: #122033;
+  --text-soft: #516074;
+  --text-inverse: #f8fafc;
+  --accent: #0f766e;
+  --accent-soft: #d9f0ed;
+  --accent-strong: #115e59;
+  --warning: #b45309;
+  --warning-soft: #fef3c7;
+  --critical: #b42318;
+  --critical-soft: #fee4e2;
+  --border: rgba(18, 32, 51, 0.12);
+  --shadow: 0 24px 60px rgba(26, 35, 59, 0.16);
+  --radius-xl: 28px;
+  --radius-lg: 20px;
+  --radius-md: 16px;
+  --radius-sm: 12px;
+  --max-width: 1180px;
+}
+
+* {
+  box-sizing: border-box;
+}
+
+html {
+  min-height: 100%;
+  scroll-behavior: smooth;
+}
+
+body {
+  margin: 0;
+  min-height: 100vh;
+  color: var(--text);
+  font-family: "Iowan Old Style", "Palatino Linotype", "Book Antiqua", Georgia, serif;
+  background:
+    radial-gradient(circle at top left, rgba(15, 118, 110, 0.18), transparent 34%),
+    radial-gradient(circle at top right, rgba(180, 83, 9, 0.16), transparent 28%),
+    linear-gradient(180deg, var(--bg) 0%, #faf7f0 48%, #f4efe5 100%);
+}
+
+a {
+  color: inherit;
+}
+
+button,
+a {
+  -webkit-tap-highlight-color: transparent;
+}
+
+#app {
+  width: 100%;
+}
+
+.dashboard {
+  width: min(100%, var(--max-width));
+  margin: 0 auto;
+  padding: 24px;
