+  background:
+    linear-gradient(135deg, rgba(10, 18, 33, 0.96), rgba(18, 54, 73, 0.92)),
+    radial-gradient(circle at top right, rgba(45, 212, 191, 0.22), transparent 28%);
+  box-shadow: var(--shadow);
+}
+
+.hero::before,
+.hero::after {
+  content: "";
+  position: absolute;
+  border-radius: 999px;
+  pointer-events: none;
+}
+
+.hero::before {
+  top: -120px;
+  right: -60px;
+  width: 240px;
+  height: 240px;
+  background: rgba(15, 118, 110, 0.22);
+  filter: blur(8px);
+}
+
+.hero::after {
+  bottom: -80px;
+  left: -40px;
+  width: 180px;
+  height: 180px;
+  background: rgba(180, 83, 9, 0.22);
+  filter: blur(10px);
+}
+
+.hero__eyebrow {
+  margin: 0;
+  color: rgba(248, 250, 252, 0.8);
+  font: 700 0.82rem/1.2 system-ui, sans-serif;
+  letter-spacing: 0.18em;
