+  color: rgba(248, 250, 252, 0.72);
+}
+
+.meta-chip__value {
+  font: 700 1.3rem/1.2 system-ui, sans-serif;
+}
+
+.section-links {
+  display: flex;
+  flex-wrap: wrap;
+  gap: 10px;
+  margin: 18px 0 0;
+}
+
+.section-links a {
+  display: inline-flex;
