index 0000000000000000000000000000000000000000..92edb1628328d43f83891bb1fb882f0a41ff43b3
--- /dev/null
+++ b/public/styles.css
@@ -0,0 +1,603 @@
+:root {
+  color-scheme: light;
+  --bg: #f3efe6;
+  --bg-accent: #efe4d1;
+  --panel: #fffdf8;
+  --panel-strong: #1f2937;
+  --panel-muted: #f7f3ea;
+  --text: #122033;
+  --text-soft: #516074;
+  --text-inverse: #f8fafc;
+  --accent: #0f766e;
+  --accent-soft: #d9f0ed;
+  --accent-strong: #115e59;
+  --warning: #b45309;
+  --warning-soft: #fef3c7;
+  --critical: #b42318;
+  --critical-soft: #fee4e2;
+  --border: rgba(18, 32, 51, 0.12);
+  --shadow: 0 24px 60px rgba(26, 35, 59, 0.16);
+  --radius-xl: 28px;
+  --radius-lg: 20px;
+  --radius-md: 16px;
+  --radius-sm: 12px;
+  --max-width: 1180px;
+}
+
+* {
+  box-sizing: border-box;
+}
+
+html {
+  min-height: 100%;
+  scroll-behavior: smooth;
+}
+
+body {
+  margin: 0;
+  min-height: 100vh;
+  color: var(--text);
+  font-family: "Iowan Old Style", "Palatino Linotype", "Book Antiqua", Georgia, serif;
+  background:
+    radial-gradient(circle at top left, rgba(15, 118, 110, 0.18), transparent 34%),
+    radial-gradient(circle at top right, rgba(180, 83, 9, 0.16), transparent 28%),
+    linear-gradient(180deg, var(--bg) 0%, #faf7f0 48%, #f4efe5 100%);
+}
+
+a {
+  color: inherit;
+}
+
+button,
+a {
+  -webkit-tap-highlight-color: transparent;
+}
+
+#app {
+  width: 100%;
+}
+
+.dashboard {
+  width: min(100%, var(--max-width));
+  margin: 0 auto;
+  padding: 24px;
+}
+
+.skip-link {
+  position: absolute;
+  left: -9999px;
+  top: 16px;
+  z-index: 20;
+  padding: 12px 16px;
+  border-radius: 999px;
+  background: var(--text);
+  color: var(--text-inverse);
+  text-decoration: none;
+}
+
+.skip-link:focus-visible {
+  left: 24px;
+}
+
+.hero {
+  position: relative;
+  overflow: hidden;
+  display: grid;
+  gap: 22px;
+  padding: 32px;
+  border: 1px solid rgba(255, 255, 255, 0.18);
+  border-radius: var(--radius-xl);
+  color: var(--text-inverse);
+  background:
+    linear-gradient(135deg, rgba(10, 18, 33, 0.96), rgba(18, 54, 73, 0.92)),
+    radial-gradient(circle at top right, rgba(45, 212, 191, 0.22), transparent 28%);
+  box-shadow: var(--shadow);
+}
+
+.hero::before,
+.hero::after {
+  content: "";
+  position: absolute;
+  border-radius: 999px;
+  pointer-events: none;
+}
+
+.hero::before {
+  top: -120px;
+  right: -60px;
+  width: 240px;
+  height: 240px;
+  background: rgba(15, 118, 110, 0.22);
+  filter: blur(8px);
+}
+
+.hero::after {
+  bottom: -80px;
+  left: -40px;
+  width: 180px;
+  height: 180px;
+  background: rgba(180, 83, 9, 0.22);
+  filter: blur(10px);
+}
+
+.hero__eyebrow {
+  margin: 0;
+  color: rgba(248, 250, 252, 0.8);
+  font: 700 0.82rem/1.2 system-ui, sans-serif;
+  letter-spacing: 0.18em;
+  text-transform: uppercase;
+}
+
+.hero__title {
+  margin: 0;
+  max-width: 12ch;
+  font-size: clamp(2.8rem, 7vw, 5.4rem);
+  line-height: 0.94;
+  letter-spacing: -0.05em;
+}
+
+.hero__dates {
+  display: flex;
+  flex-wrap: wrap;
+  gap: 10px 14px;
+  align-items: center;
+  margin: 0;
+  font: 500 1.05rem/1.4 system-ui, sans-serif;
+  color: rgba(248, 250, 252, 0.9);
+}
+
+.hero__dates time {
+  font-weight: 700;
+}
+
+.hero__meta {
+  display: grid;
+  grid-template-columns: repeat(4, minmax(0, 1fr));
+  gap: 14px;
+}
+
+.meta-chip {
+  display: grid;
+  gap: 4px;
+  padding: 14px 16px;
+  border-radius: 18px;
+  background: rgba(255, 255, 255, 0.08);
+  border: 1px solid rgba(255, 255, 255, 0.12);
+}
+
+.meta-chip__label {
+  font: 600 0.78rem/1.2 system-ui, sans-serif;
+  text-transform: uppercase;
+  letter-spacing: 0.14em;
+  color: rgba(248, 250, 252, 0.72);
+}
+
+.meta-chip__value {
+  font: 700 1.3rem/1.2 system-ui, sans-serif;
+}
+
+.section-links {
+  display: flex;
+  flex-wrap: wrap;
+  gap: 10px;
+  margin: 18px 0 0;
+}
+
+.section-links a {
+  display: inline-flex;
+  align-items: center;
+  gap: 8px;
+  padding: 11px 16px;
+  border-radius: 999px;
+  border: 1px solid var(--border);
+  background: rgba(255, 253, 248, 0.9);
+  text-decoration: none;
+  font: 600 0.96rem/1 system-ui, sans-serif;
+  transition:
+    transform 180ms ease,
+    box-shadow 180ms ease,
+    border-color 180ms ease;
+}
+
+.section-links a:hover {
+  transform: translateY(-1px);
+  box-shadow: 0 12px 24px rgba(18, 32, 51, 0.08);
+}
+
+.section-links a:focus-visible,
+.card__link:focus-visible,
+.brand-pill:focus-visible {
+  outline: 3px solid rgba(15, 118, 110, 0.32);
+  outline-offset: 3px;
+}
+
+.dashboard-grid {
+  display: grid;
+  grid-template-columns: minmax(0, 1.5fr) minmax(290px, 0.9fr);
+  gap: 18px;
+  margin-top: 20px;
+}
+
+.panel {
+  display: grid;
+  gap: 18px;
+  padding: 22px;
+  border-radius: var(--radius-lg);
+  background: rgba(255, 253, 248, 0.9);
+  border: 1px solid var(--border);
+  box-shadow: 0 18px 40px rgba(18, 32, 51, 0.08);
+}
+
+.panel--dark {
+  color: var(--text-inverse);
+  background: linear-gradient(180deg, #1f2937, #111827);
+  border-color: rgba(255, 255, 255, 0.08);
+}
+
+.panel__header {
+  display: flex;
+  justify-content: space-between;
+  align-items: flex-start;
+  gap: 12px;
+}
+
+.panel__eyebrow {
+  margin: 0 0 6px;
+  color: var(--accent);
+  font: 700 0.76rem/1.2 system-ui, sans-serif;
+  letter-spacing: 0.18em;
+  text-transform: uppercase;
+}
+
+.panel--dark .panel__eyebrow {
+  color: #7dd3fc;
+}
+
+.panel__title {
+  margin: 0;
+  font-size: clamp(1.45rem, 2.2vw, 2rem);
+  line-height: 1.05;
+  letter-spacing: -0.03em;
+}
+
+.panel__description {
+  margin: 8px 0 0;
+  color: var(--text-soft);
+  font: 500 0.98rem/1.55 system-ui, sans-serif;
+}
+
+.panel--dark .panel__description {
+  color: rgba(248, 250, 252, 0.75);
+}
+
+.panel__badge {
+  flex-shrink: 0;
+  padding: 9px 12px;
+  border-radius: 999px;
+  background: var(--accent-soft);
+  color: var(--accent-strong);
+  font: 700 0.84rem/1 system-ui, sans-serif;
+  white-space: nowrap;
+}
+
+.panel--dark .panel__badge {
+  background: rgba(125, 211, 252, 0.12);
+  color: #bae6fd;
+}
+
+.stack {
+  display: grid;
+  gap: 18px;
+}
+
+.events {
+  display: grid;
+  gap: 12px;
+  margin: 0;
+  padding: 0;
+  list-style: none;
+}
+
+.event {
+  display: grid;
+  grid-template-columns: auto minmax(0, 1fr);
+  gap: 14px;
+  padding: 14px;
+  border-radius: 18px;
+  background: var(--panel-muted);
+}
+
+.event__time {
+  display: grid;
+  gap: 4px;
+  min-width: 78px;
+  color: var(--accent-strong);
+  font: 700 0.9rem/1.15 system-ui, sans-serif;
+}
+
+.event__time small {
+  color: var(--text-soft);
+  font-weight: 600;
+}
+
+.event__title {
+  margin: 0;
+  font: 700 1.02rem/1.35 system-ui, sans-serif;
+}
+
+.event__meta {
+  margin: 4px 0 0;
+  color: var(--text-soft);
+  font: 500 0.92rem/1.45 system-ui, sans-serif;
+}
+
+.section {
+  display: grid;
+  gap: 14px;
+}
+
+.section__grid {
+  display: grid;
+  gap: 12px;
+}
+
+.budget {
+  display: grid;
+  gap: 16px;
+}
+
+.budget__summary {
+  display: grid;
+  grid-template-columns: repeat(3, minmax(0, 1fr));
+  gap: 12px;
+}
+
+.stat {
+  padding: 14px;
+  border-radius: 18px;
+  background: var(--panel-muted);
+}
+
+.stat__label {
+  display: block;
+  margin-bottom: 8px;
+  color: var(--text-soft);
+  font: 600 0.78rem/1.2 system-ui, sans-serif;
+  letter-spacing: 0.12em;
+  text-transform: uppercase;
+}
+
+.stat__value {
+  display: block;
+  font: 700 1.35rem/1.1 system-ui, sans-serif;
+}
+
+.budget__bar {
+  display: grid;
+  gap: 8px;
+}
+
+.progress {
+  overflow: hidden;
+  height: 14px;
+  border-radius: 999px;
+  background: rgba(18, 32, 51, 0.08);
+}
+
+.progress__fill {
+  display: block;
+  height: 100%;
+  width: var(--value, 0%);
+  border-radius: inherit;
+  background: linear-gradient(90deg, var(--accent), #34d399);
+}
+
+.budget__details,
+.memory-list,
+.luggage-list {
+  display: grid;
+  gap: 10px;
+  margin: 0;
+  padding: 0;
+  list-style: none;
+}
+
+.detail-row {
+  display: flex;
+  justify-content: space-between;
+  gap: 16px;
+  padding: 12px 14px;
+  border-radius: 16px;
+  background: var(--panel-muted);
+  font: 600 0.95rem/1.4 system-ui, sans-serif;
+}
+
+.detail-row__label {
+  color: var(--text-soft);
+}
+
+.detail-row__value {
+  text-align: right;
+}
+
+.status-pill {
+  display: inline-flex;
+  align-items: center;
+  gap: 8px;
+  padding: 10px 14px;
+  border-radius: 999px;
+  font: 700 0.88rem/1 system-ui, sans-serif;
+}
+
+.status-pill--positive {
+  background: var(--accent-soft);
+  color: var(--accent-strong);
+}
+
+.status-pill--warning {
+  background: var(--warning-soft);
+  color: var(--warning);
+}
+
+.status-pill--critical {
+  background: var(--critical-soft);
+  color: var(--critical);
+}
+
+.luggage {
+  display: grid;
+  gap: 16px;
+}
+
+.luggage__layout {
+  display: grid;
+  gap: 14px;
+}
+
+.luggage__headline {
+  display: flex;
+  justify-content: space-between;
+  gap: 12px;
+  align-items: center;
+  font: 700 1.8rem/1.05 system-ui, sans-serif;
+}
+
+.luggage__headline small {
+  color: var(--text-soft);
+  font: 600 0.9rem/1.3 system-ui, sans-serif;
+}
+
+.luggage__items li {
+  padding: 11px 14px;
+  border-radius: 14px;
+  background: var(--panel-muted);
+  font: 600 0.94rem/1.4 system-ui, sans-serif;
+}
+
+.empty-state {
+  padding: 16px;
+  border-radius: 18px;
+  border: 1px dashed rgba(18, 32, 51, 0.18);
+  color: var(--text-soft);
+  background: rgba(247, 243, 234, 0.6);
+  font: 500 0.95rem/1.5 system-ui, sans-serif;
+}
+
+.memories {
+  grid-column: 1 / -1;
+}
+
+.memory-list {
+  grid-template-columns: repeat(2, minmax(0, 1fr));
+}
+
+.memory-card {
+  display: grid;
+  gap: 6px;
+  padding: 16px;
+  border-radius: 18px;
+  background: var(--panel-muted);
+  border: 1px solid rgba(18, 32, 51, 0.06);
+}
+
+.memory-card__type {
+  color: var(--accent-strong);
+  font: 700 0.76rem/1.2 system-ui, sans-serif;
+  letter-spacing: 0.16em;
+  text-transform: uppercase;
+}
+
+.memory-card__title {
+  margin: 0;
+  font: 700 1.02rem/1.35 system-ui, sans-serif;
+}
+
+.memory-card__meta {
+  color: var(--text-soft);
+  font: 500 0.92rem/1.5 system-ui, sans-serif;
+}
+
+.trip-summary {
+  display: grid;
+  gap: 10px;
+}
+
+.trip-summary__dates {
+  display: flex;
+  flex-wrap: wrap;
+  gap: 10px;
+  align-items: center;
+  color: var(--text-soft);
+  font: 600 0.96rem/1.4 system-ui, sans-serif;
+}
+
+.brand-pill {
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  padding: 10px 14px;
+  border-radius: 999px;
+  border: 1px solid var(--border);
+  background: rgba(255, 253, 248, 0.9);
+  font: 600 0.88rem/1 system-ui, sans-serif;
+  text-decoration: none;
+}
+
+.visually-hidden {
+  position: absolute;
+  width: 1px;
+  height: 1px;
+  padding: 0;
+  margin: -1px;
+  overflow: hidden;
+  clip: rect(0, 0, 0, 0);
+  white-space: nowrap;
+  border: 0;
+}
+
+@media (max-width: 980px) {
+  .hero__meta,
+  .dashboard-grid,
+  .budget__summary,
+  .memory-list {
+    grid-template-columns: 1fr 1fr;
+  }
+
+  .dashboard-grid {
+    grid-template-columns: 1fr;
+  }
+
+  .memories {
+    grid-column: auto;
+  }
+}
+
+@media (max-width: 700px) {
+  .dashboard {
+    padding: 16px;
+  }
+
+  .hero,
+  .panel {
+    padding: 18px;
+  }
+
+  .hero__meta,
+  .budget__summary,
+  .memory-list {
+    grid-template-columns: 1fr;
+  }
+
+  .event {
+    grid-template-columns: 1fr;
+  }
+
+  .panel__header {
+    flex-direction: column;
+  }
+
+  .luggage__headline {
+    flex-direction: column;
+    align-items: flex-start;
+  }
+}
