diff --git a/src/dashboard/dashboard.test.mjs b/src/dashboard/dashboard.test.mjs
new file mode 100644
index 0000000000000000000000000000000000000000..7e9d625ab2ebcadcad01d419eae0a1b7d1520168
--- /dev/null
+++ b/src/dashboard/dashboard.test.mjs
@@ -0,0 +1,159 @@
+import assert from "node:assert/strict";
+import test from "node:test";
+
+import { addActividad } from "../itinerary/agenda/agenda.mjs";
+import { addParada } from "../itinerary/paradas/paradas.mjs";
+import { guardarNota } from "../recuerdos/notas/notas.mjs";
+import { createFavoritosStore } from "../recuerdos/favoritos/favoritos.mjs";
+import { guardarPresupuesto } from "../organizacion/presupuesto/presupuesto.mjs";
+import { crearChecklistEquipaje } from "../organizacion/equipaje/equipaje.mjs";
+import { buildDashboardMarkup, collectDashboardData, mountDashboard } from "./dashboard.mjs";
+
+class LocalStorageMock {
+  #map = new Map();
+
+  clear() {
+    this.#map.clear();
+  }
+
+  getItem(key) {
+    return this.#map.has(key) ? this.#map.get(key) : null;
+  }
+
+  setItem(key, value) {
+    this.#map.set(key, String(value));
+  }
+
+  removeItem(key) {
+    this.#map.delete(key);
+  }
+}
+
+test.beforeEach(() => {
+  globalThis.localStorage = new LocalStorageMock();
+});
+
+test.afterEach(() => {
+  delete globalThis.localStorage;
+});
+
+test("collectDashboardData compone itinerario, organización y recuerdos desde los stores compartidos", () => {
+  const firstStop = addParada({
+    id: "madrid",
+    nombre: "Madrid",
+    fechaInicio: "2026-09-01",
+    fechaFin: "2026-09-03",
+    descripcion: "Llegada y paseo"
+  });
+  const secondStop = addParada({
+    id: "sevilla",
+    nombre: "Sevilla",
+    fechaInicio: "2026-09-04",
+    fechaFin: "2026-09-07",
+    descripcion: "Centro histórico"
+  });
+
+  addActividad({
+    id: "madrid-desayuno",
+    fecha: "2026-09-02",
+    paradaId: firstStop.id,
+    horario: "08:30",
+    estado: "pendiente"
+  });
+  addActividad({
+    id: "sevilla-paseo",
+    fecha: "2026-09-05",
+    paradaId: secondStop.id,
+    horario: "11:00",
+    estado: "completada"
+  });
+
+  guardarPresupuesto({
+    total: 1000,
+    gastos: [
+      { categoria: "Hospedaje", gasto: 650 },
+      { categoria: "Comida", gasto: 150 }
+    ]
+  });
+
+  const checklist = crearChecklistEquipaje();
+  const pasaportes = checklist.agregarEquipaje("Pasaportes");
+  checklist.agregarEquipaje("Cargadores");
+  checklist.completarEquipaje(pasaportes.id);
+
+  const favoritos = createFavoritosStore();
+  favoritos.marcarFavorito({ id: "museo", tipo: "lugar", nombre: "Museo de los Niños" });
+
+  guardarNota({
+    id: "nota-1",
+    texto: "Llevar abrigo liviano",
+    paradaId: "madrid"
+  });
+
+  const data = collectDashboardData();
+
+  assert.deepEqual(data.trip, {
+    name: "Viaje en Familia",
+    start: "2026-09-01",
+    end: "2026-09-07",
+    stopCount: 2,
+    activityCount: 2,
+    memoryCount: 2
+  });
+  assert.equal(data.upcomingEvents.length, 2);
+  assert.equal(data.upcomingEvents[0].paradaNombre, "Madrid");
+  assert.equal(data.budget.total, 1000);
+  assert.equal(data.budget.gastado, 800);
+  assert.equal(data.budget.disponible, 200);
+  assert.equal(data.luggage.total, 2);
+  assert.equal(data.luggage.completados, 1);
+  assert.equal(data.memories.length, 2);
+});
+
+test("buildDashboardMarkup and mountDashboard render the four integrated sections", () => {
+  addParada({
+    id: "barcelona",
+    nombre: "Barcelona",
+    fechaInicio: "2026-10-01",
+    fechaFin: "2026-10-04",
+    descripcion: "Arte y mar"
+  });
+
+  const markup = buildDashboardMarkup({
+    trip: {
+      name: "Viaje en Familia",
+      start: "2026-10-01",
+      end: "2026-10-04",
+      stopCount: 1,
+      activityCount: 0,
+      memoryCount: 0
+    },
+    upcomingEvents: [],
+    budget: {
+      total: 0,
+      gastado: 0,
+      disponible: 0,
+      porcentajeGastado: 0,
+      estadoVisual: { clave: "sin_presupuesto", etiqueta: "Sin presupuesto", tono: "neutral" }
+    },
+    luggage: {
+      total: 0,
+      completados: 0,
+      porcentaje: 0,
+      pendingItems: []
+    },
+    memories: []
+  });
+
+  assert.match(markup, /Itinerario, organización y recuerdos/);
+  assert.match(markup, /Próximos eventos/);
+  assert.match(markup, /Resumen de presupuesto/);
+  assert.match(markup, /Progreso del checklist/);
+  assert.match(markup, /Momentos destacados/);
+
+  const root = { innerHTML: "" };
+  const rendered = mountDashboard(root);
+
+  assert.equal(root.innerHTML, rendered);
+  assert.match(root.innerHTML, /Viaje en Familia/);
+});

