+import { listParadas } from "../src/itinerary/paradas/paradas.mjs";
+import { listActividades } from "../src/itinerary/agenda/agenda.mjs";
+import { obtenerPresupuestoGuardado } from "../src/organizacion/presupuesto/presupuesto.mjs";
+import { crearChecklistEquipaje } from "../src/organizacion/equipaje/equipaje.mjs";
+import { createFavoritosStore } from "../src/recuerdos/favoritos/favoritos.mjs";
+import { listarNotas } from "../src/recuerdos/notas/notas.mjs";
+
+const DATE_FORMAT = new Intl.DateTimeFormat("es-AR", {
+  day: "2-digit",
+  month: "short",
+  year: "numeric"
+});
+
+const NUMBER_FORMAT = new Intl.NumberFormat("es-AR", {
+  maximumFractionDigits: 0
+});
+
+const MONTHS = ["ene.", "feb.", "mar.", "abr.", "may.", "jun.", "jul.", "ago.", "sept.", "oct.", "nov.", "dic."];
+
+function escapeHtml(value) {
+  return String(value)
+    .replaceAll("&", "&amp;")
+    .replaceAll("<", "&lt;")
+    .replaceAll(">", "&gt;")
+    .replaceAll('"', "&quot;")
+    .replaceAll("'", "&#39;");
+}
+
+function toIsoDate(value) {
+  if (typeof value !== "string" || value.length < 10) {
+    return null;
+  }
+
+  const candidate = value.slice(0, 10);
+  return /^\d{4}-\d{2}-\d{2}$/.test(candidate) ? candidate : null;
+}
+
+function parseDateTime(fecha, horario = "") {
+  const isoDate = toIsoDate(fecha);
+  if (!isoDate) {
+    return Number.POSITIVE_INFINITY;
+  }
+
+  const normalizedTime = typeof horario === "string" && /^\d{2}:\d{2}$/.test(horario) ? `${horario}:00` : "00:00:00";
+  const timestamp = Date.parse(`${isoDate}T${normalizedTime}`);
+  return Number.isFinite(timestamp) ? timestamp : Number.POSITIVE_INFINITY;
+}
+
+function formatDate(value) {
+  const isoDate = toIsoDate(value);
+  if (!isoDate) {
+    return value ? String(value) : "Fechas por definir";
+  }
+
+  const [year, month, day] = isoDate.split("-").map(Number);
+  return `${String(day).padStart(2, "0")} ${MONTHS[month - 1]} ${year}`;
+}
+
+function formatDateTime(fecha, horario) {
+  const date = formatDate(fecha);
+  return horario ? `${date}, ${horario}` : date;
+}
+
+function formatNumber(value) {
+  const numeric = Number(value);
+  return NUMBER_FORMAT.format(Number.isFinite(numeric) ? numeric : 0);
+}
+
+function getTripWindow(paradas) {
+  const dates = paradas
+    .map((parada) => ({
+      inicio: toIsoDate(parada.fechaInicio),
+      fin: toIsoDate(parada.fechaFin)
+    }))
+    .filter((parada) => parada.inicio || parada.fin);
+
+  if (dates.length === 0) {
+    return {
+      start: null,
+      end: null
+    };
+  }
+
+  const starts = dates.map((parada) => parada.inicio ?? parada.fin).filter(Boolean).sort();
+  const ends = dates.map((parada) => parada.fin ?? parada.inicio).filter(Boolean).sort();
+
+  return {
+    start: starts[0] ?? null,
+    end: ends.at(-1) ?? null
+  };
+}
+
+function getTripName() {
+  return "Viaje en Familia";
+}
+
+function getParadaNameById(paradas, paradaId) {
+  return paradas.find((parada) => parada.id === paradaId)?.nombre ?? "Parada sin nombre";
+}
+
+function getUpcomingEvents(actividades, paradas, limit = 4) {
+  const sorted = actividades
+    .map((actividad) => ({
+      ...actividad,
+      timestamp: parseDateTime(actividad.fecha, actividad.horario),
+      paradaNombre: getParadaNameById(paradas, actividad.paradaId)
+    }))
+    .sort((a, b) => a.timestamp - b.timestamp);
+
+  const now = Date.now();
+  const future = sorted.filter((actividad) => actividad.timestamp >= now);
+  const source = future.length > 0 ? future : sorted;
+
+  return source.slice(0, limit).map((actividad) => ({
+    ...actividad,
+    fechaTexto: formatDateTime(actividad.fecha, actividad.horario)
+  }));
+}
+
+function getMemoryLabel(memory) {
+  return (
+    memory.nombre ??
+    memory.name ??
+    memory.title ??
+    memory.titulo ??
+    memory.texto ??
+    memory.descripcion ??
+    memory.id ??
+    "Recuerdo"
+  );
+}
+
+function getMemoryType(memory) {
+  return memory.tipo ?? memory.type ?? memory.kind ?? memory.categoria ?? "recuerdo";
+}
+
+function getMemoryMeta(memory) {
+  const parts = [];
+  if (memory.paradaId) {
+    parts.push(`Parada ${memory.paradaId}`);
+  }
+  if (memory.diaId) {
+    parts.push(`Día ${memory.diaId}`);
+  }
+  return parts.join(" · ");
+}
+
+function buildMemoryHighlights(favoritos, notas, limit = 4) {
+  const favoriteCards = favoritos.map((favorito) => ({
+    type: getMemoryType(favorito),
+    title: getMemoryLabel(favorito),
+    meta: favorito.descripcion ?? favorito.detalle ?? favorito.ubicacion ?? ""
+  }));
+
+  const noteCards = notas.map((nota) => ({
+    type: "nota",
+    title: nota.texto,
+    meta: getMemoryMeta(nota)
+  }));
+
+  return [...favoriteCards, ...noteCards].slice(0, limit);
+}
+
+function buildBudgetSummary() {
+  return obtenerPresupuestoGuardado();
+}
+
+function buildLuggageSummary() {
+  const checklist = crearChecklistEquipaje();
+  const state = checklist.get();
+  const progress = checklist.obtenerProgresoEquipaje();
+  const pendingItems = (state.items ?? []).filter((item) => !item.completado).slice(0, 3);
+
+  return {
+    ...progress,
+    pendingItems
+  };
+}
+
+export function collectDashboardData() {
+  const paradas = listParadas();
+  const actividades = listActividades();
+  const favoritosStore = createFavoritosStore();
+  const favoritos = favoritosStore.get();
+  const notas = listarNotas();
+  const budget = buildBudgetSummary();
+  const luggage = buildLuggageSummary();
+  const tripWindow = getTripWindow(paradas);
+  const upcomingEvents = getUpcomingEvents(actividades, paradas);
+  const memories = buildMemoryHighlights(favoritos, notas);
+
+  return {
+    trip: {
+      name: getTripName(),
+      start: tripWindow.start,
+      end: tripWindow.end,
+      stopCount: paradas.length,
+      activityCount: actividades.length,
+      memoryCount: favoritos.length + notas.length
+    },
+    upcomingEvents,
+    budget,
+    luggage,
+    memories
+  };
+}
+
+export const buildDashboardData = collectDashboardData;
+
+export function buildDashboardMarkup(data = collectDashboardData()) {
+  const tripDates =
+    data.trip.start && data.trip.end
+      ? `<p class="hero__dates">Del <time datetime="${escapeHtml(data.trip.start)}">${escapeHtml(formatDate(data.trip.start))}</time> al <time datetime="${escapeHtml(data.trip.end)}">${escapeHtml(formatDate(data.trip.end))}</time></p>`
+      : `<p class="hero__dates">Fechas del viaje por definir</p>`;
+
+  const budgetPercent = Math.max(0, Math.min(100, Math.round((data.budget.porcentajeGastado ?? 0) * 100)));
+  const luggagePercent = Math.max(0, Math.min(100, data.luggage.porcentaje ?? 0));
+  const statusClass =
+    data.budget.estadoVisual.tono === "critico"
+      ? "status-pill--critical"
+      : data.budget.estadoVisual.tono === "advertencia"
+        ? "status-pill--warning"
+        : "status-pill--positive";
+
+  const eventMarkup =
+    data.upcomingEvents.length > 0
+      ? data.upcomingEvents
+          .map(
+            (actividad) => `
+              <li class="event">
+                <div class="event__time">
+                  <time datetime="${escapeHtml(actividad.fecha)}">${escapeHtml(formatDate(actividad.fecha))}</time>
+                  <small>${escapeHtml(actividad.horario || "Sin horario")}</small>
+                </div>
+                <div>
+                  <p class="event__title">${escapeHtml(actividad.paradaNombre)}</p>
+                  <p class="event__meta">${escapeHtml(actividad.estado)} · ${escapeHtml(actividad.fechaTexto)}</p>
+                </div>
+              </li>`
+          )
+          .join("")
+      : `<li class="empty-state">No hay eventos próximos cargados todavía.</li>`;
+
+  const budgetRows = [
+    { label: "Total", value: formatNumber(data.budget.total) },
+    { label: "Gastado", value: formatNumber(data.budget.gastado) },
+    { label: "Disponible", value: formatNumber(data.budget.disponible) }
+  ]
+    .map(
+      (row) => `
+        <div class="detail-row">
+          <span class="detail-row__label">${escapeHtml(row.label)}</span>
+          <span class="detail-row__value">${escapeHtml(row.value)}</span>
+        </div>`
+    )
+    .join("");
+
+  const luggageItems =
+    data.luggage.pendingItems.length > 0
+      ? data.luggage.pendingItems
+          .map((item) => `<li>${escapeHtml(item.nombre)}</li>`)
+          .join("")
+      : `<li class="empty-state">El equipaje está al día.</li>`;
+
+  const memoryMarkup =
+    data.memories.length > 0
+      ? data.memories
+          .map(
+            (memory) => `
+              <li class="memory-card">
+                <span class="memory-card__type">${escapeHtml(memory.type)}</span>
+                <h3 class="memory-card__title">${escapeHtml(memory.title)}</h3>
+                <p class="memory-card__meta">${escapeHtml(memory.meta || "Destacado del viaje")}</p>
+              </li>`
+          )
+          .join("")
+      : `<li class="empty-state">Aún no hay recuerdos destacados.</li>`;
+
+  return `
