+        ${tripDates}
+        <div class="hero__meta" aria-label="Resumen del viaje">
+          <div class="meta-chip">
+            <span class="meta-chip__label">Paradas</span>
+            <span class="meta-chip__value">${escapeHtml(formatNumber(data.trip.stopCount))}</span>
+          </div>
+          <div class="meta-chip">
