+              <p class="panel__description">El recorrido se ordena por fecha y horario para mantener visible lo inmediato.</p>
+            </div>
+            <span class="panel__badge">${escapeHtml(formatNumber(data.upcomingEvents.length))} visibles</span>
+          </div>
+          <ol class="events">
+            ${eventMarkup}
+          </ol>
+        </article>
+
+        <div class="stack">
+          <article class="panel section" id="presupuesto">
+            <div class="panel__header">
+              <div>
+                <p class="panel__eyebrow">Organización</p>
+                <h2 class="panel__title">Resumen de presupuesto</h2>
+                <p class="panel__description">Control visual claro para identificar gasto, saldo disponible y estado general.</p>
+              </div>
+              <span class="status-pill ${statusClass}">${escapeHtml(data.budget.estadoVisual.etiqueta)}</span>
+            </div>
+            <div class="budget">
+              <div class="budget__summary">
+                ${budgetRows}
+              </div>
+              <div class="budget__bar">
+                <div class="progress" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${escapeHtml(String(budgetPercent))}">
+                  <span class="progress__fill" style="--value: ${budgetPercent}%;"></span>
+                </div>
+                <p class="panel__description">Gastado: ${escapeHtml(formatNumber(Math.round((data.budget.porcentajeGastado ?? 0) * 100)))}% del total.</p>
+              </div>
+            </div>
+          </article>
+
+          <article class="panel section" id="equipaje">
+            <div class="panel__header">
+              <div>
+                <p class="panel__eyebrow">Equipaje</p>
+                <h2 class="panel__title">Progreso del checklist</h2>
+                <p class="panel__description">La carga pendiente queda a la vista para completar antes de salir.</p>
+              </div>
+              <span class="panel__badge">${escapeHtml(formatNumber(data.luggage.porcentaje))}% listo</span>
+            </div>
+            <div class="luggage">
+              <div class="luggage__layout">
+                <div class="luggage__headline">
+                  <span>${escapeHtml(formatNumber(data.luggage.completados))} de ${escapeHtml(formatNumber(data.luggage.total))}</span>
+                  <small>Completado</small>
+                </div>
+                <div class="progress" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${escapeHtml(String(luggagePercent))}">
+                  <span class="progress__fill" style="--value: ${luggagePercent}%;"></span>
+                </div>
+              </div>
+              <ul class="luggage-list">
+                ${luggageItems}
+              </ul>
+            </div>
+          </article>
+        </div>
+
+        <article class="panel section memories" id="recuerdos">
+          <div class="panel__header">
+            <div>
+              <p class="panel__eyebrow">Recuerdos</p>
+              <h2 class="panel__title">Momentos destacados</h2>
+              <p class="panel__description">Favoritos y notas recientes se agrupan en una lectura rápida y contrastada.</p>
+            </div>
+            <a class="brand-pill" href="#trip-title">Volver arriba</a>
+          </div>
+          <ul class="memory-list">
+            ${memoryMarkup}
+          </ul>
+        </article>
+      </section>
+    </main>
+  `;
+}
+
+export function mountDashboard(root) {
+  const target =
+    typeof root === "string" && typeof document !== "undefined"
+      ? document.querySelector(root)
+      : root;
+
+  if (!target) {
+    return null;
+  }
+
+  const markup = buildDashboardMarkup();
+  target.innerHTML = markup;
+  return markup;
+}
+
+export default {
+  collectDashboardData,
+  buildDashboardData,
+  buildDashboardMarkup,
+  mountDashboard
+};
