+import { listActividades } from "../itinerary/agenda/agenda.mjs";
+import { listParadas } from "../itinerary/paradas/paradas.mjs";
+import {
+  crearChecklistEquipaje
+} from "../organizacion/equipaje/equipaje.mjs";
+import { obtenerPresupuestoGuardado } from "../organizacion/presupuesto/presupuesto.mjs";
+import { createFavoritosStore } from "../recuerdos/favoritos/favoritos.mjs";
+import { listarNotas } from "../recuerdos/notas/notas.mjs";
+
+const MONTHS = [
+  "ene",
+  "feb",
+  "mar",
+  "abr",
+  "may",
+  "jun",
+  "jul",
+  "ago",
+  "sep",
+  "oct",
+  "nov",
+  "dic"
+];
+
+function isRecord(value) {
+  return value !== null && typeof value === "object" && !Array.isArray(value);
+}
+
+function toItems(value) {
+  return Array.isArray(value) ? value.filter(isRecord) : [];
+}
+
+function escapeHtml(value) {
+  return String(value ?? "")
+    .replaceAll("&", "&amp;")
+    .replaceAll("<", "&lt;")
+    .replaceAll(">", "&gt;")
+    .replaceAll('"', "&quot;")
+    .replaceAll("'", "&#39;");
+}
+
+function normalizeIsoDate(value) {
+  if (typeof value !== "string") {
+    return "";
+  }
+
+  const trimmed = value.trim();
+  return /^\d{4}-\d{2}-\d{2}$/.test(trimmed) ? trimmed : "";
+}
+
+function compareIsoDate(left, right) {
+  return normalizeIsoDate(left).localeCompare(normalizeIsoDate(right));
+}
+
+function formatDate(value) {
+  const iso = normalizeIsoDate(value);
+  if (!iso) {
+    return "";
+  }
+
+  const [year, month, day] = iso.split("-");
+  return `${Number(day)} ${MONTHS[Number(month) - 1] ?? month} ${year}`;
+}
+
+function formatDateRange(start, end) {
+  const from = normalizeIsoDate(start);
+  const to = normalizeIsoDate(end);
+
+  if (!from && !to) {
+    return "Fechas por definir";
+  }
+
+  if (from && from === to) {
+    return formatDate(from);
+  }
+
+  if (!from) {
+    return `Hasta ${formatDate(to)}`;
+  }
+
+  if (!to) {
+    return `Desde ${formatDate(from)}`;
+  }
+
+  return `${formatDate(from)} - ${formatDate(to)}`;
+}
+
+function formatCurrency(value) {
+  const amount = Number(value);
+  if (!Number.isFinite(amount)) {
+    return "$0";
+  }
+
+  return new Intl.NumberFormat("es-AR", {
+    style: "currency",
+    currency: "ARS",
+    maximumFractionDigits: 0
+  }).format(amount);
+}
+
+function formatPercent(value) {
+  const numeric = Number(value);
+  if (!Number.isFinite(numeric)) {
+    return "0%";
+  }
+
+  return `${Math.round(numeric * 100)}%`;
+}
+
+function createLabel(value, fallback) {
+  const text = typeof value === "string" ? value.trim() : "";
+  return text || fallback;
+}
+
+function buildTripSummary(paradas) {
+  const ordered = [...toItems(paradas)].sort((left, right) => {
+    const byStart = compareIsoDate(left.fechaInicio, right.fechaInicio);
+    if (byStart !== 0) {
+      return byStart;
+    }
+
+    const byEnd = compareIsoDate(left.fechaFin, right.fechaFin);
+    if (byEnd !== 0) {
+      return byEnd;
+    }
+
+    return createLabel(left.nombre, "").localeCompare(createLabel(right.nombre, ""));
+  });
+
+  const first = ordered[0];
+  const last = ordered[ordered.length - 1];
+  const rangeStart = first?.fechaInicio ?? first?.fechaFin ?? "";
+  const rangeEnd = last?.fechaFin ?? last?.fechaInicio ?? "";
+
+  return {
+    name: "Viaje en familia",
+    rangeLabel: formatDateRange(rangeStart, rangeEnd),
+    stopCount: ordered.length,
+    stops: ordered.map((parada, index) => ({
+      index: index + 1,
+      id: parada.id,
+      nombre: createLabel(parada.nombre, "Parada sin nombre"),
+      fechaInicio: normalizeIsoDate(parada.fechaInicio),
+      fechaFin: normalizeIsoDate(parada.fechaFin),
+      descripcion: createLabel(parada.descripcion, "Sin descripción")
+    }))
+  };
+}
+
+function buildUpcomingEvents(actividades, paradas) {
+  const byParadaId = new Map(
+    toItems(paradas).map((parada) => [parada.id, parada])
+  );
+
+  return toItems(actividades)
+    .slice()
+    .sort((left, right) => {
+      const byDate = compareIsoDate(left.fecha, right.fecha);
+      if (byDate !== 0) {
+        return byDate;
+      }
+
+      const byTime = createLabel(left.horario, "").localeCompare(createLabel(right.horario, ""));
+      if (byTime !== 0) {
+        return byTime;
+      }
+
+      return createLabel(byParadaId.get(left.paradaId)?.nombre, "").localeCompare(
+        createLabel(byParadaId.get(right.paradaId)?.nombre, "")
+      );
+    })
+    .slice(0, 4)
+    .map((actividad) => {
+      const parada = byParadaId.get(actividad.paradaId);
+
+      return {
+        id: actividad.id,
+        fecha: normalizeIsoDate(actividad.fecha),
+        horario: createLabel(actividad.horario, "Sin horario"),
+        paradaId: actividad.paradaId,
+        paradaNombre: createLabel(parada?.nombre, "Parada sin nombre"),
+        estado: actividad.estado === "completada" ? "Completada" : "Pendiente"
+      };
+    });
+}
+
+function buildBudgetSummary(presupuesto) {
+  const resumen = isRecord(presupuesto) ? presupuesto : {};
+  const categories = Array.isArray(resumen.gastosPorCategoria)
+    ? resumen.gastosPorCategoria
+    : [];
+
+  return {
+    total: Number(resumen.total ?? 0),
+    gastado: Number(resumen.gastado ?? 0),
+    disponible: Number(resumen.disponible ?? 0),
+    porcentajeGastado: Number(resumen.porcentajeGastado ?? 0),
+    porcentajeDisponible: Number(resumen.porcentajeDisponible ?? 0),
+    estadoVisual: isRecord(resumen.estadoVisual)
+      ? {
+          clave: createLabel(resumen.estadoVisual.clave, "sin_presupuesto"),
+          etiqueta: createLabel(resumen.estadoVisual.etiqueta, "Sin presupuesto"),
+          tono: createLabel(resumen.estadoVisual.tono, "neutral")
+        }
+      : {
+          clave: "sin_presupuesto",
+          etiqueta: "Sin presupuesto",
+          tono: "neutral"
+        },
+    gastosPorCategoria: categories.slice(0, 4).map((item) => ({
+      categoria: createLabel(item?.categoria, "Sin categoría"),
+      gasto: Number(item?.gasto ?? 0)
+    }))
+  };
+}
+
+function buildPackingSummary(equipajeStore) {
+  const state = isRecord(equipajeStore?.get?.()) ? equipajeStore.get() : {};
+  const items = toItems(state.items);
+  const completados = items.filter((item) => Boolean(item.completado)).length;
+  const pendientes = items.length - completados;
+
+  return {
+    total: items.length,
+    completados,
+    pendientes,
+    porcentaje: items.length === 0 ? 0 : Math.round((completados / items.length) * 100),
+    items: items.slice(0, 5).map((item) => ({
+      id: item.id,
+      nombre: createLabel(item.nombre, "Elemento sin nombre"),
+      completado: Boolean(item.completado)
+    }))
+  };
+}
+
+function getFavoriteLabel(favorito) {
+  return createLabel(
+    favorito?.nombre ?? favorito?.name ?? favorito?.titulo ?? favorito?.title ?? favorito?.id,
+    "Favorito sin nombre"
+  );
+}
+
+function buildMemoryHighlights(favoritosStore, notas) {
+  const favorites = toItems(favoritosStore?.listarFavoritos?.()).slice(0, 4);
+  const notes = toItems(notas).slice(0, 4);
+
+  return {
+    favorites: favorites.map((item) => ({
+      id: createLabel(item.id, getFavoriteLabel(item)),
+      tipo: createLabel(item.tipo ?? item.type ?? item.kind, "favorito"),
+      nombre: getFavoriteLabel(item)
+    })),
+    notes: notes.map((item) => ({
+      id: createLabel(item.id, item.texto),
+      texto: createLabel(item.texto, "Nota sin texto"),
+      contexto: createLabel(
+        item.paradaId ? `Parada ${item.paradaId}` : item.diaId ? `Día ${item.diaId}` : "",
+        "Sin contexto"
+      )
+    }))
+  };
+}
+
+export function buildDashboardModel(source = {}) {
+  const paradas = source.paradas ?? listParadas();
+  const actividades = source.actividades ?? listActividades();
+  const presupuesto = source.presupuesto ?? obtenerPresupuestoGuardado();
+  const equipaje = source.equipaje ?? crearChecklistEquipaje();
+  const favoritos = source.favoritos ?? createFavoritosStore();
+  const notas = source.notas ?? listarNotas();
+
+  return {
+    trip: buildTripSummary(paradas),
+    events: buildUpcomingEvents(actividades, paradas),
+    budget: buildBudgetSummary(presupuesto),
+    packing: buildPackingSummary(equipaje),
+    memories: buildMemoryHighlights(favoritos, notas)
+  };
+}
+
+function renderMetric(label, value, detail = "") {
+  return `
+    <div class="metric">
+      <span class="metric__label">${escapeHtml(label)}</span>
+      <strong class="metric__value">${escapeHtml(value)}</strong>
+      ${detail ? `<span class="metric__detail">${escapeHtml(detail)}</span>` : ""}
+    </div>
+  `;
+}
+
+function renderStop(stop) {
+  return `
+    <li class="stack-card">
+      <span class="stack-card__index">0${stop.index}</span>
+      <div>
+        <h3>${escapeHtml(stop.nombre)}</h3>
+        <p>${escapeHtml(formatDateRange(stop.fechaInicio, stop.fechaFin))}</p>
+      </div>
+      <span class="stack-card__meta">${escapeHtml(stop.descripcion)}</span>
+    </li>
+  `;
+}
+
+function renderEvent(event) {
+  return `
+    <li class="event-row">
+      <div class="event-row__time">
+        <strong>${escapeHtml(event.horario)}</strong>
+        <span>${escapeHtml(formatDate(event.fecha))}</span>
+      </div>
+      <div class="event-row__body">
+        <h3>${escapeHtml(event.paradaNombre)}</h3>
+        <p>${escapeHtml(`Actividad ${event.estado.toLowerCase()}`)}</p>
+      </div>
+      <span class="event-row__status">${escapeHtml(event.estado)}</span>
+    </li>
+  `;
+}
+
+function renderBudgetBreakdown(items) {
+  if (items.length === 0) {
+    return `<p class="empty-state">Aún no hay gastos cargados.</p>`;
+  }
+
+  return `
+    <ul class="budget-breakdown">
+      ${items
+        .map(
+          (item) => `
+            <li>
+              <span>${escapeHtml(item.categoria)}</span>
+              <strong>${escapeHtml(formatCurrency(item.gasto))}</strong>
+            </li>
+          `
+        )
+        .join("")}
+    </ul>
+  `;
+}
+
+function renderPackingItems(items) {
+  if (items.length === 0) {
+    return `<p class="empty-state">Todavía no hay equipaje registrado.</p>`;
+  }
+
+  return `
+    <ul class="checklist">
+      ${items
+        .map(
+          (item) => `
+            <li class="${item.completado ? "is-complete" : ""}">
+              <span>${escapeHtml(item.nombre)}</span>
+              <strong>${item.completado ? "Listo" : "Pendiente"}</strong>
+            </li>
+          `
+        )
+        .join("")}
+    </ul>
+  `;
+}
+
+function renderMemories(memories) {
+  const favoriteMarkup = memories.favorites.length
+    ? memories.favorites
+        .map(
+          (item) => `
+            <li>
+              <span>${escapeHtml(item.tipo)}</span>
+              <strong>${escapeHtml(item.nombre)}</strong>
+            </li>
+          `
+        )
+        .join("")
+    : `<li class="empty-state">Todavía no hay favoritos destacados.</li>`;
+
+  const noteMarkup = memories.notes.length
+    ? memories.notes
+        .map(
+          (item) => `
+            <li>
+              <strong>${escapeHtml(item.texto)}</strong>
+              <span>${escapeHtml(item.contexto)}</span>
+            </li>
+          `
+        )
+        .join("")
+    : `<li class="empty-state">Todavía no hay notas guardadas.</li>`;
+
+  return `
+    <div class="memory-columns">
+      <section>
+        <h3>Favoritos</h3>
+        <ul class="memory-list">${favoriteMarkup}</ul>
+      </section>
+      <section>
+        <h3>Notas</h3>
+        <ul class="memory-list">${noteMarkup}</ul>
+      </section>
+    </div>
+  `;
+}
+
+export function renderDashboardHTML(model = buildDashboardModel()) {
+  const progress = Math.max(0, Math.min(100, Number(model.packing.porcentaje ?? 0)));
+  const budgetProgress = Math.max(0, Math.min(100, Math.round((model.budget.porcentajeGastado ?? 0) * 100)));
+  const availability = formatPercent(model.budget.porcentajeDisponible ?? 0);
+
+  return `
+    <main class="dashboard-shell">
+      <section class="hero card">
+        <p class="eyebrow">Dashboard del viaje</p>
+        <div class="hero__head">
+          <div>
+            <h1>${escapeHtml(model.trip.name)}</h1>
+            <p class="hero__dates">${escapeHtml(model.trip.rangeLabel)}</p>
+          </div>
+          <div class="hero__badge">${escapeHtml(`${model.trip.stopCount} paradas`)}</div>
+        </div>
+        <div class="hero__metrics">
+          ${renderMetric("Próximos eventos", String(model.events.length), "en agenda")}
+          ${renderMetric("Presupuesto disponible", availability, formatCurrency(model.budget.disponible))}
+          ${renderMetric("Equipaje listo", formatPercent(progress / 100), `${model.packing.completados}/${model.packing.total}`)}
+          ${renderMetric("Recuerdos", String(model.memories.favorites.length + model.memories.notes.length), "destacados")}
+        </div>
+      </section>
+
+      <section class="dashboard-grid">
+        <article class="card card--itinerary">
+          <div class="section-head">
+            <p class="eyebrow">Itinerario</p>
+            <h2>Paradas del viaje</h2>
+          </div>
+          <ul class="stack-list">
+            ${model.trip.stops.length ? model.trip.stops.map(renderStop).join("") : '<li class="empty-state">Todavía no hay paradas cargadas.</li>'}
+          </ul>
+        </article>
+
+        <article class="card card--events">
+          <div class="section-head">
+            <p class="eyebrow">Próximos eventos</p>
+            <h2>Agenda visible</h2>
+          </div>
+          <ul class="event-list">
+            ${model.events.length ? model.events.map(renderEvent).join("") : '<li class="empty-state">No hay eventos programados.</li>'}
+          </ul>
+        </article>
+
+        <article class="card card--budget">
+          <div class="section-head">
+            <p class="eyebrow">Presupuesto</p>
+            <h2>Resumen financiero</h2>
+          </div>
+          <div class="budget-summary">
+            <div class="budget-summary__bar" aria-hidden="true">
+              <span style="width: ${budgetProgress}%"></span>
+            </div>
+            <dl class="budget-stats">
+              <div>
+                <dt>Total</dt>
+                <dd>${escapeHtml(formatCurrency(model.budget.total))}</dd>
+              </div>
+              <div>
+                <dt>Gastado</dt>
+                <dd>${escapeHtml(formatCurrency(model.budget.gastado))}</dd>
+              </div>
+              <div>
+                <dt>Disponible</dt>
+                <dd>${escapeHtml(formatCurrency(model.budget.disponible))}</dd>
+              </div>
+              <div>
+                <dt>Estado</dt>
+                <dd>${escapeHtml(model.budget.estadoVisual.etiqueta)}</dd>
+              </div>
+            </dl>
+          </div>
+          ${renderBudgetBreakdown(model.budget.gastosPorCategoria)}
+        </article>
+
+        <article class="card card--packing">
+          <div class="section-head">
+            <p class="eyebrow">Equipaje</p>
+            <h2>Progreso de preparación</h2>
+          </div>
+          <div class="packing-summary">
+            <div class="packing-summary__ring" aria-hidden="true">
+              <strong>${escapeHtml(String(model.packing.porcentaje))}%</strong>
+            </div>
+            <div>
+              <p>${escapeHtml(`${model.packing.completados} listos, ${model.packing.pendientes} pendientes`)}</p>
+              <p class="muted">Revisión rápida del checklist compartido.</p>
+            </div>
+          </div>
+          ${renderPackingItems(model.packing.items)}
+        </article>
+
+        <article class="card card--memories">
+          <div class="section-head">
+            <p class="eyebrow">Recuerdos destacados</p>
+            <h2>Lo que vale conservar</h2>
+          </div>
+          ${renderMemories(model.memories)}
+        </article>
+      </section>
+    </main>
+  `;
+}
+
