+import assert from "node:assert/strict";
+import test from "node:test";
+
+import { addActividad } from "../itinerary/agenda/agenda.mjs";
+import { addParada } from "../itinerary/paradas/paradas.mjs";
+import { crearChecklistEquipaje } from "../organizacion/equipaje/equipaje.mjs";
+import { guardarPresupuesto } from "../organizacion/presupuesto/presupuesto.mjs";
+import { createFavoritosStore } from "../recuerdos/favoritos/favoritos.mjs";
+import { guardarNota, limpiarNotas } from "../recuerdos/notas/notas.mjs";
+import { buildDashboardModel, renderDashboardHTML } from "./dashboard.mjs";
+
+class LocalStorageMock {
+  #map = new Map();
+
+  clear() {
+    this.#map.clear();
+  }
+
+  getItem(key) {
+    return this.#map.has(key) ? this.#map.get(key) : null;
+  }
+
+  setItem(key, value) {
+    this.#map.set(key, String(value));
+  }
+
+  removeItem(key) {
+    this.#map.delete(key);
+  }
+}
+
+test.beforeEach(() => {
+  globalThis.localStorage = new LocalStorageMock();
+  limpiarNotas();
+});
+
+test.afterEach(() => {
+  delete globalThis.localStorage;
+});
+
+test("buildDashboardModel compone itinerario, organización y recuerdos desde los stores canónicos", () => {
+  addParada({
+    id: "madrid",
+    nombre: "Madrid",
+    fechaInicio: "2026-09-01",
+    fechaFin: "2026-09-03",
+    descripcion: "Llegada y paseos"
+  });
+  addParada({
+    id: "valencia",
+    nombre: "Valencia",
+    fechaInicio: "2026-09-04",
+    fechaFin: "2026-09-06",
+    descripcion: "Costa y descanso"
+  });
+
+  addActividad({
+    id: "madrid-desayuno",
+    fecha: "2026-09-01",
+    paradaId: "madrid",
+    horario: "08:00",
+    estado: "pendiente"
+  });
+  addActividad({
+    id: "valencia-museo",
+    fecha: "2026-09-05",
+    paradaId: "valencia",
+    horario: "11:30",
+    estado: "completada"
+  });
+
+  guardarPresupuesto({
+    total: 1000,
+    gastos: [
+      { categoria: "Alojamiento", gasto: 420 },
+      { categoria: "Comida", gasto: 180 }
+    ]
+  });
+
+  const checklist = crearChecklistEquipaje();
+  checklist.agregarEquipaje("Pasaporte");
+  checklist.agregarEquipaje("Cargador");
+  checklist.completarEquipaje(checklist.get().items[0].id, true);
+
+  const favoritos = createFavoritosStore();
+  favoritos.marcarFavorito({
+    id: "museo",
+    tipo: "lugar",
+    nombre: "Museo de los Ninos"
+  });
+
+  guardarNota({
+    id: "nota-1",
+    texto: "Buscar heladería cerca del hotel",
+    paradaId: "valencia"
+  });
+
+  const model = buildDashboardModel();
+
+  assert.deepEqual(model.trip, {
+    name: "Viaje en familia",
+    rangeLabel: "1 sep 2026 - 6 sep 2026",
+    stopCount: 2,
+    stops: [
+      {
+        index: 1,
+        id: "madrid",
+        nombre: "Madrid",
+        fechaInicio: "2026-09-01",
+        fechaFin: "2026-09-03",
+        descripcion: "Llegada y paseos"
+      },
+      {
+        index: 2,
+        id: "valencia",
+        nombre: "Valencia",
+        fechaInicio: "2026-09-04",
+        fechaFin: "2026-09-06",
+        descripcion: "Costa y descanso"
+      }
+    ]
+  });
+
+  assert.deepEqual(model.events, [
+    {
+      id: "madrid-desayuno",
+      fecha: "2026-09-01",
+      horario: "08:00",
+      paradaId: "madrid",
+      paradaNombre: "Madrid",
+      estado: "Pendiente"
+    },
+    {
+      id: "valencia-museo",
+      fecha: "2026-09-05",
+      horario: "11:30",
+      paradaId: "valencia",
+      paradaNombre: "Valencia",
+      estado: "Completada"
+    }
+  ]);
+
+  assert.equal(model.budget.total, 1000);
+  assert.equal(model.budget.gastado, 600);
+  assert.equal(model.budget.disponible, 400);
+  assert.equal(model.packing.porcentaje, 50);
+  assert.equal(model.memories.favorites.length, 1);
+  assert.equal(model.memories.notes.length, 1);
+});
+
+test("renderDashboardHTML integra las secciones principales del dashboard", () => {
+  const html = renderDashboardHTML({
+    trip: {
+      name: "Viaje en familia",
+      rangeLabel: "1 sep 2026 - 6 sep 2026",
+      stopCount: 2,
+      stops: []
+    },
+    events: [],
+    budget: {
+      total: 1000,
+      gastado: 600,
+      disponible: 400,
+      porcentajeGastado: 0.6,
+      porcentajeDisponible: 0.4,
+      estadoVisual: {
+        clave: "controlado",
+        etiqueta: "En control",
+        tono: "positivo"
+      },
+      gastosPorCategoria: []
+    },
+    packing: {
+      total: 2,
+      completados: 1,
+      pendientes: 1,
+      porcentaje: 50,
+      items: []
+    },
+    memories: {
+      favorites: [],
+      notes: []
+    }
+  });
+
+  assert.match(html, /Dashboard del viaje/);
+  assert.match(html, /Itinerario/);
+  assert.match(html, /Próximos eventos/);
+  assert.match(html, /Presupuesto/);
+  assert.match(html, /Equipaje/);
+  assert.match(html, /Recuerdos destacados/);
+});
+

