+  text-transform: uppercase;
+  letter-spacing: 0.08em;
+}
+
+.budget-stats dd {
+  margin: 0.25rem 0 0;
+  font-size: 1.05rem;
+}
+
+.budget-breakdown li,
+.memory-list li {
+  grid-template-columns: 1fr auto;
+  align-items: center;
+}
+
+.packing-summary {
+  display: grid;
+  grid-template-columns: auto 1fr;
+  gap: 1rem;
+  align-items: center;
+  margin-bottom: 1rem;
+}
+
+.packing-summary__ring {
+  width: 5rem;
+  height: 5rem;
+  display: grid;
+  place-items: center;
+  border-radius: 50%;
+  background: radial-gradient(circle, rgba(247, 185, 85, 0.2), rgba(247, 185, 85, 0.06) 65%, transparent 66%);
+  border: 1px solid rgba(247, 185, 85, 0.25);
+  color: var(--accent);
+}
+
+.packing-summary__ring strong {
+  font-size: 1.2rem;
+}
+
+.checklist li.is-complete span,
+.checklist li.is-complete strong {
+  color: #d6f8ea;
+}
+
+.memory-columns {
+  display: grid;
+  gap: 1rem;
+}
+
+.memory-columns section {
+  display: grid;
+  gap: 0.75rem;
+}
+
+.memory-columns h3 {
+  margin: 0;
+  font-size: 1rem;
+  color: var(--accent-2);
+}
+
+.empty-state {
+  padding: 1rem;
+  border-radius: 16px;
+  color: var(--muted);
+  border: 1px dashed rgba(255, 255, 255, 0.12);
+  background: rgba(255, 255, 255, 0.02);
+}
+
+@media (max-width: 960px) {
