+}
+
+@media (max-width: 640px) {
+  .app-shell {
+    width: min(100% - 1rem, 1200px);
+    padding-top: 0.5rem;
+  }
+
+  .hero,
+  .dashboard-grid > .card {
+    padding: 1rem;
+  }
+
+  .hero__head,
+  .packing-summary,
+  .stack-card,
+  .event-row {
+    grid-template-columns: 1fr;
+    align-items: start;
+  }
+
+  .budget-stats {
+    grid-template-columns: 1fr;
+  }
+}
