+
+class LocalStorageMock {
+  #map = new Map();
+
+  clear() {
+    this.#map.clear();
+  }
+
+  getItem(key) {
+    return this.#map.has(key) ? this.#map.get(key) : null;
+  }
+
+  setItem(key, value) {
+    this.#map.set(key, String(value));
+  }
+
+  removeItem(key) {
+    this.#map.delete(key);
+  }
+}
+
+test.beforeEach(() => {
+  globalThis.localStorage = new LocalStorageMock();
+  limpiarNotas();
+});
+
+test.afterEach(() => {
+  delete globalThis.localStorage;
+});
+
+test("buildDashboardModel compone itinerario, organización y recuerdos desde los stores canónicos", () => {
+  addParada({
+    id: "madrid",
+    nombre: "Madrid",
+    fechaInicio: "2026-09-01",
+    fechaFin: "2026-09-03",
+    descripcion: "Llegada y paseos"
+  });
+  addParada({
+    id: "valencia",
+    nombre: "Valencia",
+    fechaInicio: "2026-09-04",
+    fechaFin: "2026-09-06",
+    descripcion: "Costa y descanso"
+  });
+
+  addActividad({
+    id: "madrid-desayuno",
+    fecha: "2026-09-01",
+    paradaId: "madrid",
+    horario: "08:00",
+    estado: "pendiente"
+  });
+  addActividad({
+    id: "valencia-museo",
+    fecha: "2026-09-05",
+    paradaId: "valencia",
+    horario: "11:30",
+    estado: "completada"
+  });
+
+  guardarPresupuesto({
+    total: 1000,
+    gastos: [
+      { categoria: "Alojamiento", gasto: 420 },
+      { categoria: "Comida", gasto: 180 }
+    ]
