+
+  assert.equal(model.budget.total, 1000);
+  assert.equal(model.budget.gastado, 600);
+  assert.equal(model.budget.disponible, 400);
+  assert.equal(model.packing.porcentaje, 50);
+  assert.equal(model.memories.favorites.length, 1);
+  assert.equal(model.memories.notes.length, 1);
+});
+
+test("renderDashboardHTML integra las secciones principales del dashboard", () => {
+  const html = renderDashboardHTML({
+    trip: {
+      name: "Viaje en familia",
