+  addParada({
+    id: "valencia",
+    nombre: "Valencia",
+    fechaInicio: "2026-09-04",
+    fechaFin: "2026-09-06",
+    descripcion: "Costa y descanso"
+  });
+
+  addActividad({
+    id: "madrid-desayuno",
+    fecha: "2026-09-01",
+    paradaId: "madrid",
+    horario: "08:00",
+    estado: "pendiente"
+  });
+  addActividad({
+    id: "valencia-museo",
+    fecha: "2026-09-05",
+    paradaId: "valencia",
+    horario: "11:30",
+    estado: "completada"
+  });
+
+  guardarPresupuesto({
+    total: 1000,
+    gastos: [
+      { categoria: "Alojamiento", gasto: 420 },
+      { categoria: "Comida", gasto: 180 }
+    ]
+  });
+
+  const checklist = crearChecklistEquipaje();
+  checklist.agregarEquipaje("Pasaporte");
+  checklist.agregarEquipaje("Cargador");
+  checklist.completarEquipaje(checklist.get().items[0].id, true);
+
+  const favoritos = createFavoritosStore();
+  favoritos.marcarFavorito({
+    id: "museo",
+    tipo: "lugar",
+    nombre: "Museo de los Ninos"
+  });
+
+  guardarNota({
+    id: "nota-1",
+    texto: "Buscar heladería cerca del hotel",
+    paradaId: "valencia"
+  });
+
+  const model = buildDashboardModel();
+
+  assert.deepEqual(model.trip, {
+    name: "Viaje en familia",
+    rangeLabel: "1 sep 2026 - 6 sep 2026",
+    stopCount: 2,
+    stops: [
+      {
+        index: 1,
+        id: "madrid",
+        nombre: "Madrid",
+        fechaInicio: "2026-09-01",
+        fechaFin: "2026-09-03",
+        descripcion: "Llegada y paseos"
+      },
+      {
+        index: 2,
+        id: "valencia",
+        nombre: "Valencia",
+        fechaInicio: "2026-09-04",
+        fechaFin: "2026-09-06",
+        descripcion: "Costa y descanso"
+      }
+    ]
+  });
+
+  assert.deepEqual(model.events, [
+    {
+      id: "madrid-desayuno",
+      fecha: "2026-09-01",
+      horario: "08:00",
+      paradaId: "madrid",
+      paradaNombre: "Madrid",
+      estado: "Pendiente"
+    },
+    {
+      id: "valencia-museo",
+      fecha: "2026-09-05",
+      horario: "11:30",
+      paradaId: "valencia",
+      paradaNombre: "Valencia",
+      estado: "Completada"
+    }
