diff --git a/public/main.mjs b/public/main.mjs
new file mode 100644
index 0000000000000000000000000000000000000000..2c998c286e5163bbb3477b9928ab37b89628c5f4
--- /dev/null
+++ b/public/main.mjs
@@ -0,0 +1,336 @@
+const STORAGE_PREFIX = "viaje-en-familia:v1:";
+
+const MONTHS = [
+  "ene",
+  "feb",
+  "mar",
+  "abr",
+  "may",
+  "jun",
+  "jul",
+  "ago",
+  "sep",
+  "oct",
+  "nov",
+  "dic"
+];
+
+function isRecord(value) {
+  return value !== null && typeof value === "object" && !Array.isArray(value);
+}
+
+function toItems(value) {
+  return Array.isArray(value) ? value.filter(isRecord) : [];
+}
+
+function readStore(key, fallback) {
+  try {
+    const raw = globalThis.localStorage?.getItem(`${STORAGE_PREFIX}${key}`);
+    if (raw === null || raw === undefined) {
+      return fallback;
+    }
+
+    return JSON.parse(raw);
+  } catch {
+    return fallback;
+  }
+}
+
+function normalizeIsoDate(value) {
+  if (typeof value !== "string") {
+    return "";
+  }
+
+  const trimmed = value.trim();
+  return /^\d{4}-\d{2}-\d{2}$/.test(trimmed) ? trimmed : "";
+}
+
+function compareIsoDate(left, right) {
+  return normalizeIsoDate(left).localeCompare(normalizeIsoDate(right));
+}
+
+function formatDate(value) {
+  const iso = normalizeIsoDate(value);
+  if (!iso) {
+    return "";
+  }
+
+  const [year, month, day] = iso.split("-");
+  return `${Number(day)} ${MONTHS[Number(month) - 1] ?? month} ${year}`;
+}
+
+function formatDateRange(start, end) {
+  const from = normalizeIsoDate(start);
+  const to = normalizeIsoDate(end);
+
+  if (!from && !to) {
+    return "Fechas por definir";
+  }
+
+  if (from && from === to) {
+    return formatDate(from);
+  }
+
+  if (!from) {
+    return `Hasta ${formatDate(to)}`;
+  }
+
+  if (!to) {
+    return `Desde ${formatDate(from)}`;
+  }
+
+  return `${formatDate(from)} - ${formatDate(to)}`;
+}
+
+function escapeHtml(value) {
+  return String(value ?? "")
+    .replaceAll("&", "&amp;")
+    .replaceAll("<", "&lt;")
+    .replaceAll(">", "&gt;")
+    .replaceAll('"', "&quot;")
+    .replaceAll("'", "&#39;");
+}
+
+function formatCurrency(value) {
+  const amount = Number(value);
+  return new Intl.NumberFormat("es-AR", {
+    style: "currency",
+    currency: "ARS",
+    maximumFractionDigits: 0
+  }).format(Number.isFinite(amount) ? amount : 0);
+}
+
+function buildDashboardModel() {
+  const paradas = toItems(readStore("itinerary/paradas", []));
+  const actividades = toItems(readStore("itinerary/agenda", []));
+  const presupuesto = isRecord(readStore("organizacion/presupuesto", {}))
+    ? readStore("organizacion/presupuesto", {})
+    : {};
+  const equipaje = isRecord(readStore("organizacion/equipaje", {}))
+    ? readStore("organizacion/equipaje", {})
+    : {};
+  const favoritos = toItems(readStore("recuerdos/favoritos", []));
+  const notas = toItems(readStore("recuerdos/notas", []));
+
+  const orderedStops = [...paradas].sort((left, right) => {
+    const byStart = compareIsoDate(left.fechaInicio, right.fechaInicio);
+    if (byStart !== 0) {
+      return byStart;
+    }
+
+    const byEnd = compareIsoDate(left.fechaFin, right.fechaFin);
+    if (byEnd !== 0) {
+      return byEnd;
+    }
+
+    return String(left.nombre ?? "").localeCompare(String(right.nombre ?? ""));
+  });
+
+  const firstStop = orderedStops[0];
+  const lastStop = orderedStops[orderedStops.length - 1];
+  const events = actividades
+    .slice()
+    .sort((left, right) => {
+      const byDate = compareIsoDate(left.fecha, right.fecha);
+      if (byDate !== 0) {
+        return byDate;
+      }
+
+      return String(left.horario ?? "").localeCompare(String(right.horario ?? ""));
+    })
+    .slice(0, 4)
+    .map((actividad) => {
+      const parada = orderedStops.find((item) => item.id === actividad.paradaId);
+      return {
+        fecha: normalizeIsoDate(actividad.fecha),
+        horario: String(actividad.horario ?? "Sin horario"),
+        paradaNombre: String(parada?.nombre ?? "Parada sin nombre"),
+        estado: actividad.estado === "completada" ? "Completada" : "Pendiente"
+      };
+    });
+
+  const budgetItems = Array.isArray(presupuesto.gastosPorCategoria)
+    ? presupuesto.gastosPorCategoria.slice(0, 4)
+    : [];
+  const items = toItems(equipaje.items);
+  const completed = items.filter((item) => Boolean(item.completado)).length;
+
+  return {
+    trip: {
+      name: "Viaje en familia",
+      rangeLabel: formatDateRange(firstStop?.fechaInicio ?? "", lastStop?.fechaFin ?? ""),
+      stopCount: orderedStops.length,
+      stops: orderedStops
+    },
+    events,
+    budget: {
+      total: Number(presupuesto.total ?? 0),
+      gastado: Number(presupuesto.gastado ?? 0),
+      disponible: Number(presupuesto.disponible ?? 0),
+      porcentajeGastado: Number(presupuesto.porcentajeGastado ?? 0),
+      porcentajeDisponible: Number(presupuesto.porcentajeDisponible ?? 0),
+      estadoVisual: isRecord(presupuesto.estadoVisual)
+        ? presupuesto.estadoVisual
+        : { etiqueta: "Sin presupuesto", tono: "neutral" },
+      gastosPorCategoria: budgetItems
+    },
+    packing: {
+      total: items.length,
+      completados: completed,
+      pendientes: items.length - completed,
+      porcentaje: items.length === 0 ? 0 : Math.round((completed / items.length) * 100),
+      items
+    },
+    memories: {
+      favorites,
+      notes
+    }
+  };
+}
+
+function renderHTML(model) {
+  const progress = Math.max(0, Math.min(100, model.packing.porcentaje ?? 0));
+  const budgetProgress = Math.max(0, Math.min(100, Math.round((model.budget.porcentajeGastado ?? 0) * 100)));
+
+  return `
+    <main class="dashboard-shell">
+      <section class="hero card">
+        <p class="eyebrow">Dashboard del viaje</p>
+        <div class="hero__head">
+          <div>
+            <h1>${escapeHtml(model.trip.name)}</h1>
+            <p class="hero__dates">${escapeHtml(model.trip.rangeLabel)}</p>
+          </div>
+          <div class="hero__badge">${escapeHtml(`${model.trip.stopCount} paradas`)}</div>
+        </div>
+        <div class="hero__metrics">
+          <div class="metric"><span class="metric__label">Próximos eventos</span><strong class="metric__value">${model.events.length}</strong></div>
+          <div class="metric"><span class="metric__label">Presupuesto disponible</span><strong class="metric__value">${escapeHtml(formatCurrency(model.budget.disponible))}</strong></div>
+          <div class="metric"><span class="metric__label">Equipaje listo</span><strong class="metric__value">${progress}%</strong></div>
+          <div class="metric"><span class="metric__label">Recuerdos</span><strong class="metric__value">${model.memories.favorites.length + model.memories.notes.length}</strong></div>
+        </div>
+      </section>
+
+      <section class="dashboard-grid">
+        <article class="card card--itinerary">
+          <div class="section-head">
+            <p class="eyebrow">Itinerario</p>
+            <h2>Paradas del viaje</h2>
+          </div>
+          <ul class="stack-list">
+            ${model.trip.stops.length ? model.trip.stops.map((stop, index) => `
+              <li class="stack-card">
+                <span class="stack-card__index">0${index + 1}</span>
+                <div>
+                  <h3>${escapeHtml(stop.nombre ?? "Parada sin nombre")}</h3>
+                  <p>${escapeHtml(formatDateRange(stop.fechaInicio ?? "", stop.fechaFin ?? ""))}</p>
+                </div>
+                <span class="stack-card__meta">${escapeHtml(stop.descripcion ?? "Sin descripción")}</span>
+              </li>
+            `).join("") : '<li class="empty-state">Todavía no hay paradas cargadas.</li>'}
+          </ul>
+        </article>
+
+        <article class="card card--events">
+          <div class="section-head">
+            <p class="eyebrow">Próximos eventos</p>
+            <h2>Agenda visible</h2>
+          </div>
+          <ul class="event-list">
+            ${model.events.length ? model.events.map((event) => `
+              <li class="event-row">
+                <div class="event-row__time">
+                  <strong>${escapeHtml(event.horario)}</strong>
+                  <span>${escapeHtml(formatDate(event.fecha))}</span>
+                </div>
+                <div class="event-row__body">
+                  <h3>${escapeHtml(event.paradaNombre)}</h3>
+                  <p>${escapeHtml(`Actividad ${event.estado.toLowerCase()}`)}</p>
+                </div>
+                <span class="event-row__status">${escapeHtml(event.estado)}</span>
+              </li>
+            `).join("") : '<li class="empty-state">No hay eventos programados.</li>'}
+          </ul>
+        </article>
+
+        <article class="card card--budget">
+          <div class="section-head">
+            <p class="eyebrow">Presupuesto</p>
+            <h2>Resumen financiero</h2>
+          </div>
+          <div class="budget-summary">
+            <div class="budget-summary__bar" aria-hidden="true">
+              <span style="width: ${budgetProgress}%"></span>
+            </div>
+            <dl class="budget-stats">
+              <div><dt>Total</dt><dd>${escapeHtml(formatCurrency(model.budget.total))}</dd></div>
+              <div><dt>Gastado</dt><dd>${escapeHtml(formatCurrency(model.budget.gastado))}</dd></div>
+              <div><dt>Disponible</dt><dd>${escapeHtml(formatCurrency(model.budget.disponible))}</dd></div>
+              <div><dt>Estado</dt><dd>${escapeHtml(model.budget.estadoVisual?.etiqueta ?? "Sin presupuesto")}</dd></div>
+            </dl>
+          </div>
+          <ul class="budget-breakdown">
+            ${model.budget.gastosPorCategoria.length ? model.budget.gastosPorCategoria.map((item) => `
+              <li><span>${escapeHtml(item.categoria ?? "Sin categoría")}</span><strong>${escapeHtml(formatCurrency(item.gasto ?? 0))}</strong></li>
+            `).join("") : '<li class="empty-state">Aún no hay gastos cargados.</li>'}
+          </ul>
+        </article>
+
+        <article class="card card--packing">
+          <div class="section-head">
+            <p class="eyebrow">Equipaje</p>
+            <h2>Progreso de preparación</h2>
+          </div>
+          <div class="packing-summary">
+            <div class="packing-summary__ring" aria-hidden="true">
+              <strong>${escapeHtml(String(model.packing.porcentaje))}%</strong>
+            </div>
+            <div>
+              <p>${escapeHtml(`${model.packing.completados} listos, ${model.packing.pendientes} pendientes`)}</p>
+              <p class="muted">Revisión rápida del checklist compartido.</p>
+            </div>
+          </div>
+          <ul class="checklist">
+            ${model.packing.items.length ? model.packing.items.map((item) => `
+              <li class="${item.completado ? "is-complete" : ""}">
+                <span>${escapeHtml(item.nombre ?? "Elemento sin nombre")}</span>
+                <strong>${item.completado ? "Listo" : "Pendiente"}</strong>
+              </li>
+            `).join("") : '<li class="empty-state">Todavía no hay equipaje registrado.</li>'}
+          </ul>
+        </article>
+
+        <article class="card card--memories">
+          <div class="section-head">
+            <p class="eyebrow">Recuerdos destacados</p>
+            <h2>Lo que vale conservar</h2>
+          </div>
+          <div class="memory-columns">
+            <section>
+              <h3>Favoritos</h3>
+              <ul class="memory-list">
+                ${model.memories.favorites.length ? model.memories.favorites.map((item) => `
+                  <li><span>${escapeHtml(item.tipo ?? "favorito")}</span><strong>${escapeHtml(item.nombre ?? item.id ?? "Favorito sin nombre")}</strong></li>
+                `).join("") : '<li class="empty-state">Todavía no hay favoritos destacados.</li>'}
+              </ul>
+            </section>
+            <section>
+              <h3>Notas</h3>
+              <ul class="memory-list">
+                ${model.memories.notes.length ? model.memories.notes.map((item) => `
+                  <li><strong>${escapeHtml(item.texto ?? "Nota sin texto")}</strong><span>${escapeHtml(item.paradaId ? `Parada ${item.paradaId}` : item.diaId ? `Día ${item.diaId}` : "Sin contexto")}</span></li>
+                `).join("") : '<li class="empty-state">Todavía no hay notas guardadas.</li>'}
+              </ul>
+            </section>
+          </div>
+        </article>
+      </section>
+    </main>
+  `;
+}
+
+const app = document.querySelector("#app");
+if (app) {
+  const model = buildDashboardModel();
+  app.innerHTML = renderHTML(model);
+}
