+<!doctype html>
+<html lang="es">
+  <head>
+    <meta charset="utf-8" />
+    <meta name="viewport" content="width=device-width, initial-scale=1" />
+    <meta name="color-scheme" content="dark" />
+    <title>Viaje en Familia</title>
+    <link rel="stylesheet" href="/styles.css" />
+  </head>
