+        fechaInicio: "2026-09-04",
+        fechaFin: "2026-09-06",
+        descripcion: "Costa y descanso"
+      }
+    ]
+  });
+
+  assert.deepEqual(model.events, [
+    {
+      id: "madrid-desayuno",
+      fecha: "2026-09-01",
+      horario: "08:00",
+      paradaId: "madrid",
+      paradaNombre: "Madrid",
+      estado: "Pendiente"
+    },
+    {
