+    linear-gradient(225deg, rgba(255, 255, 255, 0.025) 0 2px, transparent 2px 24px),
+    linear-gradient(180deg, transparent, rgba(0, 0, 0, 0.2));
+  background-size: 48px 48px, 48px 48px, 100% 100%;
+}
+
+body::before {
