+  font-size: 1rem;
+}
+
+.stack-card p,
+.event-row p,
+.memory-list li {
+  margin: 0;
+}
+
+.event-row {
+  grid-template-columns: auto 1fr auto;
+  align-items: center;
+}
+
+.event-row__time strong {
