+  overflow: hidden;
+  background: rgba(255, 255, 255, 0.08);
+}
+
+.budget-summary__bar span {
+  display: block;
+  height: 100%;
+  border-radius: inherit;
+  background: linear-gradient(90deg, var(--accent), var(--accent-3));
