+  gap: 0.75rem;
+}
+
+.memory-columns h3 {
+  margin: 0;
+  font-size: 1rem;
+  color: var(--accent-2);
+}
+
+.empty-state {
+  padding: 1rem;
+  border-radius: 16px;
+  color: var(--muted);
+  border: 1px dashed rgba(255, 255, 255, 0.12);
+  background: rgba(255, 255, 255, 0.02);
+}
+
+@media (max-width: 960px) {
+  .card--itinerary,
+  .card--events,
+  .card--budget,
