+  font-weight: 800;
+}
+
+.dashboard-progress {
+  height: 10px;
+  overflow: hidden;
+  background: #e9f1f7;
+  border-radius: 999px;
+  border: 1px solid rgba(215, 224, 234, 0.95);
+}
+
+.dashboard-progress span {
+  display: block;
+  height: 100%;
+  border-radius: inherit;
+  background: linear-gradient(90deg, var(--accent), #33a19b);
+}
+
+.dashboard-list,
+.dashboard-mini-list,
