diff --git a/public/dashboard.mjs b/public/dashboard.mjs
new file mode 100644
index 0000000000000000000000000000000000000000..839c3d8cedd1549714967327db20c8a21d346dea
--- /dev/null
+++ b/public/dashboard.mjs
@@ -0,0 +1,596 @@
+const MONTHS_SHORT_ES = [
+  "ene",
+  "feb",
+  "mar",
+  "abr",
+  "may",
+  "jun",
+  "jul",
+  "ago",
+  "sep",
+  "oct",
+  "nov",
+  "dic"
+];
+
+const STORAGE_PREFIX = "viaje-en-familia:v1:";
+const KEYS = Object.freeze({
+  paradas: `${STORAGE_PREFIX}itinerary/paradas`,
+  actividades: `${STORAGE_PREFIX}itinerary/agenda`,
+  presupuesto: `${STORAGE_PREFIX}organizacion/presupuesto`,
+  equipaje: `${STORAGE_PREFIX}organizacion/equipaje`,
+  favoritos: `${STORAGE_PREFIX}recuerdos/favoritos`,
+  notas: `${STORAGE_PREFIX}recuerdos/notas`
+});
+
+function isRecord(value) {
+  return value !== null && typeof value === "object" && !Array.isArray(value);
+}
+
+function toText(value) {
+  return value === undefined || value === null ? "" : String(value).trim();
+}
+
+function toIsoDate(value) {
+  const text = toText(value);
+  return /^\d{4}-\d{2}-\d{2}$/.test(text) ? text : "";
+}
+
+function getLocalIsoDate(date = new Date()) {
+  const year = date.getFullYear();
+  const month = String(date.getMonth() + 1).padStart(2, "0");
+  const day = String(date.getDate()).padStart(2, "0");
+  return `${year}-${month}-${day}`;
+}
+
+function compareSchedule(a, b) {
+  if (a.fecha !== b.fecha) {
+    return a.fecha.localeCompare(b.fecha);
+  }
+
+  if (a.horario !== b.horario) {
+    return a.horario.localeCompare(b.horario);
+  }
+
+  return toText(a.paradaId).localeCompare(toText(b.paradaId));
+}
+
+function formatIsoDate(value) {
+  const iso = toIsoDate(value);
+  if (!iso) {
+    return toText(value);
+  }
+
+  const year = Number(iso.slice(0, 4));
+  const monthIndex = Number(iso.slice(5, 7)) - 1;
+  const day = Number(iso.slice(8, 10));
+  const month = MONTHS_SHORT_ES[monthIndex] ?? "";
+  return `${day} ${month} ${year}`;
+}
+
+function formatDateRange(start, end) {
+  const from = toIsoDate(start);
+  const to = toIsoDate(end);
+
+  if (!from && !to) {
+    return "Fechas pendientes";
+  }
+
+  if (from && from === to) {
+    return formatIsoDate(from);
+  }
+
+  if (from && to) {
+    return `${formatIsoDate(from)} al ${formatIsoDate(to)}`;
+  }
+
+  return formatIsoDate(from || to);
+}
+
+function escapeHtml(value) {
+  return toText(value)
+    .replaceAll("&", "&amp;")
+    .replaceAll("<", "&lt;")
+    .replaceAll(">", "&gt;")
+    .replaceAll('"', "&quot;")
+    .replaceAll("'", "&#39;");
+}
+
+function readJson(key) {
+  const raw = globalThis.localStorage?.getItem(key);
+  if (!raw) {
+    return undefined;
+  }
+
+  try {
+    return JSON.parse(raw);
+  } catch {
+    return undefined;
+  }
+}
+
+function getParadaTitle(parada) {
+  return toText(parada?.nombre) || "Parada sin nombre";
+}
+
+function getMemoryTitle(memory) {
+  return toText(memory?.nombre ?? memory?.title ?? memory?.titulo ?? memory?.name) || "Sin título";
+}
+
+function getMemorySubtitle(memory) {
+  return toText(memory?.descripcion ?? memory?.texto ?? memory?.notes ?? memory?.nota) || "Sin detalle";
+}
+
+function buildTripSummary(paradas) {
+  const ordered = [...paradas]
+    .filter(isRecord)
+    .map((parada) => ({
+      id: parada.id,
+      nombre: getParadaTitle(parada),
+      fechaInicio: toIsoDate(parada.fechaInicio),
+      fechaFin: toIsoDate(parada.fechaFin),
+      descripcion: toText(parada.descripcion)
+    }))
+    .sort((a, b) => a.fechaInicio.localeCompare(b.fechaInicio));
+
+  const first = ordered[0] ?? null;
+  const last = ordered[ordered.length - 1] ?? null;
+
+  return {
+    title: "Viaje en Familia",
+    dateRange: formatDateRange(first?.fechaInicio, last?.fechaFin),
+    route:
+      ordered.length === 0
+        ? "Todavía no hay paradas"
+        : ordered.length === 1
+          ? first.nombre
+          : `${first.nombre} · ${last.nombre}`,
+    count: ordered.length,
+    paradas: ordered
+  };
+}
+
+function buildUpcomingEvents(actividades, paradas, referenceDate = new Date()) {
+  const paradaMap = new Map(
+    paradas.filter(isRecord).map((parada) => [parada.id, parada])
+  );
+  const today = getLocalIsoDate(referenceDate);
+  const ordered = actividades
+    .filter(isRecord)
+    .map((actividad) => ({
+      id: actividad.id,
+      fecha: toIsoDate(actividad.fecha),
+      paradaId: actividad.paradaId,
+      horario: toText(actividad.horario),
+      estado: toText(actividad.estado) || "pendiente",
+      paradaNombre: paradaMap.get(actividad.paradaId)
+        ? getParadaTitle(paradaMap.get(actividad.paradaId))
+        : "Parada sin nombre",
+      descripcion: toText(actividad.descripcion)
+    }))
+    .sort(compareSchedule);
+
+  const upcoming = ordered.filter((actividad) => actividad.fecha && actividad.fecha >= today);
+  const source = upcoming.length > 0 ? upcoming : ordered;
+
+  return source.slice(0, 5).map((actividad) => ({
+    ...actividad,
+    fechaTexto: formatIsoDate(actividad.fecha),
+    estadoTexto: actividad.estado === "completada" ? "Completada" : "Pendiente"
+  }));
+}
+
+function buildBudgetSummary() {
+  const presupuesto = readJson(KEYS.presupuesto) ?? {};
+  const gastos = Array.isArray(presupuesto.gastos) ? presupuesto.gastos : [];
+  const grouped = new Map();
+
+  for (const gasto of gastos) {
+    const categoria = toText(gasto?.categoria) || "Sin categoría";
+    const monto = Number(gasto?.gasto ?? gasto?.monto ?? gasto?.importe);
+    const numeric = Number.isFinite(monto) && monto >= 0 ? monto : 0;
+    grouped.set(categoria, (grouped.get(categoria) ?? 0) + numeric);
+  }
+
+  const gastosPorCategoria = [...grouped.entries()].map(([categoria, gasto]) => ({
+    categoria,
+    gasto
+  }));
+  const total = Number(presupuesto.total);
+  const totalValido = Number.isFinite(total) && total > 0 ? total : 0;
+  const gastado = gastosPorCategoria.reduce((sum, item) => sum + item.gasto, 0);
+  const disponible = totalValido - gastado;
+  const porcentajeGastado = totalValido > 0 ? gastado / totalValido : 0;
+
+  let estadoVisual = {
+    clave: "sin_presupuesto",
+    etiqueta: "Sin presupuesto",
+    tono: "neutral"
+  };
+
+  if (disponible < 0) {
+    estadoVisual = { clave: "sobregasto", etiqueta: "Sobregasto", tono: "critico" };
+  } else if (totalValido === 0) {
+    estadoVisual = { clave: "sin_presupuesto", etiqueta: "Sin presupuesto", tono: "neutral" };
+  } else if (disponible === 0) {
+    estadoVisual = { clave: "agotado", etiqueta: "Presupuesto agotado", tono: "warning" };
+  } else if (porcentajeGastado >= 0.8) {
+    estadoVisual = { clave: "advertencia", etiqueta: "Cerca del límite", tono: "warning" };
+  } else {
+    estadoVisual = { clave: "controlado", etiqueta: "En control", tono: "positive" };
+  }
+
+  return {
+    total: totalValido,
+    gastado,
+    disponible,
+    porcentajeGastado,
+    porcentajeDisponible: totalValido > 0 ? disponible / totalValido : 0,
+    gastosPorCategoria,
+    estadoVisual
+  };
+}
+
+function buildPackingSummary() {
+  const state = readJson(KEYS.equipaje) ?? { items: [], filtro: "todos" };
+  const items = Array.isArray(state.items) ? state.items : [];
+  const total = items.length;
+  const completados = items.filter((item) => Boolean(item?.completado)).length;
+  const pendientes = total - completados;
+  const porcentaje = total === 0 ? 0 : Math.round((completados / total) * 100);
+
+  return {
+    items,
+    filtro: toText(state.filtro) || "todos",
+    progreso: {
+      total,
+      completados,
+      pendientes,
+      porcentaje
+    }
+  };
+}
+
+function buildMemoryHighlights() {
+  const favoritos = Array.isArray(readJson(KEYS.favoritos)) ? readJson(KEYS.favoritos) : [];
+  const notas = Array.isArray(readJson(KEYS.notas)) ? readJson(KEYS.notas) : [];
+
+  return {
+    favoritos: favoritos.slice(0, 4).map((item) => ({
+      id: toText(item.id),
+      title: getMemoryTitle(item),
+      subtitle: getMemorySubtitle(item),
+      tipo: toText(item.tipo ?? item.type ?? item.kind ?? item.categoria)
+    })),
+    notas: notas.slice(0, 4).map((nota) => ({
+      id: toText(nota.id),
+      title: getMemoryTitle(nota),
+      subtitle: getMemorySubtitle(nota),
+      scope: toText(nota.diaId ?? nota.paradaId)
+    })),
+    totalFavoritos: favoritos.length,
+    totalNotas: notas.length
+  };
+}
+
+function buildDashboardModel(referenceDate = new Date()) {
+  const paradas = Array.isArray(readJson(KEYS.paradas)) ? readJson(KEYS.paradas) : [];
+  const actividades = Array.isArray(readJson(KEYS.actividades)) ? readJson(KEYS.actividades) : [];
+
+  return {
+    trip: buildTripSummary(paradas),
+    upcomingEvents: buildUpcomingEvents(actividades, paradas, referenceDate),
+    budget: buildBudgetSummary(),
+    packing: buildPackingSummary(),
+    memories: buildMemoryHighlights(),
+    counts: {
+      paradas: paradas.filter(isRecord).length,
+      actividades: actividades.filter(isRecord).length
+    }
+  };
+}
+
+function renderBadge(text, tone = "neutral") {
+  return `<span class="dashboard-badge dashboard-badge--${escapeHtml(tone)}">${escapeHtml(text)}</span>`;
+}
+
+function renderEmptyState(title, text) {
+  return `
+    <div class="dashboard-empty">
+      <strong>${escapeHtml(title)}</strong>
+      <p>${escapeHtml(text)}</p>
+    </div>
+  `;
+}
+
+function renderUpcomingEvents(events) {
+  if (events.length === 0) {
+    return renderEmptyState("Sin eventos próximos", "Agrega actividades para ver la agenda ordenada aquí.");
+  }
+
+  return `
+    <ol class="dashboard-list dashboard-list--events">
+      ${events
+        .map(
+          (event) => `
+            <li class="dashboard-event">
+              <div>
+                <strong>${escapeHtml(event.paradaNombre)}</strong>
+                <p>${escapeHtml(event.descripcion || event.estadoTexto)}</p>
+              </div>
+              <div class="dashboard-event-meta">
+                <span>${escapeHtml(event.fechaTexto)}</span>
+                <span>${escapeHtml(event.horario || "Sin horario")}</span>
+                ${renderBadge(event.estadoTexto, event.estado === "completada" ? "positive" : "neutral")}
+              </div>
+            </li>
+          `
+        )
+        .join("")}
+    </ol>
+  `;
+}
+
+function renderBudget(budget) {
+  const tone = toText(budget.estadoVisual?.tono) || "neutral";
+  const label = toText(budget.estadoVisual?.etiqueta) || "Sin presupuesto";
+  const total = Number(budget.total ?? 0);
+  const gastado = Number(budget.gastado ?? 0);
+  const disponible = Number(budget.disponible ?? 0);
+  const porcentajeGastado = Math.max(0, Math.min(1, Number(budget.porcentajeGastado ?? 0)));
+  const percentage = Math.round(porcentajeGastado * 100);
+  const statusText = total > 0 ? `${percentage}% usado` : "Sin datos";
+
+  return `
+    <div class="dashboard-card-stack">
+      <div class="dashboard-card-head">
+        <div>
+          <h3>Resumen de presupuesto</h3>
+          <p>${escapeHtml(label)}</p>
+        </div>
+        ${renderBadge(statusText, tone)}
+      </div>
+      <dl class="dashboard-stats">
+        <div>
+          <dt>Total</dt>
+          <dd>${escapeHtml(total.toLocaleString("es-AR", { maximumFractionDigits: 0 }))}</dd>
+        </div>
+        <div>
+          <dt>Gastado</dt>
+          <dd>${escapeHtml(gastado.toLocaleString("es-AR", { maximumFractionDigits: 0 }))}</dd>
+        </div>
+        <div>
+          <dt>Disponible</dt>
+          <dd>${escapeHtml(disponible.toLocaleString("es-AR", { maximumFractionDigits: 0 }))}</dd>
+        </div>
+      </dl>
+      <div class="dashboard-progress" aria-label="Progreso del presupuesto">
+        <span style="width: ${percentage}%"></span>
+      </div>
+      <ul class="dashboard-mini-list">
+        ${(budget.gastosPorCategoria ?? [])
+          .slice(0, 3)
+          .map(
+            (gasto) => `
+              <li>
+                <strong>${escapeHtml(gasto.categoria)}</strong>
+                <span>${escapeHtml(gasto.gasto.toLocaleString("es-AR", { maximumFractionDigits: 0 }))}</span>
+              </li>
+            `
+          )
+          .join("")}
+      </ul>
+    </div>
+  `;
+}
+
+function renderPacking(packing) {
+  const progress = packing.progreso ?? {
+    total: 0,
+    completados: 0,
+    pendientes: 0,
+    porcentaje: 0
+  };
+  const items = Array.isArray(packing.items) ? packing.items.slice(0, 4) : [];
+
+  return `
+    <div class="dashboard-card-stack">
+      <div class="dashboard-card-head">
+        <div>
+          <h3>Progreso de equipaje</h3>
+          <p>${escapeHtml(progress.completados)} de ${escapeHtml(progress.total)} completados</p>
+        </div>
+        ${renderBadge(`${progress.porcentaje}%`, progress.porcentaje === 100 ? "positive" : "neutral")}
+      </div>
+      <div class="dashboard-progress" aria-label="Progreso del equipaje">
+        <span style="width: ${Math.max(0, Math.min(100, progress.porcentaje))}%"></span>
+      </div>
+      <ul class="dashboard-checklist">
+        ${items
+          .map(
+            (item) => `
+              <li>
+                <span class="dashboard-check ${item.completado ? "is-complete" : ""}"></span>
+                <strong>${escapeHtml(item.nombre)}</strong>
+              </li>
+            `
+          )
+          .join("")}
+      </ul>
+      <p class="dashboard-fineprint">${escapeHtml(progress.pendientes)} pendientes</p>
+    </div>
+  `;
+}
+
+function renderMemories(memories) {
+  const favoritos = memories.favoritos ?? [];
+  const notas = memories.notas ?? [];
+
+  return `
+    <div class="dashboard-card-stack">
+      <div class="dashboard-card-head">
+        <div>
+          <h3>Recuerdos destacados</h3>
+          <p>${escapeHtml(memories.totalFavoritos)} favoritos y ${escapeHtml(memories.totalNotas)} notas</p>
+        </div>
+        ${renderBadge("memorias", "neutral")}
+      </div>
+      <div class="dashboard-memory-grid">
+        <div class="dashboard-memory-column">
+          <h4>Favoritos</h4>
+          ${
+            favoritos.length === 0
+              ? renderEmptyState("Sin favoritos", "Marca lugares o actividades para verlos aquí.")
+              : `<ul class="dashboard-mini-list dashboard-mini-list--memory">
+                  ${favoritos
+                    .map(
+                      (item) => `
+                        <li>
+                          <strong>${escapeHtml(item.title)}</strong>
+                          <span>${escapeHtml(item.subtitle)}</span>
+                        </li>
+                      `
+                    )
+                    .join("")}
+                </ul>`
+          }
