+        <div class="dashboard-memory-column">
+          <h4>Notas</h4>
+          ${
+            notas.length === 0
+              ? renderEmptyState("Sin notas", "Guarda ideas y recordatorios del viaje para consultarlos después.")
+              : `<ul class="dashboard-mini-list dashboard-mini-list--memory">
+                  ${notas
+                    .map(
+                      (item) => `
+                        <li>
+                          <strong>${escapeHtml(item.title)}</strong>
+                          <span>${escapeHtml(item.subtitle)}</span>
+                        </li>
+                      `
+                    )
+                    .join("")}
+                </ul>`
+          }
+        </div>
+      </div>
+    </div>
+  `;
+}
+
+function renderDashboardHTML(model = buildDashboardModel()) {
+  const trip = model.trip ?? buildTripSummary([]);
+  const counts = model.counts ?? { paradas: 0, actividades: 0 };
+
+  return `
+    <div class="dashboard-shell">
+      <header class="dashboard-hero">
+        <div class="dashboard-hero-copy">
+          <p class="dashboard-label">itinerario, organización y recuerdos</p>
+          <h1>${escapeHtml(trip.title)}</h1>
+          <p class="dashboard-summary">Fechas del viaje: <strong>${escapeHtml(trip.dateRange)}</strong></p>
+          <p class="dashboard-route">${escapeHtml(trip.route)}</p>
+        </div>
+        <div class="dashboard-actions" aria-label="Acciones del dashboard">
+          <button type="button" class="dashboard-button" data-action="refresh">Actualizar panel</button>
+        </div>
+      </header>
+
+      <section class="dashboard-overview" aria-label="Resumen del viaje">
+        <article class="dashboard-metric">
+          <span>Paradas</span>
+          <strong>${escapeHtml(counts.paradas)}</strong>
+        </article>
+        <article class="dashboard-metric">
+          <span>Eventos</span>
+          <strong>${escapeHtml(counts.actividades)}</strong>
+        </article>
+        <article class="dashboard-metric">
+          <span>Presupuesto</span>
+          <strong>${escapeHtml(Number(model.budget?.total ?? 0).toLocaleString("es-AR", { maximumFractionDigits: 0 }))}</strong>
+        </article>
+        <article class="dashboard-metric">
+          <span>Equipaje</span>
+          <strong>${escapeHtml(model.packing?.progreso?.porcentaje ?? 0)}%</strong>
+        </article>
+      </section>
+
+      <section class="dashboard-grid" aria-label="Panel principal">
+        <article class="dashboard-panel dashboard-panel--events">
+          <div class="dashboard-panel-head">
+            <div>
+              <p class="dashboard-label">itinerario</p>
+              <h2>Próximos eventos</h2>
+            </div>
+          </div>
+          ${renderUpcomingEvents(model.upcomingEvents ?? [])}
+        </article>
+
+        <aside class="dashboard-sidebar" aria-label="Organización y recuerdos">
+          <section class="dashboard-panel">
+            <p class="dashboard-label">organización</p>
+            ${renderBudget(model.budget ?? buildBudgetSummary())}
+          </section>
+
+          <section class="dashboard-panel">
+            <p class="dashboard-label">organización</p>
+            ${renderPacking(model.packing ?? buildPackingSummary())}
+          </section>
+
+          <section class="dashboard-panel">
+            <p class="dashboard-label">recuerdos</p>
+            ${renderMemories(model.memories ?? buildMemoryHighlights())}
+          </section>
+        </aside>
+      </section>
+    </div>
+  `;
+}
+
+function bindRefresh(root, refresh) {
+  const button = root.querySelector('[data-action="refresh"]');
+  if (button) {
+    button.addEventListener("click", refresh);
+  }
+}
+
+function mountDashboard(root, options = {}) {
+  if (!root) {
+    throw new TypeError("root is required");
+  }
+
+  const { referenceDate = new Date() } = options;
+
+  function render() {
+    const model = buildDashboardModel(referenceDate);
+    root.innerHTML = renderDashboardHTML(model);
+    bindRefresh(root, render);
+  }
+
+  render();
+
+  const handleStorage = () => render();
+  globalThis.addEventListener?.("storage", handleStorage);
+
+  return {
+    refresh: render,
+    destroy() {
+      globalThis.removeEventListener?.("storage", handleStorage);
+      root.innerHTML = "";
+    }
+  };
+}
+
+export {
+  buildBudgetSummary,
+  buildDashboardModel,
+  buildMemoryHighlights,
+  buildPackingSummary,
+  buildUpcomingEvents,
+  buildTripSummary,
+  formatDateRange,
+  formatIsoDate,
+  mountDashboard,
+  renderDashboardHTML
+};
