+:root {
+  color-scheme: light;
+  --bg: #eef3f8;
+  --bg-soft: #f7f9fc;
+  --surface: #ffffff;
+  --surface-strong: #f0f5fa;
+  --text: #142033;
+  --muted: #5d6b82;
+  --border: #d7e0ea;
+  --accent: #0f766e;
+  --accent-strong: #0b5f58;
+  --accent-soft: rgba(15, 118, 110, 0.12);
+  --positive: #1f7a4d;
+  --warning: #9a6700;
+  --shadow: 0 8px 24px rgba(20, 32, 51, 0.08);
+  --radius: 18px;
