@@ -0,0 +1,459 @@
+:root {
+  color-scheme: light;
+  --bg: #eef3f8;
+  --bg-soft: #f7f9fc;
+  --surface: #ffffff;
+  --surface-strong: #f0f5fa;
+  --text: #142033;
+  --muted: #5d6b82;
+  --border: #d7e0ea;
+  --accent: #0f766e;
+  --accent-strong: #0b5f58;
+  --accent-soft: rgba(15, 118, 110, 0.12);
+  --positive: #1f7a4d;
+  --warning: #9a6700;
+  --shadow: 0 8px 24px rgba(20, 32, 51, 0.08);
+  --radius: 18px;
+  --radius-sm: 12px;
+  --radius-xs: 10px;
+  --focus: 0 0 0 3px rgba(15, 118, 110, 0.22);
+  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Aptos", "Helvetica Neue",
+    sans-serif;
+}
+
+*,
+*::before,
+*::after {
+  box-sizing: border-box;
+}
+
+html {
+  background: linear-gradient(180deg, #f7fbfe 0%, var(--bg) 100%);
+}
+
+body {
+  margin: 0;
+  min-height: 100dvh;
+  color: var(--text);
+  background:
+    radial-gradient(circle at top left, rgba(15, 118, 110, 0.08), transparent 24%),
+    radial-gradient(circle at top right, rgba(20, 32, 51, 0.04), transparent 18%),
+    linear-gradient(180deg, #fbfdff 0%, var(--bg) 100%);
+}
+
+button,
+input,
+select,
+textarea {
+  font: inherit;
+}
+
+button {
+  cursor: pointer;
+}
+
+button:focus-visible,
+a:focus-visible {
+  outline: none;
+  box-shadow: var(--focus);
+}
+
+.app-shell {
+  min-height: 100dvh;
+  padding: 32px;
+}
+
+.dashboard-shell {
+  max-width: 1360px;
+  margin: 0 auto;
+  display: grid;
+  gap: 24px;
+}
+
+.dashboard-hero {
+  display: flex;
+  justify-content: space-between;
+  gap: 24px;
+  align-items: start;
+  padding: 28px 30px;
+  background: linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(255, 255, 255, 0.9));
+  border: 1px solid var(--border);
+  border-radius: calc(var(--radius) + 4px);
+  box-shadow: var(--shadow);
+}
+
+.dashboard-hero-copy {
+  display: grid;
+  gap: 10px;
+  max-width: 54rem;
+}
+
+.dashboard-label {
+  margin: 0;
+  color: var(--accent);
+  font-size: 0.75rem;
+  font-weight: 700;
+  letter-spacing: 0.12em;
+  text-transform: uppercase;
+}
+
+.dashboard-hero h1,
+.dashboard-panel h2,
+.dashboard-card-head h3,
+.dashboard-memory-column h4 {
+  margin: 0;
+  line-height: 1.05;
+}
+
+.dashboard-hero h1 {
+  font-size: clamp(2.2rem, 4vw, 4.5rem);
+  letter-spacing: -0.05em;
+}
+
+.dashboard-summary,
+.dashboard-route,
+.dashboard-card-head p,
+.dashboard-fineprint,
+.dashboard-empty p,
+.dashboard-mini-list span,
+.dashboard-event p {
+  margin: 0;
+  color: var(--muted);
+}
+
+.dashboard-summary {
+  font-size: 1.05rem;
+}
+
+.dashboard-route {
+  font-size: 0.98rem;
+  font-weight: 600;
+  color: var(--text);
+}
+
+.dashboard-actions {
+  display: flex;
+  gap: 12px;
+  align-items: center;
+}
+
+.dashboard-button {
+  min-height: 44px;
+  padding: 0 16px;
+  border: 1px solid transparent;
+  border-radius: 999px;
+  color: #ffffff;
+  background: linear-gradient(180deg, var(--accent), var(--accent-strong));
+  box-shadow: 0 8px 18px rgba(15, 118, 110, 0.18);
+  font-weight: 700;
+}
+
+.dashboard-button:hover {
+  filter: brightness(1.02);
+}
+
+.dashboard-overview {
+  display: grid;
+  grid-template-columns: repeat(4, minmax(0, 1fr));
+  gap: 16px;
+}
+
+.dashboard-metric,
+.dashboard-panel {
+  background: rgba(255, 255, 255, 0.92);
+  border: 1px solid var(--border);
+  border-radius: var(--radius);
+  box-shadow: var(--shadow);
+}
+
+.dashboard-metric {
+  padding: 18px 20px;
+  display: grid;
+  gap: 8px;
+}
+
+.dashboard-metric span {
+  color: var(--muted);
+  font-size: 0.9rem;
+  font-weight: 600;
+}
+
+.dashboard-metric strong {
+  font-size: 1.75rem;
+  letter-spacing: -0.04em;
+}
+
+.dashboard-grid {
+  display: grid;
+  grid-template-columns: minmax(0, 1.5fr) minmax(320px, 0.95fr);
