      etiqueta: "Sobregasto",
      tono: "critico"
    };
  }

  if (total <= 0) {
    return {
      clave: ESTADOS_PRESUPUESTO.sin_presupuesto,
      etiqueta: "Sin presupuesto",
      tono: "neutral"
    };
  }

  if (disponible === 0) {
