    id: parada.id,
    nombre: parada.nombre,
    fechaInicio: parada.fechaInicio,
    fechaFin: parada.fechaFin,
    descripcion: parada.descripcion
  };
}

function isParada(value) {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

function normalizeParada(parada) {
  if (!isParada(parada)) {
    throw new TypeError("parada must be an object");
  }

  return {
    id: parada.id ?? createId(),
    nombre: parada.nombre ?? "",
    fechaInicio: parada.fechaInicio ?? "",
    fechaFin: parada.fechaFin ?? "",
    descripcion: parada.descripcion ?? ""
  };
}

function createId() {
  if (typeof crypto !== "undefined" && typeof crypto.randomUUID === "function") {
    return crypto.randomUUID();
  }

  return `parada-${Date.now()}-${Math.random().toString(16).slice(2)}`;
}

function readParadas() {
  const current = getStore().get();
  if (!Array.isArray(current)) {
    return [];
  }

  return current.filter(isParada).map(cloneParada);
}

function writeParadas(paradas) {
  getStore().set(paradas.map(cloneParada));
}

function resolveId(value) {
  if (isParada(value)) {
    return value.id;
  }

  return value;
}

function moveByIndex(paradas, fromIndex, toIndex) {
  if (!Number.isInteger(fromIndex) || !Number.isInteger(toIndex)) {
    return paradas;
  }

  if (fromIndex < 0 || fromIndex >= paradas.length) {
    return paradas;
  }

  const next = paradas.slice();
  const [item] = next.splice(fromIndex, 1);
  const targetIndex = Math.max(0, Math.min(toIndex, next.length));
  next.splice(targetIndex, 0, item);
  return next;
}

function reorderByIds(paradas, order) {
  const ids = order.map(resolveId).filter((id) => id !== undefined && id !== null);
  if (ids.length === 0) {
    return paradas;
  }

  const seen = new Set();
  const next = [];

  for (const id of ids) {
    if (seen.has(id)) {
      continue;
    }

    const found = paradas.find((parada) => parada.id === id);
    if (found) {
      next.push(found);
      seen.add(id);
    }
  }

  for (const parada of paradas) {
    if (!seen.has(parada.id)) {
      next.push(parada);
    }
  }

  return next;
}

export function listParadas() {
  return readParadas();
}

export function addParada(parada) {
  const nextParada = normalizeParada(parada);
  const paradas = readParadas();
  paradas.push(nextParada);
  writeParadas(paradas);
  return cloneParada(nextParada);
}

export function updateParada(paradaOrId, changes) {
  const update = isParada(paradaOrId)
    ? paradaOrId
    : { id: paradaOrId, ...(isParada(changes) ? changes : {}) };
  const id = update.id;

  if (id === undefined || id === null) {
    return undefined;
  }

  const paradas = readParadas();
  const index = paradas.findIndex((parada) => parada.id === id);
  if (index === -1) {
    return undefined;
  }

  const nextParada = {
    ...paradas[index],
    ...update,
    id
  };

  paradas[index] = nextParada;
  writeParadas(paradas);
  return cloneParada(nextParada);
}

export function removeParada(paradaOrId) {
  const id = resolveId(paradaOrId);
  if (id === undefined || id === null) {
    return undefined;
  }

  const paradas = readParadas();
  const index = paradas.findIndex((parada) => parada.id === id);
  if (index === -1) {
    return undefined;
  }

  const [removed] = paradas.splice(index, 1);
  writeParadas(paradas);
  return cloneParada(removed);
}

export function reorderParadas(firstArg, secondArg) {
  const paradas = readParadas();

  if (Array.isArray(firstArg)) {
    const next = reorderByIds(paradas, firstArg);
    writeParadas(next);
    return next.map(cloneParada);
  }

  if (isParada(firstArg) && Array.isArray(secondArg)) {
    const next = reorderByIds(paradas, secondArg);
    writeParadas(next);
    return next.map(cloneParada);
  }

