+test("readDashboardModel consumes the canonical stores", () => {
+  addParada({
+    id: "cordoba",
+    nombre: "Córdoba",
+    fechaInicio: "2026-09-07",
+    fechaFin: "2026-09-08",
+    descripcion: "Escala corta"
+  });
+  addActividad({
+    id: "cordoba-lunch",
+    fecha: "2026-09-07",
+    paradaId: "cordoba",
+    horario: "13:00",
+    estado: "pendiente"
+  });
+  guardarPresupuesto({
+    total: 100,
+    gastos: [{ categoria: "Comida", gasto: 45 }]
+  });
