+  border-radius: var(--radius-lg);
+  background: rgba(255, 255, 255, 0.56);
+  border: 1px solid rgba(19, 32, 51, 0.08);
+}
+
+.memory-column h3 {
+  margin-bottom: 12px;
+}
+
+.memory-row {
+  align-items: start;
+}
+
+.memory-row div {
+  gap: 2px;
+}
+
+.empty-state {
+  padding: 14px 0 2px;
+  font-size: 0.96rem;
+}
+
+.empty-state.compact {
