+}
+
+h2 {
+  font-size: clamp(1.35rem, 2.4vw, 2rem);
+  line-height: 1.05;
+  letter-spacing: -0.03em;
+}
+
+h3 {
+  font-size: 1rem;
+  line-height: 1.2;
+  letter-spacing: -0.02em;
+}
+
+p {
+  margin: 0;
+  line-height: 1.55;
+}
+
+.hero-summary {
+  max-width: 64ch;
+  margin-top: 18px;
+  font-size: 1.03rem;
+  color: var(--ink-soft);
+}
+
+.hero-ribbon {
+  display: grid;
+  grid-template-columns: 18px 1fr 18px 1fr 18px;
+  align-items: center;
+  gap: 12px;
+  max-width: 720px;
+  padding: 14px 18px;
+  border-radius: 999px;
+  background: rgba(16, 27, 47, 0.04);
+  border: 1px solid rgba(16, 27, 47, 0.08);
+}
+
+.ribbon-node {
+  width: 18px;
+  height: 18px;
+  border-radius: 50%;
+  background:
+    radial-gradient(circle at 30% 30%, #fff7e8 0%, #ffd6ba 36%, var(--accent) 100%);
+  box-shadow: 0 0 0 6px rgba(217, 109, 75, 0.12);
+}
+
+.ribbon-line {
+  height: 2px;
+  border-radius: 999px;
+  background: linear-gradient(90deg, rgba(19, 32, 51, 0.18), rgba(19, 32, 51, 0.08));
+}
+
+.hero-facts {
+  display: grid;
+  grid-template-columns: repeat(3, minmax(0, 1fr));
