+}
+
+.hero-facts div,
+.budget-facts div {
+  padding: 16px 18px;
+  border-radius: var(--radius-md);
+  background: rgba(255, 255, 255, 0.62);
+  border: 1px solid rgba(19, 32, 51, 0.08);
+}
+
+.hero-facts dt,
+.budget-facts dt {
+  margin-bottom: 6px;
+  font-size: 0.78rem;
+  font-weight: 700;
+  letter-spacing: 0.11em;
+  text-transform: uppercase;
+  color: var(--ink-soft);
+}
+
+.hero-facts dd,
+.budget-facts dd {
+  margin: 0;
+  font-size: 1.04rem;
+  font-weight: 700;
+  color: var(--ink);
+}
+
+.content-grid {
+  display: grid;
+  gap: 22px;
+  grid-template-columns: 1.15fr 0.95fr;
+}
+
+.panel {
+  border-radius: var(--radius-xl);
