+
+.panel-kicker {
+  display: inline-flex;
+  align-items: center;
+  min-height: 36px;
+  padding: 0 14px;
+  border-radius: 999px;
+  background: rgba(217, 109, 75, 0.12);
+  color: var(--accent);
+  font-size: 0.82rem;
+  font-weight: 700;
+  letter-spacing: 0.08em;
+  text-transform: uppercase;
+}
+
+.route-list,
+.stack-list,
+.chip-list {
+  list-style: none;
+  padding: 0;
+  margin: 0;
+}
+
+.route-list {
+  display: grid;
+  gap: 14px;
+  margin-bottom: 18px;
+}
+
+.route-item {
+  display: grid;
+  grid-template-columns: auto minmax(0, 1fr);
+  gap: 10px 14px;
+  padding: 16px;
+  border-radius: var(--radius-lg);
+  background: rgba(255, 255, 255, 0.64);
+  border: 1px solid rgba(19, 32, 51, 0.08);
+}
+
+.route-index {
+  grid-row: span 2;
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  width: 44px;
+  height: 44px;
+  border-radius: 14px;
+  background: linear-gradient(135deg, rgba(217, 109, 75, 0.18), rgba(74, 174, 162, 0.16));
+  border: 1px solid rgba(19, 32, 51, 0.1);
+  font-family: "SFMono-Regular", Consolas, "Liberation Mono", monospace;
+  font-size: 0.82rem;
+  font-weight: 700;
+  color: var(--ink);
+}
+
+.route-copy {
+  display: grid;
+  gap: 4px;
+}
+
+.route-copy strong,
+.stack-row strong {
+  font-size: 1.02rem;
+}
+
+.route-copy span,
+.route-item p,
+.stack-row span,
+.memory-row span,
+.budget-state,
+.empty-state,
+.luggage-summary span {
+  color: var(--ink-soft);
+}
+
+.route-item p {
+  grid-column: 2;
+  font-size: 0.96rem;
