+  justify-content: space-between;
+  gap: 14px;
+  align-items: baseline;
+}
+
+.luggage-summary strong {
+  font-size: 1.1rem;
+}
+
+.chip-list {
+  display: flex;
+  flex-wrap: wrap;
+  gap: 10px;
+}
+
+.chip {
