@@ -0,0 +1,192 @@
+import assert from "node:assert/strict";
+import test from "node:test";
+
+import { addActividad } from "../itinerary/agenda/agenda.mjs";
+import { addParada } from "../itinerary/paradas/paradas.mjs";
+import { crearChecklistEquipaje } from "../organizacion/equipaje/equipaje.mjs";
+import { guardarPresupuesto } from "../organizacion/presupuesto/presupuesto.mjs";
+import { createFavoritosStore } from "../recuerdos/favoritos/favoritos.mjs";
+import { guardarNota, limpiarNotas } from "../recuerdos/notas/notas.mjs";
+import { buildDashboardModel, mountDashboard, readDashboardModel, renderDashboard } from "./dashboard.mjs";
+
+class LocalStorageMock {
+  #map = new Map();
+
+  clear() {
+    this.#map.clear();
+  }
+
+  getItem(key) {
+    return this.#map.has(key) ? this.#map.get(key) : null;
+  }
+
+  setItem(key, value) {
+    this.#map.set(key, String(value));
+  }
+
+  removeItem(key) {
+    this.#map.delete(key);
+  }
+}
+
+test.beforeEach(() => {
+  globalThis.localStorage = new LocalStorageMock();
+  limpiarNotas();
+});
+
+test.afterEach(() => {
+  delete globalThis.localStorage;
+});
+
+test("buildDashboardModel compone itinerario, organización y recuerdos en una sola vista", () => {
+  const model = buildDashboardModel({
+    tripName: "Verano 2026",
+    paradas: [
+      {
+        id: "sevilla",
+        nombre: "Sevilla",
+        fechaInicio: "2026-09-04",
+        fechaFin: "2026-09-06",
+        descripcion: "Centro histórico"
+      },
+      {
+        id: "madrid",
+        nombre: "Madrid",
+        fechaInicio: "2026-09-01",
+        fechaFin: "2026-09-03",
+        descripcion: "Llegada y paseo"
+      }
+    ],
+    actividades: [
+      {
+        id: "madrid-desayuno",
+        fecha: "2026-09-02",
+        paradaId: "madrid",
+        horario: "08:30",
+        estado: "pendiente"
+      },
+      {
+        id: "sevilla-museo",
+        fecha: "2026-09-05",
+        paradaId: "sevilla",
+        horario: "11:00",
+        estado: "completada"
+      }
+    ],
+    presupuesto: {
+      total: 1000,
+      gastado: 620,
+      disponible: 380,
+      estadoVisual: { etiqueta: "En control" }
+    },
+    equipaje: {
+      items: [
+        { id: "a", nombre: "Pasaporte", completado: true },
+        { id: "b", nombre: "Cargador", completado: false }
+      ]
+    },
+    favoritos: [
+      { id: "museo", tipo: "lugar", nombre: "Museo de Arte" }
+    ],
+    notas: [
+      { id: "nota-1", texto: "Llevar abrigo", diaId: "dia-2026-09-02" }
+    ]
+  });
+
+  assert.deepEqual(model.tripRange, {
+    start: "2026-09-01",
+    end: "2026-09-06",
+    label: "1 sep 2026 al 6 sep 2026"
+  });
+  assert.deepEqual(model.upcomingEvents, [
+    {
+      id: "madrid-desayuno",
+      title: "08:30 · Madrid",
+      subtitle: "martes 2 sep 2026",
+      state: "Pendiente"
+    },
+    {
+      id: "sevilla-museo",
+      title: "11:00 · Sevilla",
+      subtitle: "viernes 5 sep 2026",
+      state: "Completada"
+    }
+  ]);
+  assert.equal(model.luggage.progress.porcentaje, 50);
+  assert.equal(model.memories.favoriteItems[0].label, "Museo de Arte");
+  assert.equal(model.memories.noteItems[0].meta, "Día dia-2026-09-02");
+});
+
+test("renderDashboard and mountDashboard output the full dashboard shell", () => {
+  const html = renderDashboard(
+    buildDashboardModel({
+      paradas: [
+        {
+          id: "madrid",
+          nombre: "Madrid",
+          fechaInicio: "2026-09-01",
+          fechaFin: "2026-09-03",
+          descripcion: "Llegada"
+        }
+      ],
+      actividades: [],
+      presupuesto: {
+        total: 500,
+        gastado: 150,
+        disponible: 350,
+        estadoVisual: { etiqueta: "En control" }
+      }
+    })
+  );
+
+  assert.match(html, /Dashboard del viaje/);
+  assert.match(html, /Itinerario/);
+  assert.match(html, /Organización/);
+  assert.match(html, /Recuerdos destacados/);
+
+  const root = { innerHTML: "" };
+  const model = mountDashboard(root, readDashboardModel());
+
+  assert.equal(root.innerHTML.includes("data-dashboard-view"), true);
+  assert.equal(model.tripName, "Viaje en Familia");
+});
+
+test("readDashboardModel consumes the canonical stores", () => {
+  addParada({
+    id: "cordoba",
+    nombre: "Córdoba",
+    fechaInicio: "2026-09-07",
+    fechaFin: "2026-09-08",
+    descripcion: "Escala corta"
+  });
+  addActividad({
+    id: "cordoba-lunch",
+    fecha: "2026-09-07",
+    paradaId: "cordoba",
+    horario: "13:00",
+    estado: "pendiente"
+  });
+  guardarPresupuesto({
+    total: 100,
+    gastos: [{ categoria: "Comida", gasto: 45 }]
+  });
+
+  const checklist = crearChecklistEquipaje();
+  checklist.agregarEquipaje("Mochila");
+  checklist.agregarEquipaje("Cargador");
+  checklist.completarEquipaje(checklist.get().items[0].id);
+
+  const favoritosStore = createFavoritosStore();
+  favoritosStore.marcarFavorito({ id: "plaza", tipo: "lugar", nombre: "Plaza" });
+  guardarNota({ id: "nota-1", texto: "Llevar agua", paradaId: "cordoba" });
+
+  const model = readDashboardModel();
+
+  assert.equal(model.paradas[0].nombre, "Córdoba");
+  assert.equal(model.upcomingEvents[0].title, "13:00 · Córdoba");
+  assert.equal(model.budget.total, 100);
+  assert.equal(model.luggage.progress.porcentaje, 50);
+  assert.equal(model.memories.favoriteItems[0].label, "Plaza");
+  assert.equal(model.memories.noteItems[0].meta, "Parada Córdoba");
+});
+

