+<!doctype html>
+<html lang="es">
+  <head>
+    <meta charset="utf-8" />
+    <meta name="viewport" content="width=device-width, initial-scale=1" />
+    <title>Viaje en Familia</title>
+    <meta
+      name="description"
+      content="Dashboard del viaje con itinerario, organización y recuerdos destacados."
+    />
+    <link rel="stylesheet" href="./styles.css" />
+    <script type="module" src="./main.mjs"></script>
+  </head>
+  <body>
+    <div class="page-frame">
+      <div class="page-glow page-glow-left" aria-hidden="true"></div>
+      <div class="page-glow page-glow-right" aria-hidden="true"></div>
