index 0000000000000000000000000000000000000000..fd577424386764c9bf7ea9dfdea3e5d14e852b92
--- /dev/null
+++ b/public/styles.css
@@ -0,0 +1,634 @@
+:root {
+  color-scheme: dark;
+  --bg: #0b1220;
+  --bg-soft: #101b2f;
+  --surface: rgba(243, 236, 224, 0.96);
+  --surface-strong: #fffaf2;
+  --surface-muted: #ece2d5;
+  --ink: #132033;
+  --ink-soft: #4a596c;
+  --line: rgba(19, 32, 51, 0.14);
+  --line-strong: rgba(19, 32, 51, 0.26);
+  --accent: #d96d4b;
+  --accent-2: #4aaea2;
+  --accent-3: #d7ab34;
+  --shadow: 0 32px 80px rgba(0, 0, 0, 0.34);
+  --radius-xl: 32px;
+  --radius-lg: 24px;
+  --radius-md: 18px;
+  --radius-sm: 12px;
+  --content-width: min(1180px, calc(100vw - 32px));
+}
+
+*,
+*::before,
+*::after {
+  box-sizing: border-box;
+}
+
+html {
+  min-height: 100%;
+  background:
+    radial-gradient(circle at top left, rgba(217, 109, 75, 0.22), transparent 28%),
+    radial-gradient(circle at top right, rgba(74, 174, 162, 0.22), transparent 24%),
+    linear-gradient(160deg, var(--bg) 0%, var(--bg-soft) 48%, #0e1627 100%);
+}
+
+body {
+  margin: 0;
+  min-height: 100vh;
+  color: var(--ink);
+  font-family:
+    "Inter",
+    "Aptos",
+    system-ui,
+    sans-serif;
+}
+
+button,
+input,
+textarea,
+select {
+  font: inherit;
+}
+
+a {
+  color: inherit;
+}
+
+.page-frame {
+  position: relative;
+  min-height: 100vh;
+  padding: 24px 0 40px;
+  overflow: hidden;
+}
+
+.page-glow {
+  position: absolute;
+  inset: auto;
+  width: 34rem;
+  height: 34rem;
+  border-radius: 50%;
+  filter: blur(22px);
+  pointer-events: none;
+  opacity: 0.65;
+}
+
+.page-glow-left {
+  top: -10rem;
+  left: -8rem;
+  background: radial-gradient(circle, rgba(217, 109, 75, 0.35), transparent 68%);
+}
+
+.page-glow-right {
+  right: -10rem;
+  bottom: -12rem;
+  background: radial-gradient(circle, rgba(74, 174, 162, 0.24), transparent 68%);
+}
+
+.app-shell {
+  position: relative;
+  width: var(--content-width);
+  margin: 0 auto;
+}
+
+.dashboard-shell {
+  display: grid;
+  gap: 22px;
+}
+
+.hero-card,
+.panel {
+  position: relative;
+  border: 1px solid rgba(255, 255, 255, 0.42);
+  background: linear-gradient(180deg, rgba(255, 250, 242, 0.98), rgba(245, 236, 223, 0.92));
+  box-shadow: var(--shadow);
+  backdrop-filter: blur(10px);
+}
+
+.hero-card {
+  overflow: hidden;
+  border-radius: var(--radius-xl);
+  padding: clamp(28px, 5vw, 40px);
+  display: grid;
+  gap: 24px;
+}
+
+.hero-card::after {
+  content: "";
+  position: absolute;
+  inset: auto -8% -28% auto;
+  width: 26rem;
+  height: 26rem;
+  background:
+    radial-gradient(circle, rgba(217, 109, 75, 0.24), transparent 60%),
+    radial-gradient(circle at 42% 36%, rgba(74, 174, 162, 0.18), transparent 46%);
+  transform: rotate(-12deg);
+  pointer-events: none;
+}
+
+.hero-copy,
+.hero-facts,
+.panel,
+.panel-heading,
+.organization-grid,
+.memory-grid {
+  position: relative;
+  z-index: 1;
+}
+
+.eyebrow {
+  margin: 0 0 10px;
+  letter-spacing: 0.2em;
+  text-transform: uppercase;
+  font-size: 0.76rem;
+  font-weight: 700;
+  color: var(--accent);
+}
+
+h1,
+h2,
+h3,
+strong {
+  margin: 0;
+  font-family:
+    "Iowan Old Style",
+    "Palatino Linotype",
+    "Book Antiqua",
+    Georgia,
+    serif;
+}
+
+h1 {
+  font-size: clamp(2.7rem, 7vw, 5.4rem);
+  line-height: 0.96;
+  letter-spacing: -0.05em;
+  max-width: 10ch;
+  color: var(--ink);
+}
+
+h2 {
+  font-size: clamp(1.35rem, 2.4vw, 2rem);
+  line-height: 1.05;
+  letter-spacing: -0.03em;
+}
+
+h3 {
+  font-size: 1rem;
+  line-height: 1.2;
+  letter-spacing: -0.02em;
+}
+
+p {
+  margin: 0;
+  line-height: 1.55;
+}
+
+.hero-summary {
+  max-width: 64ch;
+  margin-top: 18px;
+  font-size: 1.03rem;
+  color: var(--ink-soft);
+}
+
+.hero-ribbon {
+  display: grid;
+  grid-template-columns: 18px 1fr 18px 1fr 18px;
+  align-items: center;
+  gap: 12px;
+  max-width: 720px;
+  padding: 14px 18px;
+  border-radius: 999px;
+  background: rgba(16, 27, 47, 0.04);
+  border: 1px solid rgba(16, 27, 47, 0.08);
+}
+
+.ribbon-node {
+  width: 18px;
+  height: 18px;
+  border-radius: 50%;
+  background:
+    radial-gradient(circle at 30% 30%, #fff7e8 0%, #ffd6ba 36%, var(--accent) 100%);
+  box-shadow: 0 0 0 6px rgba(217, 109, 75, 0.12);
+}
+
+.ribbon-line {
+  height: 2px;
+  border-radius: 999px;
+  background: linear-gradient(90deg, rgba(19, 32, 51, 0.18), rgba(19, 32, 51, 0.08));
+}
+
+.hero-facts {
+  display: grid;
+  grid-template-columns: repeat(3, minmax(0, 1fr));
+  gap: 16px;
+}
+
+.hero-facts div,
+.budget-facts div {
+  padding: 16px 18px;
+  border-radius: var(--radius-md);
+  background: rgba(255, 255, 255, 0.62);
+  border: 1px solid rgba(19, 32, 51, 0.08);
+}
+
+.hero-facts dt,
+.budget-facts dt {
+  margin-bottom: 6px;
+  font-size: 0.78rem;
+  font-weight: 700;
+  letter-spacing: 0.11em;
+  text-transform: uppercase;
+  color: var(--ink-soft);
+}
+
+.hero-facts dd,
+.budget-facts dd {
+  margin: 0;
+  font-size: 1.04rem;
+  font-weight: 700;
+  color: var(--ink);
+}
+
+.content-grid {
+  display: grid;
+  gap: 22px;
+  grid-template-columns: 1.15fr 0.95fr;
+}
+
+.panel {
+  border-radius: var(--radius-xl);
+  padding: 24px;
+}
+
+.panel-route {
+  grid-row: span 2;
+}
+
+.panel-memories {
+  grid-column: 1 / -1;
+}
+
+.panel-heading {
+  display: flex;
+  justify-content: space-between;
+  align-items: end;
+  gap: 16px;
+  margin-bottom: 18px;
+}
+
+.panel-kicker {
+  display: inline-flex;
+  align-items: center;
+  min-height: 36px;
+  padding: 0 14px;
+  border-radius: 999px;
+  background: rgba(217, 109, 75, 0.12);
+  color: var(--accent);
+  font-size: 0.82rem;
+  font-weight: 700;
+  letter-spacing: 0.08em;
+  text-transform: uppercase;
+}
+
+.route-list,
+.stack-list,
+.chip-list {
+  list-style: none;
+  padding: 0;
+  margin: 0;
+}
+
+.route-list {
+  display: grid;
+  gap: 14px;
+  margin-bottom: 18px;
+}
+
+.route-item {
+  display: grid;
+  grid-template-columns: auto minmax(0, 1fr);
+  gap: 10px 14px;
+  padding: 16px;
+  border-radius: var(--radius-lg);
+  background: rgba(255, 255, 255, 0.64);
+  border: 1px solid rgba(19, 32, 51, 0.08);
+}
+
+.route-index {
+  grid-row: span 2;
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  width: 44px;
+  height: 44px;
+  border-radius: 14px;
+  background: linear-gradient(135deg, rgba(217, 109, 75, 0.18), rgba(74, 174, 162, 0.16));
+  border: 1px solid rgba(19, 32, 51, 0.1);
+  font-family: "SFMono-Regular", Consolas, "Liberation Mono", monospace;
+  font-size: 0.82rem;
+  font-weight: 700;
+  color: var(--ink);
+}
+
+.route-copy {
+  display: grid;
+  gap: 4px;
+}
+
+.route-copy strong,
+.stack-row strong {
+  font-size: 1.02rem;
+}
+
+.route-copy span,
+.route-item p,
+.stack-row span,
+.memory-row span,
+.budget-state,
+.empty-state,
+.luggage-summary span {
+  color: var(--ink-soft);
+}
+
+.route-item p {
+  grid-column: 2;
+  font-size: 0.96rem;
+}
+
+.stack-list {
+  display: grid;
+  gap: 12px;
+}
+
+.stack-list.tight {
+  gap: 10px;
+}
+
+.stack-row {
+  display: flex;
+  justify-content: space-between;
+  gap: 16px;
+  align-items: center;
+  padding: 14px 16px;
+  border-radius: var(--radius-md);
+  background: rgba(255, 255, 255, 0.58);
+  border: 1px solid rgba(19, 32, 51, 0.08);
+}
+
+.stack-row div {
+  display: grid;
+  gap: 4px;
+}
+
+.status-pill {
+  flex: none;
+  display: inline-flex;
+  align-items: center;
+  padding: 8px 12px;
+  border-radius: 999px;
+  background: rgba(74, 174, 162, 0.12);
+  color: #20645d;
+  font-size: 0.8rem;
+  font-weight: 700;
+}
+
+.organization-grid {
+  display: grid;
+  gap: 18px;
+}
+
+.organization-grid section {
+  padding: 18px;
+  border-radius: var(--radius-lg);
+  background: rgba(255, 255, 255, 0.52);
+  border: 1px solid rgba(19, 32, 51, 0.08);
+}
+
+.budget-meter,
+.luggage-panel {
+  display: grid;
+  gap: 14px;
+  margin-top: 14px;
+}
+
+.meter-rail {
+  position: relative;
+  height: 14px;
+  border-radius: 999px;
+  background: rgba(19, 32, 51, 0.08);
+  overflow: hidden;
+}
+
+.meter-fill {
+  position: absolute;
+  inset: 0 auto 0 0;
+  border-radius: inherit;
+  background: linear-gradient(90deg, var(--accent), var(--accent-3));
+}
+
+.luggage-rail {
+  height: 12px;
+}
+
+.luggage-fill {
+  background: linear-gradient(90deg, var(--accent-2), #78d4c8);
+}
+
+.budget-facts {
+  display: grid;
+  grid-template-columns: repeat(3, minmax(0, 1fr));
+  gap: 10px;
+  margin: 0;
+}
+
+.budget-state {
+  font-size: 0.93rem;
+  font-weight: 700;
+}
+
+.luggage-summary {
+  display: flex;
+  justify-content: space-between;
+  gap: 14px;
+  align-items: baseline;
+}
+
+.luggage-summary strong {
+  font-size: 1.1rem;
+}
+
+.chip-list {
+  display: flex;
+  flex-wrap: wrap;
+  gap: 10px;
+}
+
+.chip {
+  display: inline-flex;
+  align-items: center;
+  min-height: 38px;
+  padding: 0 14px;
+  border-radius: 999px;
+  background: rgba(19, 32, 51, 0.05);
+  border: 1px solid rgba(19, 32, 51, 0.08);
+  font-size: 0.92rem;
+  color: var(--ink);
+}
+
+.chip-done {
+  background: rgba(74, 174, 162, 0.12);
+  border-color: rgba(74, 174, 162, 0.24);
+}
+
+.memory-grid {
+  display: grid;
+  grid-template-columns: repeat(2, minmax(0, 1fr));
+  gap: 18px;
+}
+
+.memory-column {
+  padding: 18px;
+  border-radius: var(--radius-lg);
+  background: rgba(255, 255, 255, 0.56);
+  border: 1px solid rgba(19, 32, 51, 0.08);
+}
+
+.memory-column h3 {
+  margin-bottom: 12px;
+}
+
+.memory-row {
+  align-items: start;
+}
+
+.memory-row div {
+  gap: 2px;
+}
+
+.empty-state {
+  padding: 14px 0 2px;
+  font-size: 0.96rem;
+}
+
+.empty-state.compact {
+  padding-top: 8px;
+}
+
+:focus-visible {
+  outline: 3px solid rgba(74, 174, 162, 0.9);
+  outline-offset: 4px;
+}
+
+@media (max-width: 960px) {
+  .content-grid {
+    grid-template-columns: 1fr;
+  }
+
+  .panel-route,
+  .panel-memories {
+    grid-column: auto;
+    grid-row: auto;
+  }
+
+  .memory-grid,
+  .hero-facts,
+  .budget-facts {
+    grid-template-columns: 1fr;
+  }
+}
+
+@media (max-width: 640px) {
+  .page-frame {
+    padding: 12px 0 24px;
+  }
+
+  .app-shell {
+    width: min(100vw - 20px, 100%);
+  }
+
+  .hero-card,
+  .panel {
+    border-radius: 24px;
+  }
+
+  .hero-ribbon {
+    grid-template-columns: 18px 1fr 18px;
+  }
+
+  .hero-ribbon .ribbon-line:last-of-type {
+    display: none;
+  }
+
+  .panel-heading,
+  .luggage-summary,
+  .stack-row {
+    flex-direction: column;
+    align-items: start;
+  }
+
+  .route-item {
+    grid-template-columns: 1fr;
+  }
+
+  .route-index,
+  .route-item p {
+    grid-column: auto;
+    grid-row: auto;
+  }
+}
+
+@media (prefers-reduced-motion: no-preference) {
+  .hero-card,
+  .panel {
+    animation: rise 420ms ease-out both;
+  }
+
+  .panel:nth-of-type(2) {
+    animation-delay: 80ms;
+  }
+
+  .panel:nth-of-type(3) {
+    animation-delay: 140ms;
+  }
+
+  .page-glow-left {
+    animation: driftLeft 16s ease-in-out infinite alternate;
+  }
+
+  .page-glow-right {
+    animation: driftRight 18s ease-in-out infinite alternate;
+  }
+}
+
+@keyframes rise {
+  from {
+    opacity: 0;
+    transform: translateY(12px);
+  }
+
+  to {
+    opacity: 1;
+    transform: translateY(0);
+  }
+}
+
+@keyframes driftLeft {
+  from {
+    transform: translate3d(0, 0, 0) scale(1);
+  }
+
+  to {
+    transform: translate3d(24px, 16px, 0) scale(1.04);
+  }
+}
+
+@keyframes driftRight {
+  from {
+    transform: translate3d(0, 0, 0) scale(1);
+  }
+
+  to {
+    transform: translate3d(-20px, -10px, 0) scale(1.03);
+  }
+}
diff --git a/src/dashboard/dashboard.mjs b/src/dashboard/dashboard.mjs
