index 0000000000000000000000000000000000000000..1cf894c9ffa558b36e4b5573ac884ba49b7dbdb8
--- /dev/null
+++ b/src/dashboard/dashboard.mjs
@@ -0,0 +1,524 @@
+import { listParadas } from "../itinerary/paradas/paradas.mjs";
+import { listActividades } from "../itinerary/agenda/agenda.mjs";
+import { obtenerPresupuestoGuardado } from "../organizacion/presupuesto/presupuesto.mjs";
+import { resumirPresupuesto } from "../organizacion/presupuesto/presupuesto.mjs";
+import { crearChecklistEquipaje } from "../organizacion/equipaje/equipaje.mjs";
+import { createFavoritosStore } from "../recuerdos/favoritos/favoritos.mjs";
+import { listarNotas } from "../recuerdos/notas/notas.mjs";
+
+const DISPLAY_MONTHS = [
+  "ene",
+  "feb",
+  "mar",
+  "abr",
+  "may",
+  "jun",
+  "jul",
+  "ago",
+  "sep",
+  "oct",
+  "nov",
+  "dic"
+];
+
+const DISPLAY_WEEKDAYS = [
+  "domingo",
+  "lunes",
+  "martes",
+  "miércoles",
+  "jueves",
+  "viernes",
+  "sábado"
+];
+
+function toStringValue(value) {
+  return value === undefined || value === null ? "" : String(value).trim();
+}
+
+function isValidDate(value) {
+  return value instanceof Date && !Number.isNaN(value.getTime());
+}
+
+function parseDate(value) {
+  if (value instanceof Date) {
+    return isValidDate(value) ? value : null;
+  }
+
+  const texto = toStringValue(value);
+  if (!texto) {
+    return null;
+  }
+
+  const parsed = new Date(`${texto}T00:00:00`);
+  return isValidDate(parsed) ? parsed : null;
+}
+
+function parseDateTime(fecha, horario) {
+  const day = toStringValue(fecha);
+  if (!day) {
+    return null;
+  }
+
+  const time = toStringValue(horario) || "00:00";
+  const parsed = new Date(`${day}T${time}`);
+  return isValidDate(parsed) ? parsed : parseDate(day);
+}
+
+function formatDate(value) {
+  const parsed = parseDate(value);
+  if (!parsed) {
+    return "";
+  }
+
+  return `${parsed.getDate()} ${DISPLAY_MONTHS[parsed.getMonth()]} ${parsed.getFullYear()}`;
+}
+
+function formatDayLabel(value) {
+  const parsed = parseDate(value);
+  if (!parsed) {
+    return "";
+  }
+
+  return DISPLAY_WEEKDAYS[parsed.getDay()];
+}
+
+function formatDateRange(start, end) {
+  const inicio = formatDate(start);
+  const fin = formatDate(end);
+
+  if (!inicio && !fin) {
+    return "Fechas por definir";
+  }
+
+  if (inicio && fin && inicio === fin) {
+    return inicio;
+  }
+
+  if (inicio && fin) {
+    return `${inicio} al ${fin}`;
+  }
+
+  return inicio || fin;
+}
+
+function sortByDateTime(a, b) {
+  const left = parseDateTime(a.fecha, a.horario)?.getTime() ?? Number.POSITIVE_INFINITY;
+  const right = parseDateTime(b.fecha, b.horario)?.getTime() ?? Number.POSITIVE_INFINITY;
+
+  if (left !== right) {
+    return left - right;
+  }
+
+  return toStringValue(a.horario).localeCompare(toStringValue(b.horario));
+}
+
+function getParadaNameById(paradas, paradaId) {
+  const found = paradas.find((parada) => parada.id === paradaId);
+  return toStringValue(found?.nombre) || "Sin parada";
+}
+
+function clampPercent(value) {
+  const numeric = Number(value);
+  if (!Number.isFinite(numeric)) {
+    return 0;
+  }
+
+  return Math.max(0, Math.min(100, numeric));
+}
+
+function buildTripRange(paradas) {
+  const fechasInicio = paradas.map((parada) => parseDate(parada.fechaInicio)).filter(Boolean);
+  const fechasFin = paradas.map((parada) => parseDate(parada.fechaFin ?? parada.fechaInicio)).filter(Boolean);
+
+  if (fechasInicio.length === 0 && fechasFin.length === 0) {
+    return {
+      start: "",
+      end: "",
+      label: "Fechas por definir"
+    };
+  }
+
+  const sortedStart = fechasInicio.sort((a, b) => a - b);
+  const sortedEnd = fechasFin.sort((a, b) => a - b);
+  const start = sortedStart[0] ?? sortedEnd[0];
+  const end = sortedEnd[sortedEnd.length - 1] ?? sortedStart[sortedStart.length - 1];
+
+  return {
+    start: start ? start.toISOString().slice(0, 10) : "",
+    end: end ? end.toISOString().slice(0, 10) : "",
+    label: formatDateRange(start, end)
+  };
+}
+
+function buildUpcomingEvents(actividades, paradas, limit = 5) {
+  return actividades
+    .slice()
+    .sort(sortByDateTime)
+    .slice(0, limit)
+    .map((actividad) => ({
+      id: actividad.id,
+      title: `${toStringValue(actividad.horario) || "Sin horario"} · ${getParadaNameById(paradas, actividad.paradaId)}`,
+      subtitle: `${formatDayLabel(actividad.fecha)} ${formatDate(actividad.fecha)}`.trim(),
+      state: actividad.estado === "completada" ? "Completada" : "Pendiente"
+    }));
+}
+
+function buildMemories(favoritos, notas, paradas) {
+  const favoriteItems = favoritos.slice(0, 4).map((favorito) => ({
+    id: `fav-${toStringValue(favorito.id)}`,
+    label: toStringValue(favorito.nombre) || "Sin nombre",
+    meta: toStringValue(favorito.tipo) || "favorito"
+  }));
+
+  const noteItems = notas.slice(0, 4).map((nota) => {
+    const association = toStringValue(nota.diaId || nota.paradaId);
+    const reference = nota.diaId
+      ? `Día ${association}`
+      : `Parada ${getParadaNameById(paradas, association)}`;
+
+    return {
+      id: `note-${toStringValue(nota.id)}`,
+      label: toStringValue(nota.texto) || "Sin texto",
+      meta: reference
+    };
+  });
+
+  return {
+    favoriteItems,
+    noteItems
+  };
+}
+
+export function buildDashboardModel({
+  tripName = "Viaje en Familia",
+  paradas = [],
+  actividades = [],
+  presupuesto = {},
+  equipaje = {},
+  favoritos = [],
+  notas = []
+} = {}) {
+  const safeParadas = Array.isArray(paradas) ? paradas.filter(Boolean) : [];
+  const safeActividades = Array.isArray(actividades) ? actividades.filter(Boolean) : [];
+  const safeFavoritos = Array.isArray(favoritos) ? favoritos.filter(Boolean) : [];
+  const safeNotas = Array.isArray(notas) ? notas.filter(Boolean) : [];
+  const tripRange = buildTripRange(safeParadas);
+  const budget =
+    presupuesto && typeof presupuesto === "object" && "estadoVisual" in presupuesto
+      ? presupuesto
+      : resumirPresupuesto(presupuesto);
+  const luggageItems = Array.isArray(equipaje?.items) ? equipaje.items.filter(Boolean) : [];
+  const luggageProgress = {
+    total: luggageItems.length,
+    completados: luggageItems.filter((item) => Boolean(item.completado)).length,
+    pendientes: luggageItems.filter((item) => !item.completado).length,
+    porcentaje: luggageItems.length === 0 ? 0 : Math.round((luggageItems.filter((item) => item.completado).length / luggageItems.length) * 100)
+  };
+
+  return {
+    tripName,
+    tripRange,
+    paradas: safeParadas.slice().sort((a, b) => {
+      const left = parseDate(a.fechaInicio)?.getTime() ?? Number.POSITIVE_INFINITY;
+      const right = parseDate(b.fechaInicio)?.getTime() ?? Number.POSITIVE_INFINITY;
+      return left - right;
+    }),
+    upcomingEvents: buildUpcomingEvents(safeActividades, safeParadas),
+    budget,
+    luggage: {
+      items: luggageItems,
+      progress: luggageProgress
+    },
+    memories: buildMemories(safeFavoritos, safeNotas, safeParadas)
+  };
+}
+
+export function readDashboardModel() {
+  const checklist = crearChecklistEquipaje();
+  const favoritosStore = createFavoritosStore();
+
+  return buildDashboardModel({
+    paradas: listParadas(),
+    actividades: listActividades(),
+    presupuesto: obtenerPresupuestoGuardado(),
+    equipaje: checklist.get(),
+    favoritos: favoritosStore.listarFavoritos(),
+    notas: listarNotas()
+  });
+}
+
+function escapeHtml(value) {
+  return toStringValue(value)
+    .replaceAll("&", "&amp;")
+    .replaceAll("<", "&lt;")
+    .replaceAll(">", "&gt;")
+    .replaceAll('"', "&quot;");
+}
+
+function renderParadas(paradas) {
+  if (paradas.length === 0) {
+    return `<p class="empty-state">Aún no hay paradas cargadas.</p>`;
+  }
+
+  return `
+    <ol class="route-list">
+      ${paradas
+        .map(
+          (parada, index) => `
+            <li class="route-item">
+              <span class="route-index">${String(index + 1).padStart(2, "0")}</span>
+              <div class="route-copy">
+                <strong>${escapeHtml(parada.nombre)}</strong>
+                <span>${escapeHtml(formatDateRange(parada.fechaInicio, parada.fechaFin))}</span>
+              </div>
+              <p>${escapeHtml(parada.descripcion)}</p>
+            </li>`
+        )
+        .join("")}
+    </ol>
+  `;
+}
+
+function renderEvents(upcomingEvents) {
+  if (upcomingEvents.length === 0) {
+    return `<p class="empty-state">No hay eventos próximos programados.</p>`;
+  }
+
+  return `
+    <ul class="stack-list">
+      ${upcomingEvents
+        .map(
+          (event) => `
+            <li class="stack-row">
+              <div>
+                <strong>${escapeHtml(event.title)}</strong>
+                <span>${escapeHtml(event.subtitle)}</span>
+              </div>
+              <span class="status-pill">${escapeHtml(event.state)}</span>
+            </li>`
+        )
+        .join("")}
+    </ul>
+  `;
+}
+
+function renderBudget(budget) {
+  const total = Number(budget?.total ?? 0);
+  const gastado = Number(budget?.gastado ?? 0);
+  const disponible = Number(budget?.disponible ?? total - gastado);
+  const percentage = total > 0 ? clampPercent((gastado / total) * 100) : 0;
+  const stateLabel = toStringValue(budget?.estadoVisual?.etiqueta) || "Sin presupuesto";
+
+  return `
+    <div class="budget-meter" aria-label="Resumen del presupuesto">
+      <div class="meter-rail">
+        <span class="meter-fill" style="width: ${percentage}%"></span>
+      </div>
+      <dl class="budget-facts">
+        <div>
+          <dt>Total</dt>
+          <dd>$${total.toLocaleString("es-AR")}</dd>
+        </div>
+        <div>
+          <dt>Gastado</dt>
+          <dd>$${gastado.toLocaleString("es-AR")}</dd>
+        </div>
+        <div>
+          <dt>Disponible</dt>
+          <dd>$${disponible.toLocaleString("es-AR")}</dd>
+        </div>
+      </dl>
+      <p class="budget-state">${escapeHtml(stateLabel)}</p>
+    </div>
+  `;
+}
+
+function renderLuggage(luggage) {
+  const progress = luggage?.progress ?? {
+    total: 0,
+    completados: 0,
+    pendientes: 0,
+    porcentaje: 0
+  };
+  const items = Array.isArray(luggage?.items) ? luggage.items : [];
+
+  return `
+    <div class="luggage-panel">
+      <div class="luggage-summary">
+        <strong>${progress.porcentaje}% listo</strong>
+        <span>${progress.completados}/${progress.total} items completados</span>
+      </div>
+      <div class="meter-rail luggage-rail">
+        <span class="meter-fill luggage-fill" style="width: ${progress.porcentaje}%"></span>
+      </div>
+      ${items.length === 0
+        ? `<p class="empty-state compact">La lista de equipaje todavía está vacía.</p>`
+        : `
+          <ul class="chip-list">
+            ${items
+              .slice(0, 6)
+              .map(
+                (item) => `
+                  <li class="chip ${item.completado ? "chip-done" : ""}">
+                    ${escapeHtml(item.nombre)}
+                  </li>`
+              )
+              .join("")}
+          </ul>`}
+    </div>
+  `;
+}
+
+function renderMemories(memories) {
+  const favoriteItems = memories?.favoriteItems ?? [];
+  const noteItems = memories?.noteItems ?? [];
+
+  return `
+    <div class="memory-grid">
+      <section class="memory-column">
+        <h3>Favoritos</h3>
+        ${
+          favoriteItems.length === 0
+            ? `<p class="empty-state compact">No hay recuerdos favoritos guardados.</p>`
+            : `
+              <ul class="stack-list tight">
+                ${favoriteItems
+                  .map(
+                    (item) => `
+                      <li class="stack-row memory-row">
+                        <div>
+                          <strong>${escapeHtml(item.label)}</strong>
+                          <span>${escapeHtml(item.meta)}</span>
+                        </div>
+                      </li>`
+                  )
+                  .join("")}
+              </ul>`
+        }
+      </section>
+      <section class="memory-column">
+        <h3>Notas</h3>
+        ${
+          noteItems.length === 0
+            ? `<p class="empty-state compact">No hay notas destacadas para este viaje.</p>`
+            : `
+              <ul class="stack-list tight">
+                ${noteItems
+                  .map(
+                    (item) => `
+                      <li class="stack-row memory-row">
+                        <div>
+                          <strong>${escapeHtml(item.label)}</strong>
+                          <span>${escapeHtml(item.meta)}</span>
+                        </div>
+                      </li>`
+                  )
+                  .join("")}
+              </ul>`
+        }
+      </section>
+    </div>
+  `;
+}
+
+export function renderDashboard(model = readDashboardModel()) {
+  return `
+    <main class="dashboard-shell" data-dashboard-view>
+      <section class="hero-card">
+        <div class="hero-copy">
+          <p class="eyebrow">Dashboard del viaje</p>
+          <h1>${escapeHtml(model.tripName)}</h1>
+          <p class="hero-summary">
+            ${escapeHtml(model.tripRange.label)}.
+            ${escapeHtml(String(model.paradas.length))} paradas, ${escapeHtml(String(model.upcomingEvents.length))} eventos próximos y una vista unificada de itinerario, organización y recuerdos.
+          </p>
+        </div>
+        <div class="hero-ribbon" aria-hidden="true">
+          <span class="ribbon-node"></span>
+          <span class="ribbon-line"></span>
+          <span class="ribbon-node"></span>
+          <span class="ribbon-line"></span>
+          <span class="ribbon-node"></span>
+        </div>
+        <dl class="hero-facts">
+          <div>
+            <dt>Inicio</dt>
+            <dd>${escapeHtml(formatDate(model.tripRange.start) || "Pendiente")}</dd>
+          </div>
+          <div>
+            <dt>Fin</dt>
+            <dd>${escapeHtml(formatDate(model.tripRange.end) || "Pendiente")}</dd>
+          </div>
+          <div>
+            <dt>Eventos</dt>
+            <dd>${escapeHtml(String(model.upcomingEvents.length))}</dd>
+          </div>
+        </dl>
+      </section>
+
+      <section class="content-grid">
+        <article class="panel panel-route">
+          <div class="panel-heading">
+            <div>
+              <p class="eyebrow">Itinerario</p>
+              <h2>Paradas y próximos eventos</h2>
+            </div>
+            <span class="panel-kicker">Ruta activa</span>
+          </div>
+          ${renderParadas(model.paradas)}
+          ${renderEvents(model.upcomingEvents)}
+        </article>
+
+        <article class="panel panel-organization">
+          <div class="panel-heading">
+            <div>
+              <p class="eyebrow">Organización</p>
+              <h2>Presupuesto y equipaje</h2>
+            </div>
+            <span class="panel-kicker">Control visible</span>
+          </div>
+          <div class="organization-grid">
+            <section>
+              <h3>Resumen de presupuesto</h3>
+              ${renderBudget(model.budget)}
+            </section>
+            <section>
+              <h3>Progreso de equipaje</h3>
+              ${renderLuggage(model.luggage)}
+            </section>
+          </div>
+        </article>
+
+        <article class="panel panel-memories">
+          <div class="panel-heading">
+            <div>
+              <p class="eyebrow">Recuerdos</p>
+              <h2>Recuerdos destacados</h2>
+            </div>
+            <span class="panel-kicker">Memoria viva</span>
+          </div>
+          ${renderMemories(model.memories)}
+        </article>
+      </section>
+    </main>
+  `;
+}
+
+export function mountDashboard(root, model = readDashboardModel()) {
+  if (!root) {
+    return null;
+  }
+
+  root.innerHTML = renderDashboard(model);
+  return model;
+}
+
+export function startDashboard(root = globalThis.document?.querySelector("[data-dashboard-root]")) {
+  if (!root) {
+    return null;
+  }
+
+  const model = readDashboardModel();
+  mountDashboard(root, model);
+  return model;
+}
