+:root {
+  color-scheme: dark;
+  --bg: #0b1220;
+  --bg-soft: #101b2f;
+  --surface: rgba(243, 236, 224, 0.96);
+  --surface-strong: #fffaf2;
+  --surface-muted: #ece2d5;
+  --ink: #132033;
+  --ink-soft: #4a596c;
+  --line: rgba(19, 32, 51, 0.14);
+  --line-strong: rgba(19, 32, 51, 0.26);
+  --accent: #d96d4b;
+  --accent-2: #4aaea2;
+  --accent-3: #d7ab34;
+  --shadow: 0 32px 80px rgba(0, 0, 0, 0.34);
+  --radius-xl: 32px;
+  --radius-lg: 24px;
+  --radius-md: 18px;
+  --radius-sm: 12px;
+  --content-width: min(1180px, calc(100vw - 32px));
+}
+
+*,
+*::before,
+*::after {
+  box-sizing: border-box;
+}
+
+html {
+  min-height: 100%;
+  background:
+    radial-gradient(circle at top left, rgba(217, 109, 75, 0.22), transparent 28%),
+    radial-gradient(circle at top right, rgba(74, 174, 162, 0.22), transparent 24%),
+    linear-gradient(160deg, var(--bg) 0%, var(--bg-soft) 48%, #0e1627 100%);
+}
+
+body {
+  margin: 0;
+  min-height: 100vh;
+  color: var(--ink);
+  font-family:
+    "Inter",
+    "Aptos",
+    system-ui,
+    sans-serif;
+}
+
+button,
+input,
+textarea,
+select {
+  font: inherit;
+}
+
+a {
+  color: inherit;
+}
+
+.page-frame {
+  position: relative;
+  min-height: 100vh;
+  padding: 24px 0 40px;
+  overflow: hidden;
+}
+
+.page-glow {
+  position: absolute;
+  inset: auto;
+  width: 34rem;
+  height: 34rem;
+  border-radius: 50%;
+  filter: blur(22px);
+  pointer-events: none;
+  opacity: 0.65;
+}
+
+.page-glow-left {
+  top: -10rem;
+  left: -8rem;
+  background: radial-gradient(circle, rgba(217, 109, 75, 0.35), transparent 68%);
+}
+
+.page-glow-right {
+  right: -10rem;
+  bottom: -12rem;
+  background: radial-gradient(circle, rgba(74, 174, 162, 0.24), transparent 68%);
+}
+
+.app-shell {
+  position: relative;
+  width: var(--content-width);
+  margin: 0 auto;
+}
+
+.dashboard-shell {
+  display: grid;
+  gap: 22px;
+}
+
+.hero-card,
+.panel {
+  position: relative;
+  border: 1px solid rgba(255, 255, 255, 0.42);
+  background: linear-gradient(180deg, rgba(255, 250, 242, 0.98), rgba(245, 236, 223, 0.92));
+  box-shadow: var(--shadow);
+  backdrop-filter: blur(10px);
+}
+
+.hero-card {
+  overflow: hidden;
+  border-radius: var(--radius-xl);
+  padding: clamp(28px, 5vw, 40px);
+  display: grid;
+  gap: 24px;
+}
+
+.hero-card::after {
+  content: "";
+  position: absolute;
+  inset: auto -8% -28% auto;
+  width: 26rem;
+  height: 26rem;
+  background:
+    radial-gradient(circle, rgba(217, 109, 75, 0.24), transparent 60%),
+    radial-gradient(circle at 42% 36%, rgba(74, 174, 162, 0.18), transparent 46%);
+  transform: rotate(-12deg);
+  pointer-events: none;
+}
+
+.hero-copy,
+.hero-facts,
+.panel,
+.panel-heading,
+.organization-grid,
+.memory-grid {
+  position: relative;
+  z-index: 1;
+}
+
+.eyebrow {
+  margin: 0 0 10px;
+  letter-spacing: 0.2em;
+  text-transform: uppercase;
+  font-size: 0.76rem;
+  font-weight: 700;
+  color: var(--accent);
+}
+
+h1,
+h2,
+h3,
+strong {
+  margin: 0;
+  font-family:
+    "Iowan Old Style",
+    "Palatino Linotype",
+    "Book Antiqua",
+    Georgia,
+    serif;
+}
+
+h1 {
+  font-size: clamp(2.7rem, 7vw, 5.4rem);
+  line-height: 0.96;
+  letter-spacing: -0.05em;
+  max-width: 10ch;
+  color: var(--ink);
+}
+
+h2 {
+  font-size: clamp(1.35rem, 2.4vw, 2rem);
+  line-height: 1.05;
+  letter-spacing: -0.03em;
+}
+
+h3 {
+  font-size: 1rem;
+  line-height: 1.2;
+  letter-spacing: -0.02em;
+}
+
+p {
+  margin: 0;
+  line-height: 1.55;
+}
+
+.hero-summary {
+  max-width: 64ch;
+  margin-top: 18px;
+  font-size: 1.03rem;
+  color: var(--ink-soft);
+}
+
+.hero-ribbon {
+  display: grid;
+  grid-template-columns: 18px 1fr 18px 1fr 18px;
+  align-items: center;
+  gap: 12px;
+  max-width: 720px;
+  padding: 14px 18px;
+  border-radius: 999px;
+  background: rgba(16, 27, 47, 0.04);
+  border: 1px solid rgba(16, 27, 47, 0.08);
+}
+
+.ribbon-node {
+  width: 18px;
+  height: 18px;
+  border-radius: 50%;
+  background:
+    radial-gradient(circle at 30% 30%, #fff7e8 0%, #ffd6ba 36%, var(--accent) 100%);
+  box-shadow: 0 0 0 6px rgba(217, 109, 75, 0.12);
+}
+
+.ribbon-line {
+  height: 2px;
+  border-radius: 999px;
+  background: linear-gradient(90deg, rgba(19, 32, 51, 0.18), rgba(19, 32, 51, 0.08));
+}
+
+.hero-facts {
+  display: grid;
+  grid-template-columns: repeat(3, minmax(0, 1fr));
+  gap: 16px;
+}
+
+.hero-facts div,
+.budget-facts div {
+  padding: 16px 18px;
+  border-radius: var(--radius-md);
+  background: rgba(255, 255, 255, 0.62);
+  border: 1px solid rgba(19, 32, 51, 0.08);
+}
+
+.hero-facts dt,
+.budget-facts dt {
+  margin-bottom: 6px;
+  font-size: 0.78rem;
+  font-weight: 700;
+  letter-spacing: 0.11em;
+  text-transform: uppercase;
+  color: var(--ink-soft);
+}
+
+.hero-facts dd,
+.budget-facts dd {
+  margin: 0;
+  font-size: 1.04rem;
+  font-weight: 700;
