+  outline-offset: 4px;
+}
+
+@media (max-width: 960px) {
+  .content-grid {
+    grid-template-columns: 1fr;
+  }
+
+  .panel-route,
+  .panel-memories {
+    grid-column: auto;
+    grid-row: auto;
+  }
+
+  .memory-grid,
+  .hero-facts,
+  .budget-facts {
