+import assert from "node:assert/strict";
+import test from "node:test";
+
+import { createStore } from "../../src/storage/storage.mjs";
+import { addActividad, listActividades } from "../../src/itinerary/agenda/agenda.mjs";
+import { addParada, listParadas, reorderParadas } from "../../src/itinerary/paradas/paradas.mjs";
+import {
+  buscarActividades,
+  buscarParadas,
+  explorarActividades,
+  explorarParadas
+} from "../../src/itinerary/exploracion/exploracion.mjs";
+import { crearChecklistEquipaje } from "../../src/organizacion/equipaje/equipaje.mjs";
+import { guardarPresupuesto, obtenerPresupuestoGuardado } from "../../src/organizacion/presupuesto/presupuesto.mjs";
+import { createFavoritosStore } from "../../src/recuerdos/favoritos/favoritos.mjs";
+import { guardarNota, listarNotas, limpiarNotas } from "../../src/recuerdos/notas/notas.mjs";
+import { readDashboardModel, renderDashboard } from "../../src/dashboard/dashboard.mjs";
+
+class LocalStorageMock {
+  #map = new Map();
+
+  clear() {
+    this.#map.clear();
+  }
+
+  getItem(key) {
+    return this.#map.has(key) ? this.#map.get(key) : null;
+  }
+
+  setItem(key, value) {
+    this.#map.set(key, String(value));
+  }
+
+  removeItem(key) {
+    this.#map.delete(key);
+  }
+}
+
+const STORAGE_PREFIX = "viaje-en-familia:v1";
+
+test.beforeEach(() => {
+  globalThis.localStorage = new LocalStorageMock();
+  limpiarNotas();
+});
+
+test.afterEach(() => {
+  delete globalThis.localStorage;
+});
+
+test("full trip integrates itinerary, organization and memories into a persistent dashboard", () => {
+  const journeyStore = createStore("e2e/full-trip");
+  journeyStore.set({ tripName: "Verano 2026", ready: true });
+
+  const madrid = addParada({
+    id: "madrid",
+    nombre: "Madrid",
+    fechaInicio: "2026-09-01",
+    fechaFin: "2026-09-03",
+    descripcion: "Llegada y paseo"
+  });
+  const toledo = addParada({
+    id: "toledo",
+    nombre: "Toledo",
+    fechaInicio: "2026-09-04",
+    fechaFin: "2026-09-04",
+    descripcion: "Miradores"
+  });
+  const sevilla = addParada({
+    id: "sevilla",
+    nombre: "Sevilla",
+    fechaInicio: "2026-09-05",
+    fechaFin: "2026-09-07",
+    descripcion: "Centro historico"
+  });
+
+  assert.deepEqual(listParadas(), [madrid, toledo, sevilla]);
+  assert.deepEqual(explorarParadas({ query: "villa" }), [sevilla]);
+  assert.deepEqual(buscarParadas("tole"), [toledo]);
+
+  assert.deepEqual(reorderParadas(["sevilla", "madrid"]), [sevilla, madrid, toledo]);
+  assert.deepEqual(listParadas(), [sevilla, madrid, toledo]);
+
+  const madridDesayuno = addActividad({
+    id: "madrid-desayuno",
+    fecha: "2026-09-02",
+    paradaId: "madrid",
+    horario: "08:30",
+    estado: "pendiente"
+  });
+  const sevillaCena = addActividad({
+    id: "sevilla-cena",
+    fecha: "2026-09-05",
+    paradaId: "sevilla",
+    horario: "20:00",
+    estado: "completada"
+  });
+
+  assert.deepEqual(listActividades(), [madridDesayuno, sevillaCena]);
+  assert.deepEqual(buscarActividades("sevilla"), [sevillaCena]);
+  assert.deepEqual(explorarActividades({ paradaId: "madrid" }), [madridDesayuno]);
+
+  const resumenPresupuesto = guardarPresupuesto({
+    total: 1000,
+    gastos: [
+      { categoria: "Alojamiento", gasto: 650 },
+      { categoria: "Comida", gasto: 170 }
+    ]
+  });
+
+  const checklist = crearChecklistEquipaje();
+  const pasaporte = checklist.agregarEquipaje("Pasaporte");
+  const cargador = checklist.agregarEquipaje("Cargador");
+  checklist.completarEquipaje(pasaporte.id);
+
+  const favoritos = createFavoritosStore();
+  const lugar = favoritos.marcarFavorito({
+    id: "museo",
+    tipo: "lugar",
+    nombre: "Museo de los Ninos"
+  });
+  const notaDia = guardarNota({
+    id: "nota-dia-1",
+    texto: "Llevar abrigo",
+    diaId: "dia-2026-09-02"
+  });
+  const notaParada = guardarNota({
+    id: "nota-parada-1",
+    texto: "Comprar agua",
+    paradaId: "sevilla"
+  });
+
+  const dashboard = readDashboardModel();
+  const html = renderDashboard(dashboard);
+
+  assert.deepEqual(resumenPresupuesto, obtenerPresupuestoGuardado());
+  assert.deepEqual(checklist.get().items, [pasaporte, cargador]);
+  assert.deepEqual(checklist.obtenerEquipajeFiltrado(), [cargador]);
+  assert.deepEqual(favoritos.listarFavoritos(), [lugar]);
+  assert.deepEqual(listarNotas(), [notaDia, notaParada]);
+
+  assert.deepEqual(dashboard.paradas, [sevilla, madrid, toledo]);
+  assert.deepEqual(dashboard.upcomingEvents, [
+    {
+      id: "madrid-desayuno",
+      title: "08:30 · Madrid",
+      subtitle: "miércoles 2 sep 2026",
+      state: "Pendiente"
+    },
+    {
+      id: "sevilla-cena",
+      title: "20:00 · Sevilla",
+      subtitle: "sábado 5 sep 2026",
+      state: "Completada"
+    }
+  ]);
+  assert.deepEqual(dashboard.budget, resumenPresupuesto);
+  assert.equal(dashboard.luggage.progress.porcentaje, 50);
+  assert.equal(dashboard.memories.favoriteItems[0].label, "Museo de los Ninos");
+  assert.equal(dashboard.memories.noteItems[0].meta, "Día dia-2026-09-02");
+  assert.equal(dashboard.memories.noteItems[1].meta, "Parada Sevilla");
+
+  assert.match(html, /Dashboard del viaje/);
+  assert.match(html, /Itinerario/);
+  assert.match(html, /Organización/);
+  assert.match(html, /Recuerdos destacados/);
+  assert.match(html, /Madrid/);
+  assert.match(html, /Sevilla/);
+  assert.match(html, /Cerca del límite/);
+  assert.match(html, /Pasaporte/);
+  assert.match(html, /Museo de los Ninos/);
+  assert.match(html, /Llevar abrigo/);
+
+  assert.equal(
+    globalThis.localStorage.getItem(`${STORAGE_PREFIX}:e2e/full-trip`),
+    JSON.stringify({ tripName: "Verano 2026", ready: true })
+  );
+  assert.equal(
+    globalThis.localStorage.getItem(`${STORAGE_PREFIX}:itinerary/paradas`),
+    JSON.stringify([sevilla, madrid, toledo])
+  );
+  assert.equal(
+    globalThis.localStorage.getItem(`${STORAGE_PREFIX}:itinerary/agenda`),
+    JSON.stringify([madridDesayuno, sevillaCena])
+  );
+  assert.equal(
+    globalThis.localStorage.getItem(`${STORAGE_PREFIX}:organizacion/presupuesto`),
+    JSON.stringify({
+      total: 1000,
+      gastos: [
+        { categoria: "Alojamiento", gasto: 650 },
+        { categoria: "Comida", gasto: 170 }
+      ]
+    })
+  );
+  assert.equal(
+    globalThis.localStorage.getItem(`${STORAGE_PREFIX}:organizacion/equipaje`),
+    JSON.stringify(checklist.get())
+  );
+  assert.equal(
+    globalThis.localStorage.getItem(`${STORAGE_PREFIX}:recuerdos/favoritos`),
+    JSON.stringify([lugar])
+  );
+  assert.equal(
+    globalThis.localStorage.getItem(`${STORAGE_PREFIX}:recuerdos/notas`),
+    JSON.stringify([notaDia, notaParada])
+  );
+});

