+import assert from "node:assert/strict";
+import test from "node:test";
+
+import { addActividad } from "../../src/itinerary/agenda/agenda.mjs";
+import { addParada, reorderParadas } from "../../src/itinerary/paradas/paradas.mjs";
+import { createChecklistEquipaje } from "../../src/organizacion/equipaje/equipaje.mjs";
+import { guardarPresupuesto } from "../../src/organizacion/presupuesto/presupuesto.mjs";
+import { createFavoritosStore } from "../../src/recuerdos/favoritos/favoritos.mjs";
+import { guardarNota, limpiarNotas } from "../../src/recuerdos/notas/notas.mjs";
+import { mountDashboard, readDashboardModel, renderDashboard } from "../../src/dashboard/dashboard.mjs";
+
+class LocalStorageMock {
+  #map = new Map();
+
+  clear() {
+    this.#map.clear();
+  }
+
+  getItem(key) {
+    return this.#map.has(key) ? this.#map.get(key) : null;
+  }
+
+  setItem(key, value) {
+    this.#map.set(key, String(value));
+  }
+
+  removeItem(key) {
+    this.#map.delete(key);
+  }
+}
+
+const STORAGE_KEYS = {
+  itineraryParadas: "viaje-en-familia:v1:itinerary/paradas",
+  itineraryAgenda: "viaje-en-familia:v1:itinerary/agenda",
+  organizacionPresupuesto: "viaje-en-familia:v1:organizacion/presupuesto",
+  organizacionEquipaje: "viaje-en-familia:v1:organizacion/equipaje",
+  recuerdosFavoritos: "viaje-en-familia:v1:recuerdos/favoritos",
+  recuerdosNotas: "viaje-en-familia:v1:recuerdos/notas"
+};
+
+test.beforeEach(() => {
+  globalThis.localStorage = new LocalStorageMock();
+  limpiarNotas();
+});
+
+test.afterEach(() => {
+  delete globalThis.localStorage;
+});
+
+test("full trip integrates itinerary, organization and memories into the persistent dashboard", () => {
+  const rosario = addParada({
+    id: "rosario",
+    nombre: "Rosario",
+    fechaInicio: "2026-09-01",
+    fechaFin: "2026-09-02",
+    descripcion: "Inicio del viaje"
+  });
+  const cordoba = addParada({
+    id: "cordoba",
+    nombre: "Córdoba",
+    fechaInicio: "2026-09-03",
+    fechaFin: "2026-09-04",
+    descripcion: "Escala central"
+  });
+
+  assert.deepEqual(reorderParadas(["cordoba", "rosario"]), [cordoba, rosario]);
+
+  const desayuno = addActividad({
+    id: "cordoba-desayuno",
+    fecha: "2026-09-03",
+    paradaId: "cordoba",
+    horario: "08:30",
+    estado: "pendiente"
+  });
+  const cierre = addActividad({
+    id: "rosario-cierre",
+    fecha: "2026-09-02",
+    paradaId: "rosario",
+    horario: "19:00",
+    estado: "completada"
+  });
+
+  const presupuesto = guardarPresupuesto({
+    total: 1500,
+    gastos: [
+      { categoria: "Alojamiento", gasto: 900 },
+      { categoria: "Comida", gasto: 240 }
+    ]
+  });
+
+  const equipaje = createChecklistEquipaje();
+  const pasaportes = equipaje.agregarEquipaje("Pasaportes");
+  const cargador = equipaje.agregarEquipaje("Cargador");
+  equipaje.completarEquipaje(pasaportes.id);
+
+  const favoritos = createFavoritosStore();
+  const favorito = { id: "plaza-principal", tipo: "lugar", nombre: "Plaza Principal" };
+  favoritos.marcarFavorito(favorito);
+
+  const nota = guardarNota({
+    id: "nota-cordoba",
+    texto: "Comprar agua antes de salir",
+    paradaId: "cordoba"
+  });
+
+  const model = readDashboardModel();
+
+  assert.deepEqual(model.paradas, [rosario, cordoba]);
+  assert.deepEqual(model.upcomingEvents, [
+    {
+      id: "rosario-cierre",
+      title: "19:00 · Rosario",
+      subtitle: "miércoles 2 sep 2026",
+      state: "Completada"
+    },
+    {
+      id: "cordoba-desayuno",
+      title: "08:30 · Córdoba",
+      subtitle: "jueves 3 sep 2026",
+      state: "Pendiente"
+    }
+  ]);
+  assert.equal(model.budget.total, 1500);
+  assert.equal(model.budget.gastado, 1140);
+  assert.equal(model.budget.disponible, 360);
+  assert.equal(model.luggage.progress.total, 2);
+  assert.equal(model.luggage.progress.completados, 1);
+  assert.equal(model.luggage.progress.porcentaje, 50);
+  assert.deepEqual(model.memories.favoriteItems, [
+    {
+      id: "fav-plaza-principal",
+      label: "Plaza Principal",
+      meta: "lugar"
+    }
+  ]);
+  assert.deepEqual(model.memories.noteItems, [
+    {
+      id: "note-nota-cordoba",
+      label: "Comprar agua antes de salir",
+      meta: "Parada Córdoba"
+    }
+  ]);
+
+  const html = renderDashboard(model);
+  assert.match(html, /Dashboard del viaje/);
+  assert.match(html, /Itinerario/);
+  assert.match(html, /Organización/);
+  assert.match(html, /Recuerdos/);
+  assert.match(html, /Rosario/);
+  assert.match(html, /Córdoba/);
+  assert.match(html, /Plaza Principal/);
+  assert.match(html, /Comprar agua antes de salir/);
+
+  const root = { innerHTML: "" };
+  const mounted = mountDashboard(root, model);
+
+  assert.equal(root.innerHTML.includes("data-dashboard-view"), true);
+  assert.equal(mounted.tripRange.label, "1 sep 2026 al 4 sep 2026");
+
+  assert.equal(
+    globalThis.localStorage.getItem(STORAGE_KEYS.itineraryParadas),
+    JSON.stringify([rosario, cordoba])
+  );
+  assert.equal(
+    globalThis.localStorage.getItem(STORAGE_KEYS.itineraryAgenda),
+    JSON.stringify([desayuno, cierre])
+  );
+  assert.equal(
+    globalThis.localStorage.getItem(STORAGE_KEYS.organizacionPresupuesto),
+    JSON.stringify({
+      total: 1500,
+      gastos: [
+        { categoria: "Alojamiento", gasto: 900 },
+        { categoria: "Comida", gasto: 240 }
+      ]
+    })
+  );
+  assert.equal(
+    globalThis.localStorage.getItem(STORAGE_KEYS.organizacionEquipaje),
+    JSON.stringify(equipaje.get())
+  );
+  assert.equal(
+    globalThis.localStorage.getItem(STORAGE_KEYS.recuerdosFavoritos),
+    JSON.stringify([favorito])
+  );
+  assert.equal(
+    globalThis.localStorage.getItem(STORAGE_KEYS.recuerdosNotas),
+    JSON.stringify([nota])
+  );
+  assert.deepEqual(equipaje.obtenerEquipajeFiltrado(), [cargador]);
+});

