    notasStoreInstance = createStore("recuerdos/notas");
  }

  return notasStoreInstance;
}

function leerNotas() {
  return getNotasStore().get() ?? [];
}

function esCadenaNoVacia(valor) {
  return typeof valor === "string" && valor.trim().length > 0;
}

function normalizarNota(nota) {
  if (nota === null || typeof nota !== "object" || Array.isArray(nota)) {
    throw new TypeError("La nota debe ser un objeto");
  }

  const texto = typeof nota.texto === "string" ? nota.texto.trim() : "";
  if (texto.length === 0) {
    throw new TypeError("La nota debe incluir texto");
  }

  const tieneDia = esCadenaNoVacia(nota.diaId);
  const tieneParada = esCadenaNoVacia(nota.paradaId);

  if (tieneDia === tieneParada) {
    throw new TypeError("La nota debe asociarse a un día o a una parada");
  }

  return {
    id: esCadenaNoVacia(nota.id) ? nota.id.trim() : crypto.randomUUID(),
    texto,
    ...(tieneDia ? { diaId: nota.diaId.trim() } : { paradaId: nota.paradaId.trim() })
  };
}

export function listarNotas() {
  return leerNotas();
}

export function listarNotasPorDia(diaId) {
  if (!esCadenaNoVacia(diaId)) {
    return [];
  }

  return leerNotas().filter((nota) => nota.diaId === diaId.trim());
}

export function listarNotasPorParada(paradaId) {
  if (!esCadenaNoVacia(paradaId)) {
    return [];
  }

  return leerNotas().filter((nota) => nota.paradaId === paradaId.trim());
}

export function guardarNota(nota) {
  const nuevaNota = normalizarNota(nota);
  const notas = leerNotas();
  const index = notas.findIndex(({ id }) => id === nuevaNota.id);

  if (index === -1) {
    const siguientes = [...notas, nuevaNota];
    getNotasStore().set(siguientes);
    return nuevaNota;
  }

  const siguientes = [...notas];
  siguientes[index] = nuevaNota;
  getNotasStore().set(siguientes);
  return nuevaNota;
}

export function limpiarNotas() {
  getNotasStore().set([]);
}

export const notasStore = {
  get() {
    return getNotasStore().get();
  },
  set(value) {
    return getNotasStore().set(value);
  },
  subscribe(listener) {
    return getNotasStore().subscribe(listener);
  }
};

export default {
  notasStore,
  guardarNota,
  listarNotas,
  listarNotasPorDia,
  listarNotasPorParada,
  limpiarNotas
};

