const storageKey = "viaje-en-familia:v1";

const stores = new Map();
let storageInstance;

function getLocalStorage() {
  const { localStorage } = globalThis;
  if (!localStorage) {
    throw new Error("localStorage is not available");
  }
  return localStorage;
}

function getStorageInstance() {
  const current = getLocalStorage();
  if (current !== storageInstance) {
    stores.clear();
    storageInstance = current;
  }

  return current;
}

function readValue(key) {
  const raw = getStorageInstance().getItem(key);
  if (raw === null) {
    return undefined;
  }

  try {
    return JSON.parse(raw);
  } catch {
    return undefined;
  }
}

function writeValue(key, value) {
  const storage = getStorageInstance();
  if (value === undefined) {
    storage.removeItem(key);
    return;
  }

  storage.setItem(key, JSON.stringify(value));
}

function createState(key) {
  const keyName = `${storageKey}:${key}`;
  const listeners = new Set();

  const store = {
    get() {
      return readValue(keyName);
    },
    set(value) {
      writeValue(keyName, value);
      for (const listener of listeners) {
        listener(value);
      }
    },
    subscribe(listener) {
      listeners.add(listener);
      return () => {
        listeners.delete(listener);
      };
    }
  };

  return store;
}

export function createStore(key) {
  getStorageInstance();
  if (!stores.has(key)) {
    stores.set(key, createState(key));
  }

  return stores.get(key);
}

